@import "tailwindcss";

/* Self-hosted brand fonts (no Google Fonts request at runtime) */
@import "@fontsource/space-grotesk/500.css";
@import "@fontsource/space-grotesk/600.css";
@import "@fontsource/space-grotesk/700.css";
@import "@fontsource/barlow/400.css";
@import "@fontsource/barlow/500.css";
@import "@fontsource/barlow/600.css";
@import "@fontsource/barlow/400-italic.css";
@import "@fontsource/bebas-neue/400.css";

/* ─────────────────────────────────────────────
   EVERY DETAIL DESIGN TOKENS
   paper  — cream base, most of the site
   paper2 — alternate section tone
   sand   — warm beige accent surfaces
   ink    — text and the one dark section
   muted  — secondary text (AA on paper and paper2)
   red    — actions only (buttons, active states, links)
   oxblood — brand surfaces: footer, final CTA, recommended marker
   ───────────────────────────────────────────── */
@theme {
  --color-paper: #f3f1ec;
  --color-paper2: #ebe6dd;
  --color-sand: #dbc7b3;
  --color-ink: #111111;
  --color-muted: #666666;
  --color-red: #b8363d;
  --color-red-hover: #9f2c33;
  --color-oxblood: #590d07;
  --color-line: rgb(17 17 17 / 0.14);

  --font-display: "Space Grotesk", ui-sans-serif, system-ui, sans-serif;
  --font-body: "Barlow", ui-sans-serif, system-ui, sans-serif;
  --font-numeral: "Bebas Neue", "Space Grotesk", ui-sans-serif, sans-serif;

  --radius-photo: 3px;
  --radius-panel: 6px;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    scroll-padding-top: 5.5rem;
  }
  body {
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-body);
    font-size: 1.0625rem; /* 17px */
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  h1, h2, h3, h4 {
    font-family: var(--font-display);
    font-weight: 600;
    letter-spacing: -0.015em;
    line-height: 1.1;
    text-wrap: balance;
  }
  p { text-wrap: pretty; }
  fieldset { min-width: 0; } /* fieldsets otherwise refuse to shrink below their content */
  ::selection { background: var(--color-sand); color: var(--color-ink); }

  :focus-visible {
    outline: 2px solid var(--color-red);
    outline-offset: 3px;
    border-radius: 2px;
  }
  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }
}

@layer components {
  .container-ed {
    width: 100%;
    max-width: 76rem;
    margin-inline: auto;
    padding-inline: 1.25rem;
  }
  @media (min-width: 768px) {
    .container-ed { padding-inline: 2rem; }
  }

  /* Type scale */
  /* Display type is Bebas Neue — the face Every Detail already uses for headlines and prices */
  .t-display { font-family: var(--font-numeral); font-weight: 400; font-size: clamp(4rem, 12vw, 8.5rem); letter-spacing: 0.005em; line-height: 0.86; }
  .t-page { font-family: var(--font-numeral); font-weight: 400; font-size: clamp(3rem, 7.5vw, 6.25rem); letter-spacing: 0.005em; line-height: 0.88; }
  .t-h2 { font-family: var(--font-numeral); font-weight: 400; font-size: clamp(2.75rem, 6vw, 4.5rem); letter-spacing: 0.01em; line-height: 0.9; }
  .t-h3 { font-size: 1.375rem; letter-spacing: -0.015em; line-height: 1.2; }
  .t-lede { font-size: clamp(1.125rem, 1.6vw, 1.3rem); line-height: 1.55; color: var(--color-ink); max-width: 38rem; }
  .t-small { font-size: 0.9375rem; line-height: 1.55; }
  .t-numeral { font-family: var(--font-numeral); letter-spacing: 0.01em; line-height: 0.9; font-weight: 400; }

  /* Section kicker: used only where it names the section's job (not above every heading) */
  .kicker {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 0.9375rem;
    color: var(--color-oxblood);
  }

  /* Buttons — hard offset shadow, lifted from the existing Every Detail pages */
  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    min-height: 3.25rem;
    padding: 0.8rem 1.6rem 0.7rem;
    border-radius: 999px;
    border: 2px solid var(--color-ink);
    box-shadow: 4px 4px 0 var(--color-ink);
    font-family: var(--font-numeral);
    font-weight: 400;
    font-size: 1.375rem;
    letter-spacing: 0.04em;
    line-height: 1;
    text-decoration: none;
    transition: transform 120ms var(--ease-out), box-shadow 120ms var(--ease-out), background-color 150ms;
    -webkit-tap-highlight-color: transparent;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .btn:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--color-ink); }
  }
  .btn:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--color-ink); }
  .btn-primary { background: var(--color-red); color: #fff; }
  .btn-secondary { background: var(--color-paper); color: var(--color-ink); }
  .btn-on-dark { background: var(--color-paper); color: var(--color-ink); border-color: var(--color-paper); box-shadow: 4px 4px 0 var(--color-red); }
  @media (hover: hover) and (pointer: fine) {
    .btn-on-dark:hover { box-shadow: 6px 6px 0 var(--color-red); }
  }
  .btn-on-dark:active { box-shadow: 1px 1px 0 var(--color-red); }
  .btn-outline-on-dark { background: transparent; color: var(--color-paper); border-color: var(--color-paper); box-shadow: none; }
  @media (hover: hover) and (pointer: fine) {
    .btn-outline-on-dark:hover { box-shadow: none; transform: none; background: rgb(243 241 236 / 0.1); }
  }
  .btn-outline-on-dark:active { box-shadow: none; }
  .btn-sm { min-height: 2.75rem; padding: 0.55rem 1.1rem 0.45rem; font-size: 1.2rem; box-shadow: 3px 3px 0 var(--color-ink); }

  /* Panels: ink border + offset shadow. Used for the few things that deserve a frame. */
  .panel { background: #fff; border: 2px solid var(--color-ink); border-radius: 10px; box-shadow: 6px 6px 0 var(--color-ink); }
  .panel-red { box-shadow: 6px 6px 0 var(--color-red); }

  /* Double rule — the divider from the current ceramic page */
  .rule-double { height: 6px; border-top: 2px solid var(--color-ink); border-bottom: 1px solid var(--color-ink); }

  /* Inline text link */
  .link {
    color: var(--color-ink);
    text-decoration: underline;
    text-decoration-color: var(--color-red);
    text-decoration-thickness: 2px;
    text-underline-offset: 4px;
    transition: color 150ms;
  }
  .link:hover { color: var(--color-red); }

  /* Dotted leader between a name and a price, like a printed rate card */
  .leader {
    flex: 1;
    min-width: 1.5rem;
    border-bottom: 2px dotted rgb(17 17 17 / 0.28);
    transform: translateY(-0.35em);
  }

  /* Forms */
  .field-label { display: block; font-family: var(--font-display); font-weight: 600; font-size: 0.9375rem; margin-bottom: 0.375rem; }
  .field-hint { font-weight: 400; color: var(--color-muted); font-family: var(--font-body); }
  .field {
    width: 100%;
    min-height: 3.25rem;
    padding: 0.75rem 0.95rem;
    background: #fff;
    border: 1.5px solid rgb(17 17 17 / 0.22);
    border-radius: var(--radius-panel);
    font: inherit;
    font-size: 1rem; /* 16px+ prevents iOS zoom */
    color: var(--color-ink);
    transition: border-color 150ms;
  }
  .field:hover { border-color: rgb(17 17 17 / 0.4); }
  .field:focus { outline: none; border-color: var(--color-ink); box-shadow: 0 0 0 3px rgb(184 54 61 / 0.25); }
  .field[aria-invalid="true"] { border-color: var(--color-red); }
  textarea.field { min-height: 7.5rem; resize: vertical; }
  .field-error { color: var(--color-red); font-size: 0.9375rem; margin-top: 0.375rem; }

  /* Selectable option tiles (vehicle, service, plan builder) */
  .choice {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 3.75rem;
    padding: 0.75rem 1rem;
    border: 2px solid rgb(17 17 17 / 0.16);
    border-radius: 10px;
    background: rgb(255 255 255 / 0.55);
    cursor: pointer;
    text-align: left;
    transition: border-color 150ms, background-color 150ms;
  }
  .choice:hover { border-color: rgb(17 17 17 / 0.5); }
  .choice[aria-checked="true"],
  .choice[aria-pressed="true"],
  .choice:has(input:checked) {
    border-color: var(--color-ink);
    background: #fff;
    box-shadow: 3px 3px 0 var(--color-ink);
  }
  .choice:has(input:focus-visible) { outline: 2px solid var(--color-red); outline-offset: 2px; }

  /* Long-form article body */
  .prose-ed { font-size: 1.125rem; line-height: 1.7; max-width: 42rem; }
  .prose-ed > * + * { margin-top: 1.1em; }
  .prose-ed h2 { font-size: 1.75rem; margin-top: 2em; }
  .prose-ed h3 { font-size: 1.3rem; margin-top: 1.6em; }
  .prose-ed ul { list-style: disc; padding-left: 1.25em; }
  .prose-ed ol { list-style: decimal; padding-left: 1.25em; }
  .prose-ed li + li { margin-top: 0.4em; }
  .prose-ed a { text-decoration: underline; text-decoration-color: var(--color-red); text-underline-offset: 3px; }
  .prose-ed img { border-radius: var(--radius-photo); }
  .prose-ed blockquote { border-left: 3px solid var(--color-sand); padding-left: 1rem; color: var(--color-muted); }
  .prose-ed strong { font-weight: 600; }
}

/* Accordion (native <details> — crawlable and keyboard accessible by default) */
.faq summary { list-style: none; cursor: pointer; }
.faq summary::-webkit-details-marker { display: none; }
.faq .faq-icon { transition: transform 200ms var(--ease-out); }
.faq details[open] .faq-icon { transform: rotate(45deg); }
.faq details[open] > div { animation: faq-open 220ms var(--ease-out); }
@keyframes faq-open { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

/* Hero: the one orchestrated load moment */
@keyframes rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.rise { animation: rise 700ms var(--ease-out) both; }
.rise-2 { animation-delay: 90ms; }
.rise-3 { animation-delay: 180ms; }
.rise-4 { animation-delay: 270ms; }

/* 2026 readability refinement: quieter UI, stronger hierarchy, fewer decorative effects. */
@layer components {
  .t-display { font-family: var(--font-display); font-weight: 600; font-size: clamp(3.1rem, 7vw, 6.25rem); letter-spacing: -0.045em; line-height: 0.98; }
  .t-page { font-family: var(--font-display); font-weight: 600; font-size: clamp(2.75rem, 6vw, 5rem); letter-spacing: -0.04em; line-height: 1; }
  .t-h2 { font-family: var(--font-display); font-weight: 600; font-size: clamp(2.1rem, 4vw, 3.5rem); letter-spacing: -0.035em; line-height: 1.05; }
  .t-numeral { font-family: var(--font-display); font-weight: 600; letter-spacing: -0.03em; line-height: 1; }
  .btn { min-height: 3rem; padding: .72rem 1.25rem; border: 1.5px solid var(--color-ink); border-radius: .55rem; box-shadow: none; font-family: var(--font-display); font-size: 1rem; font-weight: 600; letter-spacing: 0; }
  .btn:hover { transform: none !important; box-shadow: none !important; }
  .btn:active { transform: none; box-shadow: none; }
  .btn-on-dark { box-shadow: none; }
  .btn-sm { min-height: 2.6rem; padding: .6rem 1rem; font-size: .9375rem; box-shadow: none; }
  .panel, .panel-red { border: 1px solid var(--color-line); border-radius: .8rem; box-shadow: none; }
}

/* ─────────────────────────────────────────────
   HOMEPAGE V3: clean Apple-like restraint + retro Every Detail character
   ───────────────────────────────────────────── */
.hero-full {
  position: relative;
  min-height: 100svh;
  overflow: hidden;
  background-image: url('/images/hero.webp');
  background-size: cover;
  background-position: center 52%;
  background-color: #1b1b1b;
  color: var(--color-paper);
}
.hero-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgb(0 0 0 / .68) 0%, rgb(0 0 0 / .36) 45%, rgb(0 0 0 / .08) 72%), linear-gradient(0deg, rgb(0 0 0 / .42) 0%, transparent 45%);
}
.hero-inner { position: relative; min-height: 100svh; display: flex; align-items: flex-end; padding-top: 8rem; padding-bottom: clamp(3.5rem, 8vh, 6.5rem); }
.hero-copy { width: min(46rem, 92%); }
.hero-kicker, .eyebrow { font-family: var(--font-display); font-size: .78rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.hero-kicker { margin-bottom: 1rem; color: rgb(255 255 255 / .8); }
.hero-title { font-family: var(--font-display); font-size: clamp(3.7rem, 8.8vw, 7.7rem); font-weight: 600; letter-spacing: -.055em; line-height: .88; color: #fff; }
.hero-lede { max-width: 39rem; margin-top: 1.4rem; font-size: clamp(1.05rem, 1.7vw, 1.3rem); line-height: 1.5; color: rgb(255 255 255 / .88); }
.hero-proof { position: absolute; right: 2rem; bottom: clamp(3.5rem, 8vh, 6.5rem); display: flex; align-items: center; gap: .55rem; font-size: .9rem; font-weight: 600; }
.glass-pill, .btn-glass { background: rgb(255 255 255 / .13); border: 1px solid rgb(255 255 255 / .32); backdrop-filter: blur(20px) saturate(150%); -webkit-backdrop-filter: blur(20px) saturate(150%); box-shadow: inset 0 1px 0 rgb(255 255 255 / .18), 0 10px 30px rgb(0 0 0 / .13); }
.btn-glass { color: #fff; border-color: rgb(255 255 255 / .48); box-shadow: 4px 4px 0 rgb(0 0 0 / .55), inset 0 1px 0 rgb(255 255 255 / .2); }
.btn-glass:hover { box-shadow: 6px 6px 0 rgb(0 0 0 / .55), inset 0 1px 0 rgb(255 255 255 / .2) !important; }
.proof-row { border-bottom: 1px solid var(--color-line); background: rgb(243 241 236 / .94); font-family: var(--font-display); font-size: .78rem; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; }
.section-space { padding-top: clamp(5rem, 9vw, 8.5rem); padding-bottom: clamp(5rem, 9vw, 8.5rem); }
.section-intro { max-width: 48rem; }
.eyebrow { margin-bottom: .85rem; color: var(--color-red); }
.clean-heading { font-family: var(--font-display); font-size: clamp(2.6rem, 5.5vw, 5.2rem); font-weight: 600; letter-spacing: -.05em; line-height: .98; }
.section-intro > p:last-child { max-width: 39rem; margin-top: 1.25rem; font-size: 1.1rem; color: rgb(17 17 17 / .68); }
.work-story { background: #e9e5dd; border-block: 1px solid var(--color-line); }
.editorial-photo { border-radius: 18px; box-shadow: 0 18px 50px rgb(17 17 17 / .08); }
.editorial-photo-wide { border-radius: 22px; }
.more-section, .faq-home { background: #e9e5dd; border-block: 1px solid var(--color-line); }
.feature-card { min-height: 18rem; padding: 2rem; display: grid; grid-template-columns: auto 1fr auto; align-items: end; gap: 1.5rem; border: 1px solid rgb(17 17 17 / .15); border-radius: 22px; background: rgb(255 255 255 / .46); backdrop-filter: blur(18px) saturate(130%); transition: transform 220ms var(--ease-out), background 220ms; }
.feature-card:hover { transform: translateY(-4px); background: rgb(255 255 255 / .72); }
.feature-card h3 { font-size: clamp(2rem, 4vw, 3.2rem); letter-spacing: -.04em; }
.feature-card p { max-width: 26rem; margin-top: .65rem; color: rgb(17 17 17 / .65); }
.feature-number { align-self: start; font-family: var(--font-numeral); font-size: 1.4rem; color: var(--color-red); }
.feature-arrow { font-size: 2rem; }
.review-feature { max-width: 58rem; margin-inline: auto; }
.review-feature blockquote { margin-top: 2rem; font-family: var(--font-display); font-size: clamp(1.8rem, 4vw, 3.5rem); font-weight: 500; letter-spacing: -.035em; line-height: 1.13; }
.review-meta { margin-top: 2rem; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; }
.final-book { background: var(--color-ink); color: var(--color-paper); }
.final-title { margin-top: 1rem; font-family: var(--font-display); font-size: clamp(3.2rem, 8vw, 7rem); font-weight: 600; letter-spacing: -.055em; line-height: .9; }

@media (max-width: 767px) {
  .hero-full, .hero-inner { min-height: 92svh; }
  .hero-full { background-position: 60% center; }
  .hero-shade { background: linear-gradient(0deg, rgb(0 0 0 / .76) 0%, rgb(0 0 0 / .32) 62%, rgb(0 0 0 / .2) 100%); }
  .hero-inner { padding-bottom: 2.5rem; }
  .hero-title { font-size: clamp(3.25rem, 16vw, 5.3rem); }
  .hero-proof { display: none; }
  .feature-card { min-height: 14rem; padding: 1.4rem; }
}

