.home-nav-shell { width:min(1180px,calc(100vw - 2.5rem));height:4.75rem;margin-inline:auto;padding:0 .85rem 0 1rem;border:1px solid rgb(255 255 255/.24);border-radius:1.25rem;background:rgb(20 22 17/.32);box-shadow:inset 0 1px 0 rgb(255 255 255/.14),0 14px 45px rgb(0 0 0/.16);backdrop-filter:blur(24px) saturate(145%);-webkit-backdrop-filter:blur(24px) saturate(145%); }
.home-nav-shell .btn-primary { box-shadow:3px 3px 0 rgb(0 0 0/.72); }
.home-nav-shell .btn-primary:hover { transform:translate(-1px,-1px)!important;box-shadow:5px 5px 0 rgb(0 0 0/.72)!important; }
.hero-full { background-position:center 50%; }
.hero-shade { background:radial-gradient(ellipse 72% 74% at 18% 76%,rgb(0 0 0/.68) 0%,rgb(0 0 0/.42) 39%,transparent 72%),linear-gradient(0deg,rgb(0 0 0/.30) 0%,transparent 38%); }
.hero-inner { align-items:flex-end;padding-top:9rem;padding-bottom:clamp(4.25rem,8vh,6rem); }
.hero-copy { width:min(51rem,76%); }
.hero-title { display:flex;flex-direction:column;gap:.02em;max-width:50rem;font-size:clamp(3.8rem,6.25vw,6.45rem);line-height:.92;letter-spacing:-.058em; }
.hero-title span { display:block;white-space:nowrap; }
.hero-lede { max-width:35rem;margin-top:1.25rem;font-size:clamp(1rem,1.2vw,1.16rem); }
.hero-kicker { margin-bottom:.9rem;font-size:.72rem; }
.hero-copy .btn-primary { box-shadow:4px 4px 0 rgb(0 0 0/.72); }
.hero-copy .btn-primary:hover { transform:translate(-1px,-1px)!important;box-shadow:6px 6px 0 rgb(0 0 0/.72)!important; }
.hero-copy .btn-glass:hover { transform:translate(-1px,-1px)!important; }
.proof-row { background:var(--color-paper); }
.proof-row > div { min-height:5.4rem;align-items:center; }
@media(max-width:1023px){.home-header{padding:.75rem .75rem 0}.home-nav-shell{width:calc(100vw - 1.5rem);height:4.25rem;border-radius:1rem}.hero-copy{width:min(42rem,88%)}.hero-title{font-size:clamp(3.5rem,8.4vw,5.8rem)}}
@media(max-width:767px){.hero-full{background-position:59% center}.hero-shade{background:linear-gradient(0deg,rgb(0 0 0/.78) 0%,rgb(0 0 0/.42) 47%,rgb(0 0 0/.08) 78%)}.hero-inner{padding-top:7rem;padding-bottom:2.6rem}.hero-copy{width:100%}.hero-title{font-size:clamp(3.05rem,14vw,4.8rem);line-height:.92}.hero-title span{white-space:normal}.hero-lede{max-width:31rem;font-size:1rem}.proof-row>div{min-height:auto;padding-top:1.6rem;padding-bottom:1.6rem}}

/* V5 above-the-fold precision: larger type, stronger glass, cleaner hierarchy */
@media (min-width: 1024px) {
  .home-header { padding-top: 1.15rem; }
  .home-nav-shell {
    width: min(1080px, calc(100vw - 3rem));
    height: 5.35rem;
    padding-inline: 1.15rem;
    border-color: rgb(255 255 255 / .34);
    background: rgb(19 22 17 / .46);
    box-shadow: inset 0 1px 0 rgb(255 255 255 / .22), 0 16px 48px rgb(0 0 0 / .18);
    backdrop-filter: blur(30px) saturate(160%);
    -webkit-backdrop-filter: blur(30px) saturate(160%);
  }
  .home-nav-shell nav a,
  .home-nav-shell nav button,
  .home-nav-shell > div > a:not(.btn) {
    font-size: 1.05rem;
  }
  .home-nav-shell .btn-sm {
    min-height: 3rem;
    padding: .72rem 1.15rem;
    font-size: 1.02rem;
  }
  .hero-inner {
    padding-bottom: clamp(4.75rem, 8vh, 6.75rem);
  }
  .hero-copy {
    width: min(62rem, 80%);
  }
  .hero-kicker {
    margin-bottom: 1.05rem;
    font-size: .9rem;
    letter-spacing: .13em;
  }
  .hero-title {
    max-width: 61rem;
    font-size: clamp(5.8rem, 7.35vw, 8.25rem);
    line-height: .9;
    letter-spacing: -.062em;
  }
  .hero-lede {
    max-width: 43rem;
    margin-top: 1.45rem;
    font-size: clamp(1.28rem, 1.45vw, 1.55rem);
    line-height: 1.45;
    color: rgb(255 255 255 / .94);
  }
  .hero-copy .btn {
    min-height: 3.65rem;
    padding: .9rem 1.45rem;
    font-size: 1.12rem;
  }
  .proof-row {
    font-size: .9rem;
    letter-spacing: .065em;
  }
  .proof-row > div {
    min-height: 6.25rem;
  }
}

@media (max-width: 1023px) and (min-width: 768px) {
  .hero-kicker { font-size: .82rem; }
  .hero-title { font-size: clamp(4.6rem, 9vw, 6.4rem); }
  .hero-lede { font-size: 1.2rem; max-width: 38rem; }
  .hero-copy .btn { font-size: 1.05rem; min-height: 3.35rem; }
  .proof-row { font-size: .84rem; }
}

@media (max-width: 767px) {
  .home-nav-shell { height: 4.7rem; }
