/* Branded page wipe. The panel covers first, navigation happens behind it,
   then the same panel continues off-screen. */
.route-transition {
  position: fixed;
  inset: 0;
  z-index: 9999;
  pointer-events: none;
  visibility: hidden;
  overflow: hidden;
}
.route-transition__panel {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--color-oxblood);
  transform: translate3d(-101%, 0, 0);
  will-change: transform;
}
.route-transition__logo {
  width: clamp(5.5rem, 9vw, 8.5rem);
  height: auto;
  opacity: 0;
  transform: scale(.9) rotate(-3deg);
  filter: brightness(0) invert(1);
}
.route-transition--cover,
.route-transition--reveal { visibility: visible; }
.route-transition--cover .route-transition__panel {
  animation: ed-cover 300ms cubic-bezier(.76,0,.24,1) forwards;
}
.route-transition--cover .route-transition__logo {
  animation: ed-logo-in 180ms 105ms ease-out forwards;
}
.route-transition--reveal .route-transition__panel {
  transform: translate3d(0,0,0);
  animation: ed-reveal 420ms cubic-bezier(.76,0,.24,1) forwards;
}
.route-transition--reveal .route-transition__logo {
  opacity: 1;
  transform: scale(1) rotate(0);
  animation: ed-logo-out 190ms ease-in forwards;
}
@keyframes ed-cover {
  from { transform: translate3d(-101%,0,0); }
  to { transform: translate3d(0,0,0); }
}
@keyframes ed-reveal {
  from { transform: translate3d(0,0,0); }
  to { transform: translate3d(101%,0,0); }
}
@keyframes ed-logo-in {
  to { opacity: 1; transform: scale(1) rotate(0); }
}
@keyframes ed-logo-out {
  to { opacity: 0; transform: scale(1.06) rotate(2deg); }
}
@media (prefers-reduced-motion: reduce) {
  .route-transition { display: none !important; }
}

