/* Quote recommender: the old three-step recommendation logic, rebuilt as a native site experience. */
.quote-rec-shell,
.quote-rec-result {
  max-width: 68rem;
  margin-inline: auto;
}
.quote-rec-progress {
  display: grid;
  grid-template-columns: auto 1fr auto 1fr auto;
  align-items: center;
  gap: .8rem;
  margin-bottom: 1.25rem;
  padding: .8rem 1rem;
  border: 1px solid var(--color-line);
  border-radius: .8rem;
  background: rgb(255 255 255 / .42);
  font-family: var(--font-display);
  font-size: .82rem;
  font-weight: 600;
}
.quote-rec-progress span { display: flex; align-items: center; gap: .5rem; color: var(--color-muted); white-space: nowrap; }
.quote-rec-progress span b { display: grid; width: 1.75rem; height: 1.75rem; place-items: center; border: 1px solid var(--color-line); border-radius: 999px; font-size: .7rem; }
.quote-rec-progress span.is-active { color: var(--color-ink); }
.quote-rec-progress span.is-active b { border-color: var(--color-red); color: var(--color-red); }
.quote-rec-progress span.is-done { color: var(--color-oxblood); }
.quote-rec-progress span.is-done b { border-color: var(--color-oxblood); background: var(--color-oxblood); color: #fff; }
.quote-rec-progress i { height: 1px; background: var(--color-line); }

.quote-rec-step {
  position: relative;
  display: grid;
  grid-template-columns: 5rem 1fr;
  gap: 1.5rem;
  margin-top: 1rem;
  padding: clamp(1.5rem, 4vw, 2.5rem);
  border: 1px solid var(--color-line);
  border-radius: 1rem;
  background: rgb(255 255 255 / .52);
  transition: opacity 180ms, background-color 180ms, border-color 180ms;
}
.quote-rec-step.is-active { border-color: rgb(17 17 17 / .32); background: #fff; }
.quote-rec-step.is-complete { background: rgb(255 255 255 / .72); }
.quote-rec-step.is-locked { opacity: .42; pointer-events: none; }
.quote-rec-step-number { font-family: var(--font-numeral); font-size: clamp(2.6rem, 5vw, 4.5rem); line-height: .9; color: var(--color-sand); }
.quote-rec-step-content { min-width: 0; }
.quote-rec-step-content h2 { margin-top: .25rem; font-size: clamp(1.65rem, 3vw, 2.55rem); letter-spacing: -.04em; }
.quote-rec-step-lede { margin-top: .35rem; color: var(--color-muted); font-size: .95rem; }

.quote-rec-search-wrap { position: relative; max-width: 42rem; margin-top: 1.4rem; }
.quote-rec-search { min-height: 3.75rem; font-size: 1.05rem; }
.quote-rec-search-results { position: absolute; z-index: 20; top: calc(100% + .4rem); left: 0; right: 0; overflow: hidden; border: 1px solid rgb(17 17 17 / .25); border-radius: .75rem; background: #fff; box-shadow: 0 18px 45px rgb(17 17 17 / .12); }
.quote-rec-search-results button { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 1rem; padding: .8rem 1rem; border-bottom: 1px solid var(--color-line); text-align: left; cursor: pointer; }
.quote-rec-search-results button:last-child { border-bottom: 0; }
.quote-rec-search-results button:hover { background: var(--color-paper); }
.quote-rec-search-results button small { color: var(--color-muted); font-size: .75rem; white-space: nowrap; }
.quote-rec-search-results p { padding: 1rem; color: var(--color-muted); font-size: .9rem; }
.quote-rec-selected { display: flex; max-width: 42rem; align-items: center; justify-content: space-between; gap: 1rem; margin-top: 1.35rem; padding: 1rem 1.1rem; border: 1px solid var(--color-line); border-radius: .75rem; background: var(--color-paper); }
.quote-rec-selected div { display: flex; flex-direction: column; }
.quote-rec-selected strong { font-family: var(--font-display); font-size: 1.1rem; }
.quote-rec-selected span { color: var(--color-muted); font-size: .85rem; }
.quote-rec-selected button { color: var(--color-red); font-family: var(--font-display); font-weight: 600; cursor: pointer; }

.quote-rec-condition-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: .6rem; margin-top: 1.4rem; }
.quote-rec-condition-grid button { min-height: 6.3rem; padding: .85rem .65rem; border: 1px solid var(--color-line); border-radius: .7rem; background: var(--color-paper); text-align: left; cursor: pointer; transition: border-color 150ms, background-color 150ms; }
.quote-rec-condition-grid button span { display: block; color: var(--color-muted); font-family: var(--font-numeral); font-size: 1.1rem; }
.quote-rec-condition-grid button strong { display: block; margin-top: .8rem; font-family: var(--font-display); font-size: .95rem; }
.quote-rec-condition-grid button.is-selected { border-color: var(--color-red); background: rgb(184 54 61 / .07); box-shadow: inset 0 -3px 0 var(--color-red); }
.quote-rec-condition-desc { min-height: 1.6rem; margin-top: .9rem; color: var(--color-muted); font-size: .9rem; }

.quote-rec-concern-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .65rem; margin-top: 1.3rem; }
.quote-rec-concern-grid button { display: grid; grid-template-columns: 1.5rem 1fr; align-items: center; gap: .75rem; padding: .9rem 1rem; border: 1px solid var(--color-line); border-radius: .7rem; background: var(--color-paper); text-align: left; cursor: pointer; }
.quote-rec-concern-grid button.is-selected { border-color: var(--color-red); background: rgb(184 54 61 / .07); }
.quote-rec-concern-grid button > span:last-child { display: flex; min-width: 0; flex-direction: column; }
.quote-rec-concern-grid strong { font-family: var(--font-display); font-size: .95rem; }
.quote-rec-concern-grid small { margin-top: .1rem; color: var(--color-muted); font-size: .78rem; }
.quote-rec-check { display: grid; width: 1.3rem; height: 1.3rem; place-items: center; border: 1px solid rgb(17 17 17 / .28); border-radius: .25rem; color: #fff; font-size: .75rem; }
.is-selected > .quote-rec-check, .quote-rec-addon.is-selected .quote-rec-check { border-color: var(--color-red); background: var(--color-red); }
.quote-rec-build { margin-top: 1.4rem; }

.quote-rec-back { margin-bottom: 1rem; color: var(--color-muted); font-family: var(--font-display); font-size: .9rem; font-weight: 600; cursor: pointer; }
.quote-rec-back:hover { color: var(--color-red); }
.quote-rec-result-grid { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(15rem, .7fr); overflow: hidden; border: 1px solid var(--color-line); border-radius: 1rem; background: #fff; }
.quote-rec-result-main { padding: clamp(1.6rem, 4vw, 3rem); }
.quote-rec-result-main h2 { margin-top: .35rem; font-family: var(--font-numeral); font-size: clamp(3.5rem, 8vw, 7rem); font-weight: 400; line-height: .88; letter-spacing: .01em; }
.quote-rec-why { max-width: 46rem; margin-top: 1.3rem; color: rgb(17 17 17 / .72); font-size: .98rem; line-height: 1.65; }
.quote-rec-why:not(.is-expanded) { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
.quote-rec-read { margin-top: .45rem; color: var(--color-red); font-family: var(--font-display); font-size: .82rem; font-weight: 600; cursor: pointer; }
.quote-rec-base-price { display: flex; align-items: end; justify-content: space-between; gap: 1rem; margin-top: 2rem; padding-top: 1.25rem; border-top: 1px solid var(--color-line); }
.quote-rec-base-price span { max-width: 12rem; color: var(--color-muted); font-family: var(--font-display); font-size: .78rem; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; }
.quote-rec-base-price strong { font-family: var(--font-numeral); font-size: clamp(3.5rem, 7vw, 5.5rem); font-weight: 400; line-height: .8; }
.quote-rec-build-summary { display: flex; flex-direction: column; justify-content: flex-end; padding: 2rem; background: var(--color-oxblood); color: #fff; }
.quote-rec-build-summary span { color: var(--color-sand); font-family: var(--font-display); font-size: .72rem; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; }
.quote-rec-build-summary strong { margin-top: .5rem; font-family: var(--font-display); font-size: 1.45rem; line-height: 1.1; }
.quote-rec-build-summary small { margin-top: .3rem; color: rgb(255 255 255 / .7); }

.quote-rec-upgrade { display: grid; gap: .3rem; width: 100%; margin-top: 1rem; padding: 1.2rem 1.35rem; border: 1px solid rgb(89 13 7 / .22); border-radius: .8rem; background: var(--color-sand); text-align: left; cursor: pointer; }
.quote-rec-upgrade span { color: var(--color-oxblood); font-family: var(--font-display); font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; }
.quote-rec-upgrade strong { max-width: 55rem; font-size: .9rem; font-weight: 500; line-height: 1.5; }
.quote-rec-upgrade b { margin-top: .25rem; color: var(--color-oxblood); font-family: var(--font-display); font-size: .9rem; }

.quote-rec-options { margin-top: 1rem; padding: clamp(1.25rem, 3vw, 2rem); border: 1px solid var(--color-line); border-radius: 1rem; background: rgb(255 255 255 / .55); }
.quote-rec-options-head { display: flex; align-items: end; justify-content: space-between; gap: 1rem; margin-bottom: 1rem; }
.quote-rec-options-head h3 { margin-top: .25rem; font-size: 1.35rem; }
.quote-rec-options-head > span { color: var(--color-muted); font-size: .8rem; }
.quote-rec-addon-list { border-top: 1px solid var(--color-line); }
.quote-rec-addon { display: grid; grid-template-columns: 1.4rem 1fr auto auto; align-items: center; gap: .75rem; width: 100%; padding: .85rem .2rem; border-bottom: 1px solid var(--color-line); text-align: left; cursor: pointer; }
.quote-rec-addon strong { font-family: var(--font-display); font-size: .95rem; }
.quote-rec-addon small { padding: .15rem .4rem; border-radius: .25rem; background: var(--color-sand); color: var(--color-oxblood); font-size: .65rem; font-weight: 600; text-transform: uppercase; }
.quote-rec-addon b { min-width: 5rem; text-align: right; font-family: var(--font-display); font-size: .9rem; }
.quote-rec-paint-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; }
.quote-rec-paint-card { display: grid; grid-template-columns: 1fr auto; gap: .25rem 1rem; padding: 1.2rem; border: 1px solid var(--color-line); border-radius: .75rem; background: var(--color-paper); text-align: left; cursor: pointer; }
.quote-rec-paint-card > span { grid-column: 1 / -1; color: var(--color-red); font-family: var(--font-display); font-size: .7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; }
.quote-rec-paint-card strong { font-family: var(--font-display); font-size: 1rem; }
.quote-rec-paint-card b { font-family: var(--font-numeral); font-size: 1.5rem; font-weight: 400; }
.quote-rec-paint-card p { grid-column: 1 / -1; margin-top: .35rem; color: var(--color-muted); font-size: .78rem; line-height: 1.45; }
.quote-rec-paint-card.is-selected { border-color: var(--color-red); background: rgb(184 54 61 / .06); box-shadow: inset 0 -3px 0 var(--color-red); }

.quote-rec-checkout { display: grid; grid-template-columns: minmax(15rem, .7fr) minmax(0, 1.3fr); overflow: hidden; margin-top: 1rem; border: 1px solid var(--color-line); border-radius: 1rem; background: #fff; }
.quote-rec-total { padding: clamp(1.5rem, 3vw, 2rem); background: var(--color-ink); color: #fff; }
.quote-rec-total > span { color: var(--color-sand); font-family: var(--font-display); font-size: .75rem; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; }
.quote-rec-total strong { display: block; margin-top: .45rem; font-family: var(--font-numeral); font-size: clamp(3.8rem, 7vw, 6rem); font-weight: 400; line-height: .85; }
.quote-rec-total p { margin-top: 1rem; color: rgb(255 255 255 / .62); font-size: .8rem; line-height: 1.45; }
.quote-rec-contact, .quote-rec-sent { padding: clamp(1.5rem, 3vw, 2rem); }
.quote-rec-contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: .85rem; }
.quote-rec-contact-grid label:last-child { grid-column: 1 / -1; }
.quote-rec-contact-grid label > span { display: block; margin-bottom: .3rem; font-family: var(--font-display); font-size: .82rem; font-weight: 600; }
.quote-rec-contact-grid label small { color: var(--color-muted); font-family: var(--font-body); font-weight: 400; }
.quote-rec-error { margin-top: .8rem; color: var(--color-red); font-size: .9rem; }
.quote-rec-actions { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 1rem; }
.quote-rec-actions .btn { flex: 1; min-width: 12rem; }
.quote-rec-actions button:disabled { opacity: .55; cursor: wait; }
.quote-rec-trust { display: flex; flex-wrap: wrap; gap: .5rem 1rem; margin-top: 1rem; color: var(--color-muted); font-size: .72rem; }
.quote-rec-sent { display: flex; flex-direction: column; justify-content: center; }
.quote-rec-sent > span { color: var(--color-red); font-family: var(--font-display); font-size: .75rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; }
.quote-rec-sent h3 { margin-top: .35rem; font-size: 1.7rem; }
.quote-rec-sent p { margin-top: .45rem; color: var(--color-muted); }

@media (max-width: 760px) {
  .quote-rec-progress { grid-template-columns: 1fr 1fr 1fr; gap: .4rem; padding: .65rem; }
  .quote-rec-progress i { display: none; }
  .quote-rec-progress span { justify-content: center; font-size: .68rem; }
  .quote-rec-progress span b { width: 1.45rem; height: 1.45rem; }
  .quote-rec-step { grid-template-columns: 1fr; gap: .4rem; padding: 1.2rem; }
  .quote-rec-step-number { font-size: 2rem; }
  .quote-rec-condition-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: .3rem; }
  .quote-rec-condition-grid button { min-height: 5rem; padding: .65rem .35rem; }
  .quote-rec-condition-grid button strong { margin-top: .5rem; font-size: .72rem; }
  .quote-rec-condition-grid button span { font-size: .85rem; }
  .quote-rec-concern-grid { grid-template-columns: 1fr; }
  .quote-rec-result-grid, .quote-rec-checkout { grid-template-columns: 1fr; }
  .quote-rec-build-summary { min-height: 9rem; }
  .quote-rec-options-head { align-items: start; flex-direction: column; }
  .quote-rec-paint-grid { grid-template-columns: 1fr; }
  .quote-rec-contact-grid { grid-template-columns: 1fr; }
  .quote-rec-contact-grid label:last-child { grid-column: auto; }
  .quote-rec-actions { flex-direction: column; }
  .quote-rec-actions .btn { width: 100%; flex: auto; }
  .quote-rec-addon { grid-template-columns: 1.4rem 1fr auto; }
  .quote-rec-addon small { display: none; }
}

