/* V17: one global header treatment. Every route now uses the same
   photographic fade as the homepage, and the brand mark sits closer
   to the viewport edge without being clipped. */
.inner-header {
  background: transparent;
  border-bottom: 0;
}

.home-header::before,
.inner-header::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 15rem;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    rgb(0 0 0 / .78) 0%,
    rgb(0 0 0 / .62) 24%,
    rgb(0 0 0 / .40) 50%,
    rgb(0 0 0 / .16) 74%,
    transparent 100%
  );
}

@media (min-width: 1024px) {
  .home-nav-shell,
  .inner-nav-shell {
    width: min(1560px, calc(100vw - 2rem));
    padding-left: 0;
    padding-right: 1rem;
  }
}

@media (min-width: 1600px) {
  .home-header::before,
  .inner-header::before {
    height: 18rem;
    background: linear-gradient(
      to bottom,
      rgb(0 0 0 / .86) 0%,
      rgb(0 0 0 / .70) 28%,
      rgb(0 0 0 / .46) 54%,
      rgb(0 0 0 / .20) 76%,
      transparent 100%
    );
  }

  .home-nav-shell,
  .inner-nav-shell {
    width: min(1560px, calc(100vw - 2.5rem));
    padding-left: 0;
    padding-right: 1rem;
  }
}

@media (max-width: 1023px) {
  .home-header::before,
  .inner-header::before {
    height: 11rem;
    background: linear-gradient(
      to bottom,
      rgb(0 0 0 / .78),
      rgb(0 0 0 / .38) 58%,
      transparent
    );
  }

  .home-nav-shell,
  .inner-nav-shell {
    width: calc(100vw - 1rem);
    margin-left: .5rem;
    margin-right: .5rem;
    padding-left: 0;
  }
}

@media (max-width: 767px) {
  .home-nav-shell,
  .inner-nav-shell {
    width: calc(100vw - .75rem);
    margin-left: .375rem;
    margin-right: .375rem;
    padding-left: 0;
    padding-right: .5rem;
  }
}

