.quote-rec-price-card > p { margin-top: 1rem; padding-top: 1rem; border-top: 1px solid rgb(255 255 255 / .18); color: rgb(255 255 255 / .76); font-size: .78rem; line-height: 1.45; }
.quote-rec-price-card > b { margin-top: 1rem; color: #fff; font-family: var(--font-display); font-size: .78rem; font-weight: 600; line-height: 1.45; }
.quote-rec-save-card { display: grid; grid-template-columns: minmax(15rem, .72fr) minmax(0, 1.28fr); overflow: hidden; margin-top: 1rem; border: 1px solid var(--color-line); border-radius: 1rem; background: #fff; }
