.quote-rec-save-button { width: 100%; margin-top: 1rem; }
.quote-rec-save-note { margin-top: .7rem; color: var(--color-muted); font-size: .72rem; text-align: center; }
.quote-rec-book-card { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 2rem; margin-top: 1rem; padding: clamp(1.5rem, 3vw, 2.2rem); border: 1px solid rgb(89 13 7 / .2); border-radius: 1rem; background: var(--color-sand); }
.quote-rec-book-card span { color: var(--color-red); font-family: var(--font-display); font-size: .72rem; font-weight: 750; text-transform: uppercase; letter-spacing: .09em; }
.quote-rec-book-card h3 { margin-top: .3rem; font-size: clamp(1.6rem, 3vw, 2.25rem); line-height: 1; letter-spacing: -.04em; }
