.quote-rec-book-actions { display: grid; gap: .7rem; min-width: 14rem; }
.quote-rec-customize-toggle { color: var(--color-oxblood); font-family: var(--font-display); font-size: .82rem; font-weight: 650; text-align: center; cursor: pointer; }
.quote-rec-customize-panel { margin-top: 1rem; padding: clamp(1.25rem, 3vw, 2rem); border: 1px solid var(--color-line); border-radius: 1rem; background: rgb(255 255 255 / .58); }
.quote-rec-customize-group { margin-top: 1.35rem; }
.quote-rec-customize-group h4 { margin-bottom: .6rem; font-family: var(--font-display); font-size: .92rem; }
.quote-rec-customize-footer { display: flex; align-items: end; justify-content: space-between; gap: 1rem; margin-top: 1.35rem; padding-top: 1.25rem; border-top: 1px solid var(--color-line); }
.quote-rec-customize-footer > div { display: grid; gap: .2rem; }
.quote-rec-customize-footer span { color: var(--color-muted); font-family: var(--font-display); font-size: .72rem; font-weight: 650; text-transform: uppercase; letter-spacing: .07em; }
.quote-rec-customize-footer strong { font-family: var(--font-numeral); font-size: 2.8rem; font-weight: 400; line-height: .9; }
