    opacity: .82 !important;
    transform: none !important;
    font-size: .72rem !important;
    line-height: 1.42 !important;
  }
  .v15-service:hover .v15-service-includes,
  .v15-service.is-active .v15-service-includes {
    max-height: none !important;
    margin-top: .6rem !important;
    opacity: 1 !important;
  }
  .v15-arrow { grid-column: 3 !important; grid-row: 1 !important; align-self: start; }
}

@media (max-width: 420px) {
  .hero-inner.container-ed { padding-top: clamp(20rem, 46svh, 27rem); }
  .proof-row { font-size: .72rem !important; letter-spacing: .035em !important; }
  .proof-row span { min-height: 3.75rem !important; padding: .6rem .45rem !important; }
}

/* V1.4.3: iOS address autofill + mobile legibility/wrapping polish */
@media (max-width: 767px) {
  /* Keep the small hero context line readable against bright areas of the photo. */
  .hero-eyebrow,
  .hero-copy .eyebrow {
    color: #fff !important;
    font-size: .72rem !important;
