/* V1.4.5: keep the booking flow intact; step only the client-info section */
.client-info-progress {
  width:100%;
  max-width:46rem;
  display:grid;
  grid-template-columns:auto 1fr auto 1fr auto;
  align-items:center;
  gap:.7rem;
  margin-top:.25rem;
  padding:.75rem .9rem;
  border:1px solid var(--color-line);
  border-radius:.8rem;
  background:rgb(255 255 255 / .52);
}
.client-info-progress button {
  display:flex;
  align-items:center;
  gap:.45rem;
  min-width:0;
  border:0;
  background:transparent;
  color:var(--color-muted);
  font-family:var(--font-display);
  font-size:.78rem;
  font-weight:750;
  text-align:left;
}
.client-info-progress button b {
  display:grid;
  width:1.7rem;
  height:1.7rem;
  flex:0 0 1.7rem;
  place-items:center;
  border:1px solid var(--color-line);
  border-radius:999px;
  font-size:.66rem;
}
.client-info-progress button.is-active { color:var(--color-ink); }
.client-info-progress button.is-active b { border-color:var(--color-red);color:var(--color-red); }
.client-info-progress button.is-done { color:var(--color-oxblood);cursor:pointer; }
.client-info-progress button.is-done b { border-color:var(--color-oxblood);background:var(--color-oxblood);color:#fff; }
.client-info-progress i { height:1px;background:var(--color-line); }
.client-info-panel { width:100%;max-width:46rem;min-width:0; }
.booking-address-block { padding-top:.1rem; }

@media (max-width:640px) {
  .client-info-progress {
    grid-template-columns:1fr 1fr 1fr;
    gap:.3rem;
    padding:.65rem .45rem;
  }
  .client-info-progress i { display:none; }
  .client-info-progress button {
    justify-content:center;
    gap:.3rem;
    font-size:.66rem;
    line-height:1.1;
    text-align:center;
  }
  .client-info-progress button b {
    width:1.4rem;
    height:1.4rem;
    flex-basis:1.4rem;
    font-size:.58rem;
  }
  .client-info-panel .btn { min-height:3.25rem; }
}

/* V1.4.7: notes editor is intentionally not a textarea so iOS Safari cannot
   misclassify it as another address field during contact/address AutoFill. */
.autofill-safe-notes {
  min-height: 7.5rem;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  cursor: text;
}
.autofill-safe-notes:empty::before {
  content: attr(data-placeholder);
  color: var(--color-muted);
  pointer-events: none;
}

/* Booking calendar: compact, familiar month picker */
.booking-calendar-wrap {
  margin-top: 1rem;
  border: 1px solid rgb(17 17 17 / .16);
  border-radius: 14px;
  background: #fff;
  overflow: hidden;
}
.booking-calendar-month {
  max-width: 34rem;
  padding: 1.1rem 1.25rem 1.2rem;
}
.booking-calendar-header {
  display: grid;
  grid-template-columns: 2.5rem 1fr 2.5rem;
  align-items: center;
  margin-bottom: .8rem;
}
.booking-calendar-header h3 {
  margin: 0;
  text-align: center;
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
}
.booking-calendar-header button {
  width: 2.25rem;
  height: 2.25rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--color-ink);
  font-size: 1.65rem;
  line-height: 1;
  cursor: pointer;
}
.booking-calendar-header button:hover:not(:disabled) { background: rgb(17 17 17 / .055); }
.booking-calendar-header button:disabled { opacity: .18; cursor: default; }
.booking-calendar-weekdays,
.booking-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: .25rem;
}
.booking-calendar-weekdays { margin-bottom: .25rem; }
.booking-calendar-weekdays span {
  text-align: center;
  font-family: var(--font-display);
  font-size: .65rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--color-muted);
}
.booking-calendar-day,
.booking-calendar-blank {
  aspect-ratio: 1 / 1;
  min-width: 0;
}
.booking-calendar-day {
  display: grid;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: rgb(17 17 17 / .24);
  font-family: var(--font-display);
  font-size: .96rem;
  font-weight: 600;
  cursor: default;
}
.booking-calendar-day:not(:disabled) {
  color: var(--color-ink);
  cursor: pointer;
}
.booking-calendar-day:not(:disabled):hover {
  background: rgb(184 54 61 / .09);
}
.booking-calendar-day[aria-checked="true"] {
  border-color: var(--color-red);
  background: var(--color-red);
  color: #fff;
}
.booking-calendar-day:focus-visible { outline: 3px solid rgb(184 54 61 / .22); outline-offset: 1px; }
.booking-time-panel {
  padding: 1rem 1.25rem 1.15rem;
  border-top: 1px solid var(--color-line);
  background: rgb(232 221 207 / .16);
}
.booking-time-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}
.booking-time-heading h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.08rem;
  font-weight: 700;
}
.booking-time-heading > span { font-size: .76rem; color: var(--color-muted); }
.booking-time-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: .45rem;
  margin-top: .75rem;
}
.booking-time-choice {
  min-height: 2.75rem;
  align-items: center;
  padding: .45rem .35rem;
  text-align: center;
  font-family: var(--font-display);
  font-weight: 600;
}
.booking-time-zone { margin: .6rem 0 0; font-size: .74rem; color: var(--color-muted); }

@media (max-width: 760px) {
  .booking-calendar-month { max-width: none; padding: 1rem; }
  .booking-calendar-header { margin-bottom: .65rem; }
  .booking-calendar-weekdays, .booking-calendar-grid { gap: .15rem; }
  .booking-calendar-day { font-size: .92rem; }
  .booking-time-panel { padding: .9rem 1rem 1rem; }
  .booking-time-heading { align-items: flex-start; flex-direction: column; gap: .1rem; }
  .booking-time-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}


/* V1.5.0: scheduling notice + clearer booking calendar */
.availability-banner {
  position: relative;
  display: block;
  width: 100vw;
  height: 2.15rem;
  margin-left: calc(50% - 50vw);
  overflow: hidden;
  border: 0;
  border-bottom: 1px solid rgb(255 255 255 / .16);
  background: var(--color-red);
  color: #fff;
  cursor: pointer;
  pointer-events: auto;
  font-family: var(--font-display);
  font-size: .68rem;
  font-weight: 750;
  letter-spacing: .08em;
  text-transform: uppercase;
  white-space: nowrap;
}
.availability-banner-track {
  display: flex;
  width: max-content;
  min-width: 200%;
  align-items: center;
  height: 100%;
  animation: availability-marquee 28s linear infinite;
}
.availability-banner-track > span { display: inline-block; padding-right: 1.5rem; }
.availability-banner:hover .availability-banner-track { animation-play-state: paused; }
@keyframes availability-marquee { to { transform: translateX(-50%); } }

.home-header,
.inner-header { padding-top: 0 !important; }
.home-nav-shell,
.inner-nav-shell { margin-top: 1rem; }

.availability-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 1.25rem;
  background: rgb(17 17 17 / .58);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  pointer-events: auto;
}
.availability-modal {
  position: relative;
  width: min(34rem, 100%);
  padding: clamp(1.6rem, 4vw, 2.35rem);
  border: 1px solid rgb(17 17 17 / .14);
  border-radius: 1rem;
  background: var(--color-paper);
  color: var(--color-ink);
  box-shadow: 0 24px 80px rgb(0 0 0 / .24);
}
.availability-modal-close {
  position: absolute;
  top: .8rem;
  right: .8rem;
  width: 2.4rem;
  height: 2.4rem;
  border: 0;
  border-radius: 999px;
  background: rgb(17 17 17 / .06);
  color: var(--color-ink);
  font-size: 1.5rem;
  line-height: 1;
  cursor: pointer;
}
.availability-modal-kicker {
  margin: 0 0 .75rem;
  color: var(--color-red);
  font-family: var(--font-display);
  font-size: .68rem;
  font-weight: 800;
  letter-spacing: .13em;
}
.availability-modal h2 {
  max-width: 27rem;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 650;
  letter-spacing: -.045em;
  line-height: 1;
}
.availability-modal > p:not(.availability-modal-kicker) {
  margin-top: 1rem;
  color: rgb(17 17 17 / .7);
  line-height: 1.6;
}
.availability-modal-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.25rem;
  margin-top: 1.5rem;
}
.availability-modal-actions > a:not(.btn) {
  color: var(--color-ink);
  font-family: var(--font-display);
  font-size: .88rem;
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: var(--color-red);
  text-underline-offset: 4px;
}

/* Calendar dates all remain readable. Availability is the accent, not opacity. */
.booking-calendar-day {
  position: relative;
  color: var(--color-ink);
  overflow: visible;
}
.booking-calendar-day:disabled {
  color: var(--color-ink);
  opacity: 1;
}
.booking-calendar-day[data-available="true"] {
  color: var(--color-red);
  font-weight: 750;
}
.booking-calendar-dot {
  position: absolute;
  left: 50%;
  bottom: .28rem;
  width: .25rem;
  height: .25rem;
  border-radius: 999px;
  background: currentColor;
  transform: translateX(-50%);
}
.booking-calendar-day[data-today="true"]::before {
  content: "";
  position: absolute;
  inset: .18rem;
  border: 1.5px solid var(--color-ink);
  border-radius: 999px;
  pointer-events: none;
}
.booking-calendar-today {
  position: absolute;
  top: -.43rem;
  left: 50%;
  padding: 0 .2rem;
  background: #fff;
  color: var(--color-ink);
  font-family: var(--font-display);
  font-size: .43rem;
  font-weight: 800;
  letter-spacing: .04em;
  line-height: 1;
  text-transform: uppercase;
  transform: translateX(-50%);
}
.booking-calendar-day[aria-checked="true"] {
  color: #fff;
}
.booking-calendar-day[aria-checked="true"] .booking-calendar-dot { background: #fff; }
.booking-calendar-day[aria-checked="true"]::before { border-color: transparent; }
.booking-calendar-day[aria-checked="true"] .booking-calendar-today {
  background: var(--color-red);
