/* v41: first-screen audit + Detail+ hero composition */
.plus-brand-hero{
  min-height:0;
  padding:clamp(7.2rem,9vh,8.4rem) 0 0;
  background:var(--plus-ox);
}
.plus-brand-hero-grid{
  min-height:clamp(31rem,60vh,39rem);
  grid-template-columns:minmax(0,1.65fr) minmax(19rem,.72fr);
  gap:clamp(2.5rem,5vw,5.5rem);
  align-items:center;
}
.plus-brand-hero-copy{padding:clamp(2rem,4vh,3.5rem) 0}
.plus-brand-hero .plus-brand-kicker{color:var(--plus-coral)}
.plus-brand-hero h1{
  max-width:900px;
  margin-top:1rem;
  font-size:clamp(4rem,6.7vw,7.2rem);
  line-height:.84;
}
.plus-brand-lede{max-width:39rem;margin-top:1.35rem;font-size:clamp(1rem,1.1vw,1.12rem)}
.plus-brand-actions{margin-top:1.65rem}
.plus-brand-photo{
  align-self:center;
  min-height:0;
  margin-right:calc((100vw - min(88vw,1340px))/ -2);
  border:0;
  border-left:3px solid var(--plus-black);
  box-shadow:none;
  overflow:hidden;
}
.plus-brand-photo>div:first-child{height:auto!important;aspect-ratio:2/3!important}
.plus-brand-photo img{height:100%!important;object-fit:cover;object-position:center center}
.plus-brand-hero-stamp{position:absolute;left:-2.4rem;top:2.1rem;z-index:2;background:var(--plus-ox)}
.plus-brand-photo figcaption{right:auto;left:0}
.plus-brand-rule{margin-top:0;border-top:2px solid var(--plus-coral);border-bottom:0}
.plus-brand-rule span{padding:1rem .6rem;font-size:.62rem}


@media(max-width:900px){
  .plus-brand-photo>div:first-child{height:100%!important;aspect-ratio:auto!important}
  .plus-brand-photo img{object-position:center 55%}
}

/* Inner-page first screens: sticky header already occupies its own height. Do not add another header-sized void. */
