/* V42 responsive QA: viewport safety, border/shadow gutters, and cross-page rhythm */
html,body{max-width:100%;overflow-x:clip}
img,svg,video,canvas{max-width:100%}
main,section,article,div,form,fieldset{min-width:0}
.btn,.tactile-link,.svc-mini-book,.svc-outline-btn,.svc-tactile-btn,.svc-light-btn,.plus-brand-btn{max-width:100%;white-space:normal;text-align:center;overflow-wrap:anywhere}
[id]{scroll-margin-top:6.5rem}

/* Offset borders/shadows need a real gutter. Do not hide their last few pixels at the viewport edge. */
.home-next-v158,.services-v161,.plus-brand,.paint-v38{overflow-x:clip}
.upgrade-board,.edu-service,.edu-value-statement,.svc-live-prices,.svc-guidance,.plus-brand-form-wrap,.pv38-ticket{margin-right:10px;margin-bottom:10px}

/* Homepage: keep the strongest layouts, but prevent intermediate laptop widths from squeezing controls. */
@media (min-width:768px) and (max-width:1199px){
  .home-services-v14{padding-top:5.25rem;padding-bottom:5.75rem}
  .home-services-v14 .v14-service-head{grid-template-columns:minmax(0,1fr) minmax(16rem,.55fr);gap:2.5rem;margin-bottom:2.5rem}
