  .v15-stage-inner{padding-inline:1.4rem}
  .v15-service{grid-template-columns:3rem minmax(0,1fr) minmax(9rem,.34fr) auto 1.5rem;gap:.8rem}
  .home-work-v157,.home-story,.home-next-v158,.home-faq{padding-top:5.5rem!important;padding-bottom:5.5rem!important}
  .upgrade-board{grid-template-columns:minmax(0,1fr) minmax(18rem,.82fr);gap:2.5rem;padding:2rem;min-height:0}
  .upgrade-main h3{font-size:clamp(3.2rem,5.5vw,5rem)}
  .plus-steps{gap:0}
}

