/* V17.1: Services is primarily a framed, scroll-driven story. */
.service-depth{
  --depth-top:0px;
  position:relative;
  height:930vh;
  padding:0 1rem;
  background:#111;
  color:var(--color-paper);
  border-block:3px solid #111;
}
.service-depth-anchor{position:absolute;left:0;width:1px;height:1px;pointer-events:none;scroll-margin-top:calc(var(--depth-top) + 1rem)}
.service-depth-sticky{
  position:sticky;
  top:var(--depth-top);
  height:calc(100svh - var(--depth-top) - 1rem);
  min-height:34rem;
  overflow:hidden;
  border:1px solid rgb(255 255 255/.2);
