/* V16.2 homepage motion pass: layered cards + restrained scroll-linked depth */
.hero-full {
  --home-hero-progress: 0;
  background-size: calc(100% + (var(--home-hero-progress) * 5%)) auto;
}
.hero-copy {
  transform: translate3d(0, calc(var(--home-hero-progress, 0) * -32px), 0) scale(calc(1 - (var(--home-hero-progress, 0) * .018)));
  opacity: calc(1 - (var(--home-hero-progress, 0) * .42));
  transform-origin: left center;
  will-change: transform, opacity;
}

.work-v157-lead,
.work-v157-grid figure {
  --home-work-in: 1;
  --home-work-drift: 0;
  transform: translate3d(0, calc((1 - var(--home-work-in)) * 36px), 0);
  opacity: calc(.62 + (var(--home-work-in) * .38));
  will-change: transform, opacity;
}
.work-v157-lead > div:first-child,
.work-v157-grid figure > div:first-child {
  transform: translate3d(0, calc(var(--home-work-drift) * -10px), 0) scale(calc(1.025 - (var(--home-work-in) * .025)));
  transition: transform .18s linear;
}
.work-v157-lead:hover > div:first-child,
.work-v157-grid figure:hover > div:first-child {
  transform: translate3d(3px, calc(3px + (var(--home-work-drift) * -10px)), 0) scale(calc(1.025 - (var(--home-work-in) * .025)));
}

