/* ===== V18 SYSTEM REFINEMENT ===== */
:root {
  --v18-section: clamp(4.5rem, 8vw, 8rem);
  --v18-gap: clamp(1.25rem, 2.4vw, 2rem);
  --v18-rule: rgb(24 17 13 / .16);
}

/* CTA language and navigation now use one clear decision model: Find My Detail / Book Now. */
.booking-stage-rail {
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:.5rem;
  padding:.55rem;
  border:1px solid var(--v18-rule);
  border-radius:1rem;
  background:rgb(255 255 255 / .5);
}
.booking-stage-rail span {
  display:flex; align-items:center; gap:.55rem;
  min-height:2.75rem; padding:.55rem .7rem;
  border-radius:.7rem;
  color:var(--color-muted);
  font-family:var(--font-display); font-size:.78rem; font-weight:700;
  text-transform:uppercase; letter-spacing:.06em;
}
.booking-stage-rail span b {
  display:grid; place-items:center; width:1.55rem; height:1.55rem;
  border:1px solid currentColor; border-radius:999px; font-size:.68rem;
}
.booking-stage-rail span.is-active { background:var(--color-ink); color:var(--color-paper); }

/* Services: give customers a simple decision before the educational depth. */
.svc-quick-pick { padding:clamp(3rem,6vw,5.5rem) 0; border-bottom:1px solid var(--v18-rule); background:var(--color-paper); }
.svc-quick-head { display:flex; align-items:end; justify-content:space-between; gap:2rem; margin-bottom:2rem; }
.svc-quick-head h2 { max-width:760px; font-family:var(--font-display); font-size:clamp(2.2rem,5vw,4.7rem); line-height:.94; letter-spacing:-.055em; }
.svc-quick-head h2 span { color:var(--color-red); }
.svc-quick-grid { display:grid; grid-template-columns:repeat(3,1fr); border:1px solid var(--v18-rule); }
.svc-quick-grid a { display:flex; min-height:20rem; flex-direction:column; padding:1.6rem; border-right:1px solid var(--v18-rule); color:inherit; transition:background .2s ease,color .2s ease,transform .2s ease; }
.svc-quick-grid a:last-child { border-right:0; }
.svc-quick-grid a:hover { background:#fff; transform:translateY(-2px); }
.svc-quick-grid a.is-featured { background:var(--color-ink); color:var(--color-paper); }
.svc-quick-grid b { font-size:.72rem; letter-spacing:.1em; opacity:.62; }
.svc-quick-grid span { margin-top:auto; font-size:.8rem; font-weight:700; text-transform:uppercase; letter-spacing:.06em; opacity:.7; }
.svc-quick-grid strong { margin-top:.4rem; font-family:var(--font-display); font-size:clamp(1.6rem,2.6vw,2.4rem); line-height:1; letter-spacing:-.04em; }
.svc-quick-grid p { margin-top:.9rem; max-width:29rem; line-height:1.55; opacity:.8; }
.svc-quick-actions { display:flex; gap:.8rem; margin-top:1.3rem; }

/* Detail+ resolves the offer before the long-form story. */
.plus-offer-clarity { border-bottom:1px solid rgb(255 255 255 / .14); background:#171310; color:#f3f1ec; }
.plus-offer-grid { display:grid; grid-template-columns:repeat(3,1fr) auto; align-items:stretch; }
.plus-offer-grid > div { padding:1.4rem 1.4rem 1.5rem; border-right:1px solid rgb(255 255 255 / .14); }
.plus-offer-grid span { display:block; color:#c8bba9; font-size:.68rem; font-weight:800; letter-spacing:.11em; }
.plus-offer-grid strong { display:block; margin-top:.35rem; font-family:var(--font-display); font-size:1.05rem; }
.plus-offer-grid > a { display:grid; place-items:center; padding:1.5rem 2rem; background:var(--color-red); color:#fff; font-family:var(--font-display); font-weight:800; }

/* Homepage crew trust bridge */
.home-team-proof { padding:var(--v18-section) 0; background:#ede8df; }
.home-team-proof-grid { display:grid; grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr); gap:clamp(2rem,6vw,6rem); align-items:center; }
.home-team-proof figure { transform:rotate(-1deg); box-shadow:0 22px 70px rgb(24 17 13 / .12); }
.home-team-proof-copy p:not(.eyebrow) { max-width:34rem; margin-top:1.4rem; font-size:1.06rem; line-height:1.65; color:var(--color-muted); }
.home-team-proof-points { display:flex; flex-wrap:wrap; gap:.55rem; margin:1.5rem 0 1.7rem; }
.home-team-proof-points span { border:1px solid var(--v18-rule); border-radius:999px; padding:.48rem .72rem; font-size:.68rem; font-weight:800; letter-spacing:.06em; }

/* Our Work: editorial proof instead of a generic gallery. */
.work-page-v18 { background:var(--color-paper); }
.work-page-hero { padding:clamp(7rem,11vw,10rem) 0 clamp(4rem,7vw,7rem); background:#161310; color:#f3f1ec; }
.work-page-hero-grid { display:grid; grid-template-columns:1.15fr .65fr; gap:clamp(2rem,7vw,7rem); align-items:end; }
.work-page-hero h1 { margin-top:1rem; font-family:var(--font-display); font-size:clamp(4rem,9vw,8.8rem); line-height:.82; letter-spacing:-.075em; }
