.work-page-hero-copy > p { font-size:clamp(1.05rem,1.8vw,1.35rem); line-height:1.6; color:rgb(243 241 236 / .75); }
.work-page-proof { display:flex; flex-direction:column; gap:.25rem; margin-top:2rem; padding-top:1.2rem; border-top:1px solid rgb(255 255 255 / .18); }
