}

.gift-intro-orbit-b {
  width: min(26rem, 58vw);
  aspect-ratio: 1;
  left: 50%;
  top: 47%;
  transform: translate(-50%, -50%);
  opacity: .55;
}

.gift-intro-shell {
  position: relative;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: 8.2rem 1.25rem 2.5rem;
}

.gift-intro-copy {
  position: absolute;
  top: clamp(7.2rem, 12vw, 8.7rem);
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  display: grid;
  gap: .7rem;
  width: min(26rem, calc(100% - 2rem));
  color: #fff4ef;
  animation: giftIntroFade 1s cubic-bezier(.22, 1, .36, 1) both;
}

.gift-intro-copy .eyebrow {
  color: rgba(255,255,255,.74);
}

.gift-intro-copy span {
  font-size: .82rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  opacity: .88;
}

.gift-intro-card-wrap {
  display: grid;
  place-items: center;
  width: 100%;
  padding-inline: 1rem;
}

.gift-card-preview-intro {
  width: min(33rem, calc(100vw - 2.5rem));
  min-height: 20rem;
  border-radius: 1.65rem;
  transform:
    perspective(1200px)
    rotateX(calc(var(--gift-mouse-y) * -0.34deg))
    rotateY(calc(var(--gift-mouse-x) * 0.42deg))
    translate3d(calc(var(--gift-mouse-x) * 0.6px), calc(var(--gift-scroll-shift) + (var(--gift-mouse-y) * 0.34px)), 0);
  animation:
    giftCardDrop 1.12s cubic-bezier(.22, 1, .36, 1) .1s both,
    giftCardFloat 5.8s ease-in-out 1.15s infinite;
  will-change: transform;
  box-shadow: 0 42px 90px rgba(48, 11, 8, .32);
}

.gift-card-preview-intro:before {
  content: "";
  position: absolute;
  inset: -12% -10% auto;
  height: 48%;
  background: linear-gradient(180deg, rgba(255,255,255,.22), transparent 70%);
  opacity: .45;
  pointer-events: none;
}

.gift-intro-scroll {
  position: absolute;
  left: 50%;
  bottom: clamp(1.5rem, 4vw, 2.8rem);
  transform: translateX(-50%);
  border: 0;
  background: transparent;
  color: rgba(255,255,255,.86);
  display: inline-flex;
  align-items: center;
  gap: .72rem;
  font: inherit;
  font-size: .84rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color .18s ease, transform .18s ease;
  animation: giftScrollCue 1.2s ease .7s both;
}

.gift-intro-scroll:hover {
  color: #fff;
}

.gift-intro-scroll i {
  display: inline-grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.28);
  font-style: normal;
  font-size: 1rem;
}

.gift-showcase {
  position: relative;
  margin-top: 0;
  scroll-margin-top: 6rem;
  padding: clamp(4rem, 7vw, 6rem) 0 clamp(4rem, 7vw, 6rem);
}

.gift-preview-wrap-v2 {
  top: 6rem;
}

.gift-preview-wrap-v2 h1 {
  max-width: 11ch;
  font-size: clamp(2.8rem, 5vw, 4.8rem);
}

@keyframes giftCardDrop {
  0% {
    opacity: 0;
    transform:
      perspective(1200px)
      translate3d(0, -82px, 0)
      scale(.955)
      rotateX(8deg);
  }
  64% {
    opacity: 1;
    transform:
      perspective(1200px)
      translate3d(0, 10px, 0)
      scale(1.012)
      rotateX(-1deg);
  }
  100% {
    opacity: 1;
  }
}

@keyframes giftCardFloat {
  0%, 100% {
    box-shadow: 0 42px 90px rgba(48, 11, 8, .32);
  }
  50% {
    box-shadow: 0 54px 105px rgba(48, 11, 8, .27);
  }
}

@keyframes giftIntroFade {
  from {
    opacity: 0;
    transform: translate(-50%, 18px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

@keyframes giftScrollCue {
  from {
    opacity: 0;
    transform: translate(-50%, 10px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .gift-card-preview-intro,
  .gift-intro-copy,
  .gift-intro-scroll {
    animation: none !important;
  }

  .gift-card-preview-intro {
    transform: none !important;
  }
}

@media (max-width: 900px) {
  .gift-intro-shell {
    padding-top: 7.4rem;
  }

  .gift-card-preview-intro {
    width: min(30rem, calc(100vw - 2rem));
    min-height: 18rem;
  }
}

@media (max-width: 640px) {
  .gift-intro {
    min-height: 92svh;
  }

  .gift-intro-copy {
    top: 6.8rem;
    gap: .55rem;
  }

  .gift-intro-copy span {
    font-size: .72rem;
  }

  .gift-intro-glow {
    width: min(28rem, 88vw);
    top: 42%;
  }

  .gift-intro-orbit-a {
    width: min(28rem, 92vw);
    top: 44%;
  }

  .gift-intro-orbit-b {
    width: min(16rem, 64vw);
    top: 44%;
  }

  .gift-card-preview-intro {
    width: min(24rem, calc(100vw - 1.4rem));
    min-height: 15rem;
    border-radius: 1.25rem;
  }

  .gift-intro-scroll {
    bottom: 1.25rem;
    font-size: .72rem;
    letter-spacing: .1em;
  }

  .gift-intro-scroll i {
    width: 1.7rem;
    height: 1.7rem;
  }

  .gift-showcase {
    padding-top: 3rem;
  }
}

/* ===== BOOKING GIFT CARD v18.6 ===== */
.booking-gift-card {
  margin-top: .15rem;
  padding-top: 1rem;
  border-top: 1px solid var(--v18-rule);
}
.booking-gift-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.booking-gift-card-help {
  margin-top: .3rem;
  color: var(--color-muted);
  font-size: .78rem;
  line-height: 1.45;
}
.booking-gift-card-remove {
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  color: var(--color-red);
  font: inherit;
  font-size: .75rem;
  font-weight: 800;
  text-decoration: underline;
  text-underline-offset: .2rem;
  cursor: pointer;
}
.booking-gift-card-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: .55rem;
  margin-top: .8rem;
}
.booking-gift-card-entry input {
  min-width: 0;
  border: 1px solid rgb(17 17 17 / .18);
  border-radius: .75rem;
  background: #fff;
  padding: .78rem .85rem;
  color: var(--color-ink);
  font: inherit;
  font-size: .86rem;
  font-weight: 700;
  letter-spacing: .04em;
  outline: none;
}
.booking-gift-card-entry input:focus {
  border-color: var(--color-red);
  box-shadow: 0 0 0 3px rgb(185 32 44 / .08);
}
.booking-gift-card-entry button {
  border: 1px solid var(--color-ink);
  border-radius: .75rem;
  background: var(--color-ink);
  color: #fff;
  padding: .75rem .9rem;
  font: inherit;
  font-size: .78rem;
  font-weight: 900;
  cursor: pointer;
}
.booking-gift-card-entry button:disabled {
  cursor: not-allowed;
  opacity: .45;
}
.booking-gift-card-applied {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: .8rem;
  padding: .9rem 1rem;
  border: 1px solid rgb(89 13 7 / .16);
  border-radius: .85rem;
  background: rgb(89 13 7 / .055);
}
.booking-gift-card-applied > div {
  display: grid;
  gap: .12rem;
}
.booking-gift-card-applied span {
  color: var(--color-red);
  font-size: .67rem;
  font-weight: 900;
  letter-spacing: .08em;
}
.booking-gift-card-applied strong {
  font-family: var(--font-display);
  font-size: 1.05rem;
}
.booking-gift-card-applied small {
  color: var(--color-muted);
  font-size: .72rem;
}
.booking-gift-card-applied > b {
  display: grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 999px;
  background: var(--color-oxblood);
  color: #fff;
  font-size: .85rem;
}
.booking-gift-card-error {
  margin-top: .55rem;
  color: #9e1d24;
  font-size: .76rem;
  font-weight: 700;
  line-height: 1.4;
}
@media (max-width: 420px) {
  .booking-gift-card-entry { grid-template-columns: 1fr; }
  .booking-gift-card-entry button { width: 100%; }
}

/* ===== BOOKING SUMMARY VIEWPORT FIT v18.9 ===== */
@media (min-width:1024px) {
  .booking-summary-card {
    /* The summary remains sticky, but becomes its own scroll surface only when
       the available viewport is shorter than the card's content. */
    max-height: calc(100dvh - 9.6rem) !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: auto;
    scrollbar-color: rgb(17 17 17 / .32) transparent;
  }

  .booking-summary-card::-webkit-scrollbar {
    width: 9px;
  }
  .booking-summary-card::-webkit-scrollbar-track {
    background: transparent;
  }
  .booking-summary-card::-webkit-scrollbar-thumb {
    background: rgb(17 17 17 / .26);
    border: 3px solid transparent;
    border-radius: 999px;
    background-clip: padding-box;
  }
  .booking-summary-card:hover::-webkit-scrollbar-thumb {
    background: rgb(17 17 17 / .42);
    border: 3px solid transparent;
    background-clip: padding-box;
  }
}

