/* 01 / promise */
.v27-hero{--p:0;position:relative;min-height:100svh;overflow:hidden;background:#111;color:#fff}.v27-hero-photo,.v27-hero-shade{position:absolute;inset:0}.v27-hero-photo>div{position:absolute!important;inset:0}.v27-hero-photo img{object-position:58% 52%;transform:scale(calc(1.02 + var(--p)*.035));transition:none;will-change:transform}.v27-hero-shade{background:linear-gradient(90deg,rgba(5,5,5,.78) 0%,rgba(5,5,5,.52) 32%,rgba(5,5,5,.08) 67%),linear-gradient(0deg,rgba(5,5,5,.58),transparent 40%)}.v27-hero-inner{position:relative;z-index:2;min-height:100svh;display:flex;flex-direction:column;justify-content:flex-end;padding-top:9rem;padding-bottom:clamp(3.5rem,6vh,5.5rem)}.v27-location{margin:0 0 1.3rem;font-family:var(--font-numeral);font-size:.82rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.72)}.v27-hero-title{width:min(880px,70vw);margin:0;font-family:var(--font-numeral);font-weight:400;text-transform:uppercase;line-height:.75;letter-spacing:-.025em;text-wrap:initial}.v27-hero-title span{display:block;transform:translate3d(calc(var(--p)*-12px),calc(var(--p)*-24px),0)}.v27-hero-title .line-a{font-size:clamp(6.4rem,12.2vw,12rem);color:#f5f1e8}.v27-hero-title .line-b{font-size:clamp(5.4rem,10.6vw,10.6rem);color:var(--v27-red);margin-left:.02em}.v27-hero-title .line-c{font-size:clamp(6.4rem,12.2vw,12rem);color:var(--v27-red);margin-left:.02em}.v27-hero-bottom{display:flex;align-items:flex-end;justify-content:space-between;gap:3rem;margin-top:2rem;border-top:1px solid rgba(255,255,255,.45);padding-top:1.2rem}.v27-hero-bottom p{max-width:34rem;margin:0;color:rgba(255,255,255,.76);font-size:1rem;line-height:1.5}.v27-main-cta{display:inline-flex;align-items:center;justify-content:space-between;gap:2.5rem;min-width:190px;padding:.95rem 1.05rem;background:var(--v27-red);color:#fff;font-family:var(--font-display);font-size:.82rem;font-weight:800;letter-spacing:.07em;text-decoration:none;text-transform:uppercase;border:1px solid var(--v27-red);transition:background-color .2s ease,color .2s ease}.v27-main-cta:hover{background:#fff;border-color:#fff;color:#111}.v27-sweep{position:absolute;left:-10%;bottom:0;z-index:3;width:120%;height:4px;background:var(--v27-red);transform:scaleX(calc(.12 + var(--p)*.88));transform-origin:left center}

/* 02 / service choice */
.v27-choice{background:var(--v27-cream);padding:clamp(7rem,12vw,12rem) 0}.v27-choice-intro{--r:0;display:grid;grid-template-columns:.28fr 1.1fr .55fr;gap:clamp(2rem,5vw,6rem);align-items:end;padding-bottom:clamp(4rem,7vw,7rem);opacity:calc(.2 + var(--r)*.8);transform:translateY(calc((1 - var(--r))*24px))}.v27-choice-intro h2{margin:0;font-family:var(--font-numeral);font-weight:400;font-size:clamp(5rem,9.4vw,10rem);line-height:.78;letter-spacing:-.02em;text-transform:uppercase}.v27-choice-intro h2 span{display:block}.v27-choice-intro h2 span:last-child{color:var(--v27-red)}.v27-choice-intro>p:last-child{max-width:25rem;margin:0 0 .4rem;line-height:1.55;color:#525252}.v27-booking{border-top:1px solid #111}.v27-inline-links{display:flex;gap:2rem;justify-content:flex-end;margin-top:1.4rem;font-family:var(--font-display);font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em}.v27-inline-links a{text-decoration:none;border-bottom:1px solid currentColor}
