.v27-booking .v15-service-label{padding:1rem 0;border-bottom:1px solid var(--v27-line);color:#555}.v27-booking .v15-services{border:0!important;border-radius:0!important;background:transparent!important}.v27-booking .v15-service{border:0!important;border-bottom:1px solid #111!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:1.45rem 0!important}.v27-booking .v15-service:hover,.v27-booking .v15-service.is-active{background:var(--v27-red)!important;color:#fff!important;padding-left:1rem!important;padding-right:1rem!important}.v27-booking .v15-service-copy strong{font-family:var(--font-numeral)!important;font-weight:400!important;font-size:clamp(3.8rem,6vw,6.8rem)!important;letter-spacing:-.015em!important;line-height:.8!important;text-transform:uppercase}.v27-booking .v15-service-cue,.v27-booking .v15-service-detail,.v27-booking .v15-service-num{font-family:var(--font-display)!important}.v27-booking .v15-most{border-radius:0!important}.v27-booking .v15-stage{border-radius:0!important;background:var(--v27-black)!important}.v27-booking .v15-vehicle{border-radius:0!important}

/* 03 / work as a horizontal film strip */
.v27-work{--p:0;height:330svh;background:var(--v27-black);color:#fff}.v27-work-sticky{position:sticky;top:0;height:100svh;overflow:hidden;padding-top:clamp(6.5rem,9vh,8.5rem)}.v27-work-title-wrap{position:absolute;z-index:2;left:0;right:0;top:clamp(6.5rem,9vh,8.5rem);pointer-events:none}.v27-work-title-wrap h2{margin:1rem 0 0;font-family:var(--font-numeral);font-weight:400;font-size:clamp(5rem,10vw,10.8rem);line-height:.75;letter-spacing:-.02em;text-transform:uppercase}.v27-work-title-wrap h2 span{color:var(--v27-red)}.v27-work-track{position:absolute;left:0;top:0;height:100%;display:flex;align-items:flex-end;gap:1.3rem;width:max-content;padding:34vh 6vw 5vh 48vw;transform:translateX(calc(var(--p)*-52%));will-change:transform}.v27-shot{position:relative;flex:0 0 auto;margin:0;overflow:hidden;background:#222}.v27-shot>div{position:absolute!important;inset:0}.v27-shot-a{width:min(62vw,900px);height:52vh}.v27-shot-b{width:min(32vw,460px);height:65vh}.v27-shot-c{width:min(58vw,840px);height:48vh}.v27-shot-d{width:min(43vw,630px);height:61vh}.v27-shot figcaption{position:absolute;left:0;right:0;bottom:0;display:flex;justify-content:space-between;gap:1rem;padding:1rem;background:linear-gradient(transparent,rgba(0,0,0,.8));font-family:var(--font-display);font-size:.72rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.v27-shot figcaption b{color:var(--v27-red)}.v27-work-end{width:min(54vw,760px);padding:0 4vw 7vh 2vw;align-self:flex-end}.v27-work-end strong{display:block;font-family:var(--font-numeral);font-size:clamp(4.5rem,8vw,8rem);font-weight:400;line-height:.78;text-transform:uppercase}.v27-work-end strong span{color:var(--v27-red)}.v27-work-end a{display:inline-block;margin-top:1.8rem;color:#fff;font-size:.82rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;text-underline-offset:.35em}

/* 04 / story */
