.v29-hero-title span:nth-child(3){font-size:clamp(6.6rem,11.2vw,11.4rem);transform:translate3d(calc(var(--v29-x8) * -.8),calc(var(--v29-y10) * .72),0) rotate(var(--hero-r3,0deg))}
.v29-hero-title span{filter:drop-shadow(0 5px 18px rgba(0,0,0,.26));transition:letter-spacing .2s ease}
@media(pointer:fine){.v29-hero-title:hover span:nth-child(1){letter-spacing:-.032em}.v29-hero-title:hover span:nth-child(2){letter-spacing:-.028em}.v29-hero-title:hover span:nth-child(3){letter-spacing:-.032em}}
.v29-sweep{background:var(--v29-red);box-shadow:0 0 22px color-mix(in srgb,var(--v29-red) 65%,transparent)}

/* Curved, truly continuous hand-off. Time moves it; page scroll pushes it harder. */
.v30-ribbon{position:relative;height:174px;overflow:hidden;background:var(--v29-red);color:var(--v29-paper);border-bottom:1px solid rgba(0,0,0,.18)}
.v30-ribbon-window{position:absolute;inset:0;overflow:hidden}
