.v30-ribbon-svg{display:block;flex:none;width:2400px;height:184px;overflow:visible}
.v30-ribbon-svg text{fill:var(--v29-paper);font-family:var(--font-display);font-size:82px;font-weight:900;letter-spacing:-2px;text-transform:uppercase}

/* Get to the actual chooser quickly. The first option should enter this viewport. */
.v29-choice{padding:3.8rem 0 5rem}
.v29-choice-intro{grid-template-columns:.42fr 1.3fr .72fr;gap:2rem;margin-bottom:1.8rem;align-items:end}
.v29-choice-intro h2{line-height:.8}
.v29-choice-intro h2 span:first-child{font-size:clamp(3.9rem,6.4vw,6.6rem)}
.v29-choice-intro h2 span:last-child{font-size:clamp(4.1rem,6.8vw,7rem)}
.v29-choice-intro>p:last-child{font-size:1rem;line-height:1.45}
.v29-booking .v15-service-copy strong{font-size:clamp(3.7rem,5.7vw,6.35rem)!important}

/* Archive: one composition exits before the final one enters. */
.v29-work-heading{opacity:var(--work-head-opacity,1);transform:translate3d(0,var(--work-head-y,0px),0);transition:opacity .08s linear;will-change:opacity,transform}
.v29-work-end{opacity:var(--work-end-opacity,0);transform:translate3d(0,var(--work-end-y,42px),0);will-change:opacity,transform}
.v29-work-end p,.v29-work-end strong{font-size:clamp(4.4rem,7.4vw,7.7rem)}

/* Story: photos occupy intentional gaps in the sentence, never destroy it. */
.v30-story{min-height:112vh}
.v30-story-inner{min-height:112vh;padding:10vh 0 7vh;justify-content:center}
.v30-story-title{position:relative;z-index:2;margin:1.2rem 0 0;display:flex;flex-direction:column;gap:.08em;font-family:var(--font-display);font-size:clamp(5.4rem,8.15vw,8.55rem);font-weight:900;line-height:.78;letter-spacing:-.045em;text-transform:uppercase}
.v30-story-line{display:grid;grid-template-columns:max-content minmax(210px,22vw) max-content;align-items:center;justify-content:space-between;gap:.12em;white-space:nowrap}
.v30-story-line-b{grid-template-columns:max-content minmax(190px,20vw) max-content}
.v30-story-slot{position:relative;display:block;height:1.03em;overflow:hidden;border:7px solid var(--v29-paper);box-shadow:9px 9px 0 rgba(0,0,0,.18);z-index:3;will-change:transform}
.v30-story-slot img,.v30-story-float img{object-fit:cover;transform:scale(1.055)}
.v30-slot-a{transform:translate3d(calc(var(--story-slot-a-x,0px) + var(--v29-x10)),calc(var(--story-slot-a-y,0px) + var(--v29-y5)),0) rotate(var(--story-a-rot,-4deg))}
.v30-slot-b{transform:translate3d(calc(var(--story-slot-b-x,0px) - var(--v29-x8)),calc(var(--story-slot-b-y,0px) - var(--v29-y5)),0) rotate(var(--story-b-rot,4deg))}
.v30-story-float{position:absolute;right:1.5%;bottom:18%;z-index:4;width:min(17vw,250px);height:min(10vw,150px);overflow:hidden;border:6px solid var(--v29-paper);box-shadow:8px 8px 0 rgba(0,0,0,.18);transform:translate3d(calc(var(--story-float-x,0px) + var(--v29-x8)),calc(var(--story-float-y,0px) + var(--v29-y5)),0) rotate(var(--story-c-rot,-3deg));will-change:transform}
.v30-story .v29-story-foot{margin-top:4.6rem}

/* Proof: retain impact without turning a paragraph into the entire screen. */
.v29-proof{padding:7.2rem 0 7.6rem}
.v29-proof-grid{grid-template-columns:.38fr 1.22fr;gap:5vw;align-items:center}
.v29-proof-count{top:132px}
.v29-proof-count>span{font-size:clamp(6.5rem,10vw,10.5rem);transform:translate3d(calc(var(--v29-x8) * -.65),calc(var(--v29-y5) * -.65),0) scale(var(--proof-count-scale,1))}
.v29-proof blockquote{max-width:920px;font-size:clamp(2.3rem,3.55vw,3.85rem);line-height:1.04;letter-spacing:-.038em;transform:translate3d(calc(var(--proof-quote-x,0px) + var(--v29-x10)),var(--proof-quote-y,0px),0)}
.v29-proof-ring{right:-5vw;top:-7vw;width:31vw;height:31vw;opacity:.2}

/* Beyond: abstract but legible. Nothing is allowed to crop its own headline. */
.v29-beyond{padding:5.5rem 0 7rem}
.v29-beyond-marquee{position:absolute;left:0;right:0;top:-1.2rem;opacity:.46;pointer-events:none}
.v29-beyond-marquee span{font-size:clamp(3.2rem,6.5vw,6.8rem)}
.v29-beyond-head{position:relative;z-index:2;margin:0 0 2.5rem;align-items:flex-end}
.v29-beyond-head h2{font-size:clamp(5rem,8.5vw,8.8rem);line-height:.78}
.v29-beyond-stage{gap:22px}
.v29-feature{min-height:590px}
.v29-feature>strong{font-size:clamp(3.5rem,5.3vw,5.65rem);line-height:.83}
.v29-feature-plus strong{font-size:clamp(3.45rem,5vw,5.35rem);max-width:100%}
.v29-feature-plus p{max-width:27rem}
.v29-beyond-stamp{width:122px;height:122px;font-size:1.15rem}

@media(max-width:1100px){
  .v30-story-title{font-size:clamp(4.6rem,8.4vw,7rem)}
  .v30-story-line{grid-template-columns:max-content minmax(150px,20vw) max-content}
  .v29-proof-grid{grid-template-columns:1fr;gap:2.8rem}
  .v29-proof-count{position:relative;top:auto}
}
@media(max-width:760px){
