  .v29-hero-title span:nth-child(2){font-size:clamp(4.3rem,17.5vw,6rem)}
  .v29-hero-title span:nth-child(3){font-size:clamp(4.9rem,19.5vw,6.8rem)}
  .v30-ribbon{height:122px}.v30-ribbon-track{height:128px}.v30-ribbon-svg{width:1680px;height:128px}.v30-ribbon-svg text{font-size:64px}
  .v29-choice{padding:3.4rem 0 4.5rem}
  .v29-choice-intro{gap:.8rem;margin-bottom:1.4rem}
  .v29-work-heading,.v29-work-end{opacity:1!important;transform:none!important}
  .v30-story{min-height:auto}.v30-story-inner{min-height:auto;padding:6.5rem 0}
  .v30-story-title{font-size:clamp(4.6rem,18vw,6.6rem);gap:.22em}
  .v30-story-line,.v30-story-line-b{display:flex;flex-wrap:wrap;justify-content:flex-start;gap:.08em .12em;white-space:normal}
  .v30-story-slot{order:3;width:72vw;height:42vw;margin:.1em auto 0;border-width:5px;transform:rotate(-3deg)!important}
  .v30-story-line-b .v30-story-slot{transform:rotate(3deg)!important}
  .v30-story-float{display:none}
  .v30-story .v29-story-foot{margin-top:2.5rem}
  .v29-proof{padding:5rem 0}.v29-proof blockquote{font-size:clamp(2.15rem,8.4vw,3.4rem);transform:none}.v29-proof-count>span{transform:none}
  .v29-beyond{padding-top:4.5rem}.v29-beyond-head h2{font-size:clamp(5rem,20vw,7rem)}.v29-feature>strong,.v29-feature-plus strong{font-size:clamp(3.55rem,14vw,5rem)}
}
@media(prefers-reduced-motion:reduce){.v30-ribbon-track,.v30-story-slot,.v30-story-float,.v30-hero-focus{transform:none!important}.v30-ribbon-track{left:-20vw}}

/* ============================================================
   V31 — HOMEPAGE MENU AS A SIGNATURE SCENE
   ============================================================ */
body:has(.v29-hero) .v31-home-menu{
  top:0!important;
  height:100svh!important;
  max-height:none!important;
  padding:0!important;
  overflow:hidden!important;
  border-radius:0!important;
  background:#0a0a0a!important;
  color:#f2eee3!important;
  z-index:39!important;
}
.v31-menu-shell{
  position:relative;
  display:grid;
  grid-template-rows:auto 1fr auto;
  width:100%;
  height:100%;
  padding:142px 34px 28px;
  overflow:hidden;
  isolation:isolate;
}
.v31-menu-shell::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  opacity:.16;
  background-image:radial-gradient(rgba(255,255,255,.22) .55px,transparent .55px);
  background-size:5px 5px;
  mix-blend-mode:soft-light;
  z-index:-1;
}
.v31-menu-shell::after{
  content:"";
  position:absolute;
  width:38vw;
  height:38vw;
  right:-15vw;
  bottom:-18vw;
  border:1px solid rgba(213,104,101,.42);
  border-radius:50%;
  pointer-events:none;
}
.v31-menu-topline{
  display:flex;
  justify-content:space-between;
  gap:2rem;
  padding-bottom:14px;
  border-bottom:1px solid rgba(242,238,227,.24);
  font-family:var(--font-display);
  font-size:.66rem;
  font-weight:800;
  letter-spacing:.16em;
  line-height:1;
  color:rgba(242,238,227,.56);
}
.v31-menu-grid{
  display:grid;
  grid-template-columns:minmax(0,1.25fr) minmax(320px,.75fr);
  gap:clamp(2rem,5vw,6rem);
  min-height:0;
  align-items:center;
}
.v31-menu-links{display:flex;flex-direction:column;align-self:center;min-width:0}
.v31-menu-link{
  position:relative;
  display:grid;
  grid-template-columns:48px minmax(0,1fr) minmax(170px,.42fr) 34px;
  align-items:center;
  min-height:92px;
  border-bottom:1px solid rgba(242,238,227,.18);
  color:#f2eee3;
  text-decoration:none;
  overflow:hidden;
  transition:color .22s ease,padding-left .28s cubic-bezier(.2,.8,.2,1),border-color .2s ease;
}
.v31-menu-link:first-child{border-top:1px solid rgba(242,238,227,.18)}
.v31-menu-link::before{
  content:"";
  position:absolute;
  inset:0;
  background:#d56865;
  transform:translateX(-101%);
  transition:transform .34s cubic-bezier(.2,.8,.2,1);
  z-index:-1;
}
.v31-menu-link:hover,.v31-menu-link:focus-visible{color:#0a0a0a;padding-left:12px;border-color:#d56865;outline:none}
.v31-menu-link:hover::before,.v31-menu-link:focus-visible::before{transform:translateX(0)}
.v31-menu-number{font-family:var(--font-display);font-size:.64rem;font-weight:900;letter-spacing:.14em;opacity:.55}
.v31-menu-name{font-family:var(--font-display);font-size:clamp(3.6rem,6.8vw,7rem);font-weight:900;line-height:.78;letter-spacing:-.035em;text-transform:uppercase;white-space:nowrap}
.v31-menu-note{font-size:.8rem;line-height:1.25;color:rgba(242,238,227,.48);transition:color .2s ease}
.v31-menu-link:hover .v31-menu-note,.v31-menu-link:focus-visible .v31-menu-note{color:rgba(10,10,10,.66)}
.v31-menu-arrow{justify-self:end;font-size:1.25rem;transition:transform .25s ease}
.v31-menu-link:hover .v31-menu-arrow,.v31-menu-link:focus-visible .v31-menu-arrow{transform:translate(4px,-4px)}
.v31-menu-visual{position:relative;height:min(58vh,620px);align-self:center}
.v31-menu-image-frame{position:absolute;inset:7% 0 5% 8%;overflow:hidden;background:#181818;transform:rotate(2deg);box-shadow:0 25px 80px rgba(0,0,0,.35)}
.v31-menu-image{object-fit:cover;filter:saturate(.92) contrast(1.03);animation:v31MenuImageIn .55s cubic-bezier(.2,.8,.2,1) both}
@keyframes v31MenuImageIn{from{opacity:0;transform:scale(1.08) translateY(16px)}to{opacity:1;transform:scale(1) translateY(0)}}
.v31-menu-scan{position:absolute;left:0;right:0;top:-15%;height:26%;background:linear-gradient(180deg,transparent,rgba(213,104,101,.22),transparent);transform:skewY(-7deg);animation:v31Scan 4.8s linear infinite;mix-blend-mode:screen}
@keyframes v31Scan{to{top:110%}}
.v31-menu-orbit{position:absolute;width:172px;height:172px;right:-18px;bottom:-18px;border:1px solid rgba(213,104,101,.7);border-radius:50%;display:grid;place-items:center;animation:v31Orbit 13s linear infinite}
.v31-menu-orbit span{position:absolute;width:245px;text-align:center;font-family:var(--font-display);font-size:.58rem;font-weight:900;letter-spacing:.24em;color:#d56865;transform:rotate(-16deg)}
@keyframes v31Orbit{to{transform:rotate(360deg)}}
.v31-menu-footer{display:grid;grid-template-columns:1fr auto;align-items:end;gap:2rem;padding-top:16px;border-top:1px solid rgba(242,238,227,.24)}
.v31-menu-secondary{display:flex;flex-wrap:wrap;gap:.55rem 1.35rem;max-width:820px}
.v31-menu-secondary a{font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:rgba(242,238,227,.66);text-decoration:none;transition:color .18s ease,transform .18s ease}
.v31-menu-secondary a:hover,.v31-menu-secondary a:focus-visible{color:#d56865;transform:translateY(-2px);outline:none}
.v31-menu-actions{display:flex;align-items:center;gap:1.6rem}
.v31-menu-actions>a{font-family:var(--font-display);font-size:.72rem;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#f2eee3;text-decoration:none}
.v31-menu-actions>a:last-child{display:flex;align-items:center;gap:1.2rem;min-height:48px;padding:0 18px;background:#d56865;color:#0a0a0a}
.v31-menu-actions>a:last-child span{font-size:1rem}

/* Keep the opener readable while the dark menu sits behind it. */
body:has(.v31-home-menu) .v29-menu-button{background:#f2eee3!important;color:#0a0a0a!important;border-color:#f2eee3!important}
body:has(.v31-home-menu) .home-logo-control{filter:none}

@media (hover:hover) and (pointer:fine){
  .v31-menu-image-frame{transition:transform .28s cubic-bezier(.2,.8,.2,1)}
  .v31-menu-visual:hover .v31-menu-image-frame{transform:rotate(0deg) scale(1.012)}
}

@media(max-width:900px){
  body:has(.v29-hero) .v31-home-menu{overflow-y:auto!important}
