/* ============================================================
   V33 — HOMEPAGE REFINEMENT PASS
   ============================================================ */

/* Reactive homepage logo and chrome */
body:has(.v29-hero){
  --home-logo-color:var(--v29-red);
  --home-menu-chrome:rgba(255,255,255,.92);
  --home-menu-border:rgba(255,255,255,.78);
  --home-menu-ink:#ffffff;
}
html[data-home-scene="choice"] body:has(.v29-hero),
html[data-home-scene="proof"] body:has(.v29-hero){
  --home-logo-color:#111111;
  --home-menu-chrome:rgba(242,236,223,.86);
  --home-menu-border:rgba(17,17,17,.6);
  --home-menu-ink:#111111;
}
html[data-home-scene="story"] body:has(.v29-hero),
html[data-home-scene="beyond"] body:has(.v29-hero),
html[data-home-scene="work"] body:has(.v29-hero),
html[data-home-scene="close"] body:has(.v29-hero){
  --home-logo-color:var(--v29-paper);
  --home-menu-chrome:rgba(10,10,10,.38);
  --home-menu-border:rgba(255,255,255,.72);
  --home-menu-ink:#ffffff;
}
.home-logo-mark{
  display:block;
  width:7.4rem;
  height:7.4rem;
  background:var(--home-logo-color);
  mask:url('/brand/every-detail-logo.png') center/contain no-repeat;
  -webkit-mask:url('/brand/every-detail-logo.png') center/contain no-repeat;
  filter:drop-shadow(0 8px 20px rgba(0,0,0,.22));
  transition:background-color .28s ease, transform .28s ease, filter .28s ease;
}
body:has(.v29-hero) .v29-menu-button{
  border-color:var(--home-menu-border);
  background:var(--home-menu-chrome);
  color:var(--home-menu-ink);
  transition:background-color .28s ease, border-color .28s ease, color .28s ease;
}
body:has(.v29-hero) .v29-menu-button:hover{background:var(--v29-paper);color:var(--v29-ink)}

/* Simpler pull-down menu */
body:has(.v29-hero) .v33-home-menu{
  background:#f4efe4!important;
  color:var(--v29-ink)!important;
}
.v33-menu-shell{
  display:grid;
  grid-template-rows:auto 1fr auto;
  height:100%;
  padding:132px clamp(28px,4vw,56px) 28px;
}
.v33-menu-topline{
  display:flex;
  justify-content:space-between;
  gap:1rem;
  padding-bottom:16px;
  border-bottom:1px solid rgba(17,17,17,.14);
  color:rgba(17,17,17,.62);
  font-family:var(--font-display);
  font-size:.72rem;
  font-weight:800;
  letter-spacing:.12em;
  text-transform:uppercase;
}
.v33-menu-main{
  display:grid;
  align-content:start;
  gap:0;
  padding:20px 0 14px;
}
.v33-menu-link{
  display:grid;
  grid-template-columns:46px minmax(0,1fr) 28px;
  align-items:center;
  min-height:72px;
  border-bottom:1px solid rgba(17,17,17,.14);
  color:inherit;
  text-decoration:none;
  transition:padding .22s ease, color .22s ease, background-color .22s ease;
}
.v33-menu-link:hover,
.v33-menu-link[aria-current="page"]{
  padding-left:10px;
  color:var(--v29-red);
  background:rgba(223,52,64,.035);
}
.v33-menu-number,
.v33-menu-arrow{
  font-family:var(--font-display);
  font-size:.76rem;
  font-weight:900;
  letter-spacing:.14em;
  text-transform:uppercase;
}
.v33-menu-name{
  font-family:var(--font-display);
  font-size:clamp(2.5rem,4.7vw,4.8rem);
  font-weight:900;
  line-height:.86;
  letter-spacing:-.05em;
  text-transform:uppercase;
}
.v33-menu-arrow{justify-self:end;font-size:1rem}
.v33-menu-bottom{
  display:grid;
  grid-template-columns:1fr auto;
  gap:1.5rem 2rem;
  align-items:end;
  padding-top:18px;
  border-top:1px solid rgba(17,17,17,.14);
}
.v33-menu-secondary{
  display:flex;
  flex-wrap:wrap;
  gap:.7rem 1.1rem;
  color:rgba(17,17,17,.72);
  font-family:var(--font-display);
  font-size:.78rem;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.v33-menu-actions{display:flex;flex-wrap:wrap;gap:.8rem}
.v33-menu-actions>a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:48px;
  padding:0 18px;
  border:1px solid rgba(17,17,17,.82);
  color:var(--v29-ink);
  font-family:var(--font-display);
  font-size:.82rem;
  font-weight:900;
  letter-spacing:.13em;
  text-transform:uppercase;
  text-decoration:none;
  transition:background-color .2s ease, color .2s ease, border-color .2s ease;
}
.v33-menu-actions>a:last-child{background:var(--v29-ink);color:var(--v29-paper)}
.v33-menu-actions>a:hover{background:var(--v29-red);border-color:var(--v29-red);color:#fff}
@media(min-width:901px){
  body:has(.v29-hero) .v33-home-menu{
    top:0!important;
    bottom:auto!important;
    height:min(560px,64svh)!important;
    max-height:560px!important;
    overflow:hidden!important;
    border-radius:0 0 28px 28px!important;
    box-shadow:0 24px 60px rgba(0,0,0,.22);
    animation:v33PullMenu .38s cubic-bezier(.16,1,.3,1) both;
  }
  @keyframes v33PullMenu{from{transform:translateY(-104%)}to{transform:translateY(0)}}
}
@media(max-width:900px){
  body:has(.v29-hero) .v33-home-menu{
    top:0!important;
    height:100svh!important;
    max-height:none!important;
    border-radius:0!important;
    padding-top:0!important;
  }
  .v33-menu-shell{padding:116px 18px 22px}
  .v33-menu-topline{display:block;padding-bottom:12px}
  .v33-menu-topline span+span{display:none}
  .v33-menu-link{grid-template-columns:34px minmax(0,1fr) 20px;min-height:60px}
