  opacity:0;
  will-change:transform,opacity;
}
.v36-proof-review-1{opacity:var(--proof-r1);transform:translate3d(-50%,calc(-50% + (1 - var(--proof-r1))*54px),0) scale(calc(.97 + var(--proof-r1)*.03))}
.v36-proof-review-2{opacity:var(--proof-r2);transform:translate3d(-50%,calc(-50% + (1 - var(--proof-r2))*54px),0) scale(calc(.97 + var(--proof-r2)*.03))}
.v36-proof-review-3{opacity:var(--proof-r3);transform:translate3d(-50%,calc(-50% + (1 - var(--proof-r3))*54px),0) scale(calc(.97 + var(--proof-r3)*.03))}
.v36-proof-index{display:block;margin-bottom:1rem;color:var(--v29-red);font-family:var(--font-display);font-size:.82rem;font-weight:900;letter-spacing:.14em;text-transform:uppercase}
