  .v36-home-menu .v33-menu-actions{display:grid;grid-template-columns:1fr 1fr;width:100%}
  .v36-home-menu .v33-menu-actions>a{min-height:48px;padding:0 10px;font-size:.72rem}

  /* Hero composed for portrait screens. */
  .v29-hero{min-height:100svh}
  .v29-hero-inner{min-height:100svh;padding:128px 0 52px;justify-content:center}
  .v29-hero-kicker{font-size:.68rem;letter-spacing:.18em;margin-bottom:1rem}
  .v29-hero-title{width:100%;gap:.04em;line-height:.77}
  .v29-hero-title span:nth-child(1){font-size:clamp(4.8rem,20vw,7rem)}
