  .v29-hero-cta{margin-top:1.5rem;min-height:52px}
  .v30-hero-focus{width:96vw;height:58vh}

  /* Tape becomes a compact but still physical transition. */
  .v36-tape{height:142px;margin-top:-4px;margin-bottom:-10px}
  .v36-tape-svg{height:150px;width:1320px;max-width:none;transform:translateX(-25%)}
  .v36-tape-text{font-size:58px}

  .v29-choice{padding:4.4rem 0 4.8rem}
  .v29-choice-intro{display:grid;grid-template-columns:1fr;gap:.65rem;margin-bottom:1.6rem}
  .v29-choice-intro h2{white-space:normal;display:block;line-height:.82}
  .v29-choice-intro h2 span{display:block}
  .v29-choice-intro h2 span:first-child{font-size:clamp(4rem,17vw,6rem)!important}
  .v29-choice-intro h2 span:last-child{font-size:clamp(3.8rem,15.8vw,5.7rem)!important}
  .v29-choice-intro>p:last-child{max-width:25rem;font-size:.96rem}
  .v29-booking{margin-top:.5rem}

  /* Work becomes an art-directed vertical contact sheet on touch. */
  .v29-work{height:auto;padding:5.2rem 0 5.4rem}
  .v29-work-sticky{position:relative;height:auto;overflow:visible;padding:0}
  .v29-work-heading{position:relative;top:auto;margin-bottom:2rem}
  .v29-work-heading h2{font-size:clamp(4rem,17vw,6.4rem);line-height:.8}
  .v29-work-track{display:grid!important;grid-template-columns:1fr;gap:16px;width:auto!important;padding:0 14px!important;transform:none!important}
  .v29-shot-a,.v29-shot-b,.v29-shot-c,.v29-shot-d{grid-column:auto;width:100%!important;height:72vw!important;max-height:460px}
  .v29-shot-b,.v29-shot-d{width:86%!important;margin-left:auto}
