  .v29-work-end{width:100%;min-width:0;padding:3.3rem 0 .5rem}
  .v29-work-end p,.v29-work-end strong{font-size:clamp(4rem,17vw,6.3rem);max-width:8ch}

  /* Story: giant statement, collage overlaps but stays inside viewport. */
  .v36-story{min-height:auto}
  .v36-story-inner{min-height:auto;padding:5.8rem 0 5rem;display:block}
  .v36-story-title{display:flex;flex-direction:column;gap:.02em;font-size:clamp(4.6rem,19vw,7rem);line-height:.8}
  .v36-story-title span:nth-child(even),.v36-story-title span:nth-child(odd){text-align:left}
  .v36-story-title span:nth-child(2),.v36-story-title span:nth-child(4){padding-left:10vw}
  .v36-story-collage{position:relative;left:auto;top:auto;width:100%;height:108vw;max-height:620px;transform:none;margin:-7vw 0 -4vw;z-index:3}
  .v36-story-photo{border-width:7px;box-shadow:8px 10px 0 rgba(62,16,18,.22)}
  .v36-story-photo-a{left:8%;top:7%;width:82%;height:43%}
  .v36-story-photo-b{left:0;top:45%;width:70%;height:33%}
  .v36-story-photo-c{right:2%;bottom:2%;width:50%;height:29%}
  .v36-story-foot{grid-template-columns:1fr;margin-top:1.6rem}

  /* Review sequence stays pinned but reads cleanly on a tall phone. */
  .v36-proof{height:330svh}
  .v36-proof-review{width:calc(100vw - 36px)}
  .v36-proof-count strong{font-size:clamp(11rem,54vw,19rem)}
  .v36-proof-count>span{font-size:clamp(1.9rem,9vw,3.3rem)}
  .v36-proof-review p{font-size:clamp(3rem,13.5vw,5.2rem);line-height:.92}
  .v36-proof-index{font-size:.72rem}
  .v36-proof-review footer{font-size:.68rem}

  /* Beyond the reset: stack scenes, retain hierarchy. */
  .v32-beyond{padding-top:5rem;padding-bottom:4rem}
  .v32-beyond-head{grid-template-columns:1fr;gap:.75rem;margin-bottom:2rem}
  .v32-beyond-head h2{font-size:clamp(4.4rem,18vw,6.5rem);line-height:.82}
  .v32-care-scene{min-height:620px}
  .v32-care-copy{left:20px;right:20px;bottom:28px;max-width:none}
