  .v35-care-maintain{min-height:650px;margin-top:-2.5vh;clip-path:polygon(0 3%,100% 0,100% 100%,0 100%)}
  .v35-maintain-cadence{left:20px;right:20px;bottom:24px;justify-content:space-between;font-size:.83rem;gap:.35rem}
  .v35-maintain-ghost{font-size:30vw;bottom:.22em}

  .v29-close{min-height:760px}
  .v29-close-inner{min-height:760px;justify-content:flex-end;padding-bottom:6rem}
  .v29-close h2{font-size:clamp(4.7rem,19vw,7rem);line-height:.78}
}

@media(max-width:520px){
  .home-logo-mark{width:5.1rem;height:5.1rem}
  body:has(.v29-hero) .v29-menu-button{min-width:72px;height:42px}
  .v29-menu-label{font-size:.62rem}
  .v29-hero-inner{padding-top:118px}
  .v29-hero-kicker{max-width:24ch;text-align:center;line-height:1.4}
  .v36-tape-svg{width:1180px;transform:translateX(-32%)}
  .v29-choice-intro h2 span:first-child{font-size:16.5vw!important}
  .v29-choice-intro h2 span:last-child{font-size:14.8vw!important}
  .v36-story-title{font-size:18.2vw}
  .v36-story-title span:nth-child(2),.v36-story-title span:nth-child(4){padding-left:6vw}
  .v36-story-collage{height:112vw;margin-top:-4vw}
  .v36-proof-review p{font-size:12.7vw}
  .v32-care-copy>strong,.v35-maintain-copy>strong{font-size:15vw}
}

@media(pointer:coarse){
  .v36-story-photo{transform:rotate(0deg)}
}
@media(prefers-reduced-motion:reduce){
  .v36-story-photo,.v36-proof-count,.v36-proof-review,.v36-tape-text{transform:none!important;transition:none!important}
  .v36-proof{height:auto;padding:5rem 0}
  .v36-proof-sticky{position:relative;height:auto;overflow:visible}
  .v36-proof-stage{display:grid;gap:2rem;height:auto}
  .v36-proof-count{position:relative;inset:auto;opacity:1;transform:none}
  .v36-proof-reviews{position:relative;inset:auto;display:grid;gap:1rem}
  .v36-proof-review{position:relative;left:auto;top:auto;width:auto;opacity:1!important;transform:none!important}
  .v36-proof-progress{display:none}
}

/* ============================================================
   V37 — COMPOSITION FIRST
   ============================================================ */

/* Tape: use it as the handoff, not as a decorative stripe. */
.v36-tape{
  height:236px;
  margin-top:-28px;
  margin-bottom:-58px;
  background:var(--v29-paper);
  overflow:hidden;
  z-index:7;
}
.v36-tape-svg{
  width:calc(100% + 60px);
  height:252px;
  margin-left:-30px;
  overflow:visible;
  filter:drop-shadow(0 8px 0 rgba(79,27,29,.10));
}
.v36-tape-text{
  font-size:68px;
  letter-spacing:-.025em;
}
.v29-choice{padding-top:8.6rem}

/* Story: two statements, one playful seam of photography. */
.v37-story{
  position:relative;
  min-height:118svh;
  overflow:hidden;
  background:linear-gradient(180deg,#6e292d 0%,#c95f5d 22%,var(--v29-red) 58%,#da706e 100%);
  color:var(--v29-paper);
  isolation:isolate;
}
.v37-story::before{
  content:"";
  position:absolute;
  inset:0;
  opacity:.10;
  background-image:radial-gradient(circle at 1px 1px,rgba(255,255,255,.38) 1px,transparent 1px);
  background-size:9px 9px;
  mask-image:linear-gradient(to bottom,transparent,black 18%,black 84%,transparent);
}
.v37-story-inner{
  position:relative;
  min-height:118svh;
  padding:10vh 0 7vh;
  display:flex;
  flex-direction:column;
  justify-content:center;
}
.v37-story-inner>.v29-kicker{position:relative;z-index:5;margin:0 0 1rem;color:rgba(242,236,223,.8)}
.v37-story-title{
  position:relative;
  z-index:2;
  margin:0;
  display:grid;
  gap:min(31vh,260px);
  font-family:var(--font-display);
  font-size:clamp(6rem,9vw,9.6rem);
  font-weight:900;
  line-height:.8;
  letter-spacing:-.055em;
  text-transform:uppercase;
}
.v37-story-title span:first-child{max-width:9.8ch}
.v37-story-title span:last-child{max-width:10.3ch;margin-left:auto;text-align:right}
.v37-story-collage{
  position:absolute;
  z-index:4;
  left:50%;
  top:50%;
  width:min(67vw,980px);
  height:min(48vh,470px);
  transform:translate(-50%,-50%);
  pointer-events:none;
}
.v37-story-photo{
  position:absolute;
  overflow:hidden;
  display:block;
  border:9px solid var(--v29-paper);
  background:#ddd;
  box-shadow:15px 18px 0 rgba(65,16,18,.22);
  opacity:var(--story-photo-opacity,1);
  scale:var(--story-photo-scale,.9);
  will-change:transform,opacity;
}
.v37-story-photo-a{
  left:18%;top:0;width:58%;height:62%;
  transform:translate3d(calc(var(--story-a-x,0px)*.28),calc(var(--story-a-y,0px)*.22),0) rotate(var(--story-a-rot,-4deg));
}
.v37-story-photo-b{
  left:0;bottom:0;width:48%;height:47%;
  transform:translate3d(calc(var(--story-b-x,0px)*.23),calc(var(--story-b-y,0px)*.18),0) rotate(var(--story-b-rot,5deg));
}
.v37-story-photo-c{
  right:2%;bottom:5%;width:32%;height:44%;
  transform:translate3d(calc(var(--story-c-x,0px)*.20),calc(var(--story-c-y,0px)*.18),0) rotate(var(--story-c-rot,-3deg));
}
.v37-story-foot{
  position:relative;
  z-index:5;
  margin-top:2.8rem;
  width:min(100%,760px);
  display:grid;
  grid-template-columns:1fr auto;
  gap:1.4rem 2rem;
  align-items:end;
  padding-top:1.2rem;
  border-top:1px solid rgba(242,236,223,.48);
}
.v37-story-foot p{margin:0;max-width:40rem;color:rgba(242,236,223,.86);font-size:1rem;line-height:1.55}
.v37-story-foot a{color:var(--v29-paper);font-family:var(--font-display);font-size:.76rem;font-weight:900;letter-spacing:.13em;text-transform:uppercase}

/* Reviews: count compresses into a proof marker, reviews own the stage. */
.v37-proof{
  --proof-count-out:0;
  --proof-r1:0;
  --proof-r2:0;
  --proof-r3:0;
  position:relative;
  height:350svh;
  background:#080808;
  color:var(--v29-paper);
}
.v37-proof-sticky{
  position:sticky;
  top:0;
  height:100svh;
  overflow:hidden;
  background:
    radial-gradient(circle at 82% 18%,rgba(213,104,101,.09),transparent 34%),
    #080808;
}
.v37-proof-sticky::before{
  content:"";
  position:absolute;
  inset:0;
  opacity:.22;
  background-image:radial-gradient(circle at 1px 1px,rgba(255,255,255,.10) 1px,transparent 1px);
  background-size:10px 10px;
  mask-image:linear-gradient(to right,black,transparent 72%);
}
.v37-proof-stage{position:relative;height:100%}
.v37-proof-count{
  position:absolute;
  left:50%;
  top:50%;
  width:min(1120px,88vw);
  transform:
    translate3d(calc(-50% - var(--proof-count-out)*35vw),calc(-50% - var(--proof-count-out)*25vh),0)
    scale(calc(1 - var(--proof-count-out)*.52));
  transform-origin:center;
  opacity:1;
  will-change:transform;
}
.v37-proof-count>p{
  margin:0 0 .45rem;
  color:rgba(242,236,223,.68);
  font-family:var(--font-display);
  font-size:.76rem;
  font-weight:900;
  letter-spacing:.16em;
  text-transform:uppercase;
}
.v37-proof-count strong{
  display:block;
  color:var(--v29-red);
  font-family:var(--font-display);
  font-size:clamp(12rem,31vw,28rem);
  font-weight:900;
  line-height:.62;
  letter-spacing:-.085em;
}
.v37-proof-count>span{
  display:block;
  margin-top:1.3rem;
  font-family:var(--font-display);
  font-size:clamp(1.6rem,3vw,3.25rem);
  font-weight:900;
  line-height:.9;
  letter-spacing:-.025em;
  text-transform:uppercase;
}
.v37-proof-copy{
  position:absolute;
  left:5vw;
  top:8vh;
  max-width:32rem;
  opacity:var(--proof-count-out);
  transform:translate3d(0,calc((1 - var(--proof-count-out))*24px),0);
}
.v37-proof-copy .v29-kicker{margin:0 0 .7rem}
.v37-proof-copy h2{
  margin:0;
  font-family:var(--font-display);
  font-size:clamp(3.6rem,5.2vw,5.8rem);
  font-weight:900;
  line-height:.84;
  letter-spacing:-.045em;
  text-transform:uppercase;
}
.v37-proof-reviews{position:absolute;inset:0;pointer-events:none}
.v37-proof-review{
  position:absolute;
  right:4vw;
  top:50%;
  width:min(720px,52vw);
  padding:clamp(1.4rem,2.4vw,2.4rem) 0;
  opacity:0;
  transform:translate3d(7vw,-50%,0);
  will-change:transform,opacity;
}
.v37-proof-review-1{opacity:var(--proof-r1);transform:translate3d(calc((1 - var(--proof-r1))*7vw),-50%,0)}
.v37-proof-review-2{opacity:var(--proof-r2);transform:translate3d(calc((1 - var(--proof-r2))*7vw),-50%,0)}
.v37-proof-review-3{opacity:var(--proof-r3);transform:translate3d(calc((1 - var(--proof-r3))*7vw),-50%,0)}
.v37-proof-index{
  display:block;
  margin-bottom:1rem;
  color:var(--v29-red);
  font-family:var(--font-display);
  font-size:.76rem;
  font-weight:900;
  letter-spacing:.15em;
  text-transform:uppercase;
}
.v37-proof-review p{
  margin:0;
  font-family:var(--font-display);
  font-size:clamp(3rem,4.6vw,5.4rem);
  font-weight:800;
  line-height:.94;
  letter-spacing:-.04em;
  text-wrap:balance;
}
.v37-proof-review footer{
  margin-top:1.45rem;
  padding-top:.85rem;
  border-top:1px solid rgba(242,236,223,.24);
  color:rgba(242,236,223,.62);
  font-family:var(--font-display);
  font-size:.74rem;
  font-weight:900;
  letter-spacing:.13em;
  text-transform:uppercase;
}
.v37-proof-rail{
  position:absolute;
  left:5vw;
  right:5vw;
  bottom:5vh;
  height:3px;
  background:rgba(242,236,223,.14);
}
.v37-proof-rail span{display:block;height:100%;width:var(--proof-progress,4%);background:var(--v29-red)}

/* Maintain: photography + red wash + cadence, no UI chips. */
.v37-beyond{padding-bottom:5.5rem}
.v37-maintain{
  position:relative;
  display:block;
  min-height:76svh;
  margin-top:-4vh;
  overflow:hidden;
  color:var(--v29-paper);
  text-decoration:none;
  background:#6f282b;
  clip-path:polygon(0 7%,100% 0,100% 100%,0 100%);
  isolation:isolate;
}
.v37-maintain-photo{
  position:absolute;
  z-index:0;
  right:0;
  top:0;
  width:46%;
  height:100%;
  overflow:hidden;
  filter:saturate(.88) contrast(1.05);
  transform:translate3d(calc((1 - var(--beyond-progress,.5))*6vw),0,0) scale(1.04);
}
.v37-maintain-photo::after{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(90deg,#7a2d30 0%,rgba(122,45,48,.82) 17%,rgba(122,45,48,.16) 72%,rgba(0,0,0,.18));
}
.v37-maintain-wash{
  position:absolute;
  z-index:1;
  inset:0;
  background:linear-gradient(105deg,var(--v29-red) 0 58%,rgba(213,104,101,.92) 68%,rgba(213,104,101,.18) 100%);
  transform:translate3d(calc(var(--beyond-progress,.5)*-7vw),0,0);
  opacity:.93;
}
.v37-maintain-ghost{
  position:absolute;
  z-index:2;
  left:-.02em;
  bottom:-.16em;
