  padding:.34em .48em .3em;
  background:var(--v29-ink);
  color:var(--v29-paper);
  font-size:clamp(1.35rem,2.2vw,2.2rem);
  line-height:1;
  letter-spacing:.04em;
  transform:translate3d(0,var(--life-c-y,0px),0) rotate(-5deg);
}
.v39-life-d{
  grid-column:2;
  color:var(--v29-red);
  font-size:clamp(5.4rem,10vw,10.2rem);
  white-space:nowrap;
  transform:translate3d(var(--life-d-x,0px),0,0) rotate(-.6deg);
}
.v39-clean-life+ .v29-close{z-index:1}

@media(max-width:900px){
  .v36-tape{
