  .v38-proof-review{
    left:20px!important;
    right:20px!important;
    width:auto!important;
  }
  .v38-proof-review-1{transform:translate3d(0,calc(-50% + var(--proof-r1-y,18px)),0)!important}
  .v38-proof-review-2{transform:translate3d(0,calc(-50% + var(--proof-r2-y,18px)),0)!important}
  .v38-proof-review-3{transform:translate3d(0,calc(-50% + var(--proof-r3-y,18px)),0)!important}
  .v38-proof-review p{font-size:clamp(2.55rem,10.6vw,4.1rem)!important;line-height:.96!important}

  .v39-clean-life{
    min-height:68svh;
    margin-top:-38px;
    margin-bottom:-34px;
    border-radius:0 0 50% 50% / 0 0 7% 7%;
  }
  .v39-clean-life::before{top:-52px;height:104px}
  .v39-clean-life-inner{
