  }
  .v39-life-d{grid-column:1;white-space:normal;text-align:center}
}

@media(max-width:520px){
  body:has(.v29-hero) .home-logo-control{top:max(14px,env(safe-area-inset-top))!important}
  .v36-tape-svg{width:1220px!important;transform:translateX(-29%)!important}
  .v39-clean-life{min-height:64svh}
  .v39-clean-life-inner{min-height:64svh;padding:6rem 0 5.4rem}
  .v39-life-a,.v39-life-b,.v39-life-d{font-size:clamp(3.9rem,18.5vw,5.8rem)}
}

@media(prefers-reduced-motion:reduce){
  .v39-life-word,
  .v38-proof-count,
  .v38-proof-review{transform:none!important;transition:none!important}
}

/* V39 arc correction: let the clean-car interlude physically overlap both neighbors. */
.v39-clean-life{overflow:visible!important}
.v39-clean-life::before{z-index:0!important}
.v39-clean-life-grain{z-index:1}
.v39-clean-life-inner{position:relative;z-index:2}

/* ============================================================
   V40 — SITEWIDE ART DIRECTION
   Shared system for every non-home page.
   ============================================================ */

:root{
  --site-red:#D56865;
  --site-red-dark:#763132;
  --site-ink:#0b0b0b;
  --site-paper:#f3eddf;
  --site-paper-2:#e9e0d0;
  --site-line:rgba(11,11,11,.16);
  --site-shadow:0 22px 60px rgba(20,10,8,.16),0 4px 12px rgba(20,10,8,.08);
  --site-ease:cubic-bezier(.16,1,.3,1);
}

html:not([data-route="/"]) body{
  background:var(--site-paper);
  color:var(--site-ink);
}
html:not([data-route="/"]) main{
  overflow:clip;
  background:var(--site-paper);
}
html:not([data-route="/"]) main::before{
  content:"";
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:1000;
  opacity:.20;
  mix-blend-mode:multiply;
  background-image:
    radial-gradient(circle at 20% 30%,rgba(40,20,12,.055) 0 1px,transparent 1.3px),
    radial-gradient(circle at 78% 63%,rgba(40,20,12,.035) 0 1px,transparent 1.2px);
  background-size:9px 9px,13px 13px;
}

/* Non-home header */
html:not([data-route="/"]) .site-header,
html:not([data-route="/"]) header[class*="site"],
html:not([data-route="/"]) body>header{
  --header-bg:rgba(11,11,11,.90);
}
html:not([data-route="/"]) .inner-header,
html:not([data-route="/"]) .home-header{
  background:rgba(10,10,10,.88)!important;
  border-bottom:1px solid rgba(255,255,255,.12)!important;
  backdrop-filter:blur(16px) saturate(.85);
}
html:not([data-route="/"]) .inner-logo{width:64px!important;height:64px!important}
html:not([data-route="/"]) .inner-header a,
html:not([data-route="/"]) .inner-header button{letter-spacing:.08em}

/* Shared reveal language */
@media (prefers-reduced-motion:no-preference){
  html:not([data-route="/"]) main section.site-reveal-ready{
    opacity:.001;
    transform:translateY(32px);
    transition:opacity .72s var(--site-ease),transform .72s var(--site-ease);
  }
  html:not([data-route="/"]) main section.site-reveal-ready.site-reveal-in{
    opacity:1;
    transform:none;
  }
  html:not([data-route="/"]) main figure,
  html:not([data-route="/"]) main [class*="photo"],
  html:not([data-route="/"]) main [class*="media"]{
    --site-pointer-x:0;
    --site-pointer-y:0;
  }
}

/* Shared page header */
.site-page-header{
  position:relative;
  overflow:hidden;
  padding:clamp(7.5rem,12vw,10rem) 0 clamp(3.8rem,7vw,6.5rem);
  color:var(--site-paper);
  background:
    linear-gradient(180deg,rgba(0,0,0,.16),transparent 50%),
    radial-gradient(circle at 78% 22%,rgba(213,104,101,.28),transparent 28%),
    linear-gradient(135deg,#111 0%,#0b0b0b 66%,#261516 100%);
}
.site-page-header::after{
  content:"";
  position:absolute;
  left:-6%;right:-6%;bottom:-46px;height:90px;
  border-radius:50% 50% 0 0/100% 100% 0 0;
  background:var(--site-paper);
}
.site-page-header-inner{position:relative;z-index:2}
.site-page-header-top{
  display:flex;justify-content:space-between;align-items:center;gap:1rem;
  padding-bottom:18px;border-bottom:1px solid rgba(255,255,255,.18);
  font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase;
  color:rgba(243,237,223,.62);
}
.site-page-header-top a{color:inherit}
.site-page-header-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:2rem;margin-top:clamp(2.6rem,5vw,5rem)}
.site-page-header-grid.has-aside{grid-template-columns:minmax(0,1.05fr) minmax(320px,.95fr);align-items:end}
.site-page-header-copy h1{
  margin:0;max-width:12ch;font-family:var(--font-display);font-size:clamp(4.6rem,8vw,8.8rem);font-weight:900;line-height:.84;letter-spacing:-.055em;text-transform:uppercase;
}
.site-page-header-copy h1 br+span,
.site-page-header-copy h1 span{color:var(--site-red)}
.site-page-header-lede{max-width:42rem;margin-top:1.5rem;color:rgba(243,237,223,.72);font-size:clamp(1rem,1.35vw,1.2rem);line-height:1.55}
.site-page-header-actions{display:flex;flex-wrap:wrap;gap:.8rem;margin-top:1.8rem}
.site-page-header-aside{transform:translate3d(calc(var(--site-pointer-x)*5px),calc(var(--site-pointer-y)*5px),0);transition:transform .25s ease-out}
.site-page-header-aside img{box-shadow:var(--site-shadow)}

/* Shared CTA */
.site-cta-band{position:relative;overflow:hidden;background:var(--site-red);color:var(--site-paper);padding:clamp(5rem,8vw,8rem) 0}
.site-cta-band::before{content:"";position:absolute;inset:0;background:linear-gradient(115deg,rgba(0,0,0,.18),transparent 40%,rgba(255,255,255,.06));pointer-events:none}
.site-cta-word{position:absolute;left:-2%;top:-.18em;white-space:nowrap;font-family:var(--font-display);font-size:clamp(8rem,18vw,18rem);font-weight:900;line-height:1;color:rgba(243,237,223,.08);letter-spacing:-.06em;transform:translateX(calc(var(--site-scroll,0)*-9vw));}
.site-cta-inner{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.2fr) auto;gap:2rem;align-items:end}
.site-cta-kicker{margin:0 0 .8rem;font-family:var(--font-display);font-size:.76rem;font-weight:900;letter-spacing:.14em;text-transform:uppercase}
.site-cta-inner h2{margin:0;max-width:9ch;font-family:var(--font-display);font-size:clamp(4rem,7vw,7.6rem);font-weight:900;line-height:.84;letter-spacing:-.055em;text-transform:uppercase}
.site-cta-inner>div>p:not(.site-cta-kicker){max-width:38rem;margin:1rem 0 0;color:rgba(243,237,223,.78);font-size:1.02rem;line-height:1.55}
.site-cta-actions{display:flex;flex-direction:column;gap:.7rem;min-width:210px}
.site-cta-primary,.site-cta-secondary{display:flex;justify-content:space-between;align-items:center;gap:1rem;min-height:54px;padding:0 18px;border:1px solid rgba(243,237,223,.72);font-family:var(--font-display);font-size:.78rem;font-weight:900;letter-spacing:.12em;text-transform:uppercase;text-decoration:none}
.site-cta-primary{background:var(--site-paper);color:var(--site-ink)}
.site-cta-secondary{color:var(--site-paper)}

/* Footer */
.site-footer{position:relative;background:#090909;color:var(--site-paper);border-top:1px solid rgba(255,255,255,.12)}
.site-footer-grid{display:grid;grid-template-columns:1.7fr .7fr .7fr 1fr;gap:clamp(2rem,4vw,5rem);padding:clamp(4.5rem,7vw,7rem) 0 3.5rem}
.site-footer-brand img{width:92px;height:92px;object-fit:contain}
.site-footer-brand h2{margin:1.5rem 0 0;font-family:var(--font-display);font-size:clamp(2.8rem,4vw,4.7rem);line-height:.84;letter-spacing:-.045em;text-transform:uppercase}
.site-footer-brand h2 span{color:var(--site-red)}
.site-footer-brand p{max-width:28rem;color:rgba(243,237,223,.62)}
.site-footer-book{display:inline-flex;margin-top:1rem;color:var(--site-paper);font-family:var(--font-display);font-weight:900;letter-spacing:.11em;text-transform:uppercase}
.site-footer-column{display:flex;flex-direction:column;gap:.62rem}
.site-footer-column h3{margin:0 0 .45rem;color:var(--site-red);font-family:var(--font-display);font-size:.76rem;letter-spacing:.14em;text-transform:uppercase}
.site-footer-column a{color:rgba(243,237,223,.72);text-decoration:none}
.site-footer-column a:hover{color:var(--site-paper)}
.site-footer-contact p{margin-top:1rem;color:rgba(243,237,223,.48);font-size:.82rem}
.site-footer-bottom{display:grid;grid-template-columns:1fr 1fr auto;gap:1rem;padding:1.2rem 0 1.6rem;border-top:1px solid rgba(255,255,255,.10);color:rgba(243,237,223,.45);font-family:var(--font-display);font-size:.68rem;letter-spacing:.1em;text-transform:uppercase}
.site-footer-bottom a{color:inherit}

/* ================= BRAND / STORY PAGES ================= */
.about-v2,.work-page-v18,.plus-brand,.paint-v38,.gift-page{
  --page-accent:var(--site-red);
  background:var(--site-paper);
}
.about-v2 h1,.about-v2 h2,.work-page-v18 h1,.work-page-v18 h2,.plus-brand h1,.plus-brand h2,.paint-v38 h1,.paint-v38 h2,.gift-page h1,.gift-page h2{
