  width:8px;
  height:8px;
  flex:0 0 auto;
  border-radius:50%;
  background:var(--v29-red);
  box-shadow:0 0 0 4px rgba(213,104,101,.14);
}
.home-school-availability-copy{display:flex;align-items:baseline;gap:.55rem;white-space:nowrap}
.home-school-availability-copy strong,
.home-school-availability-copy span,
.home-school-availability i{
  font-family:var(--font-display);
  font-style:normal;
  text-transform:uppercase;
}
.home-school-availability-copy strong{font-size:.72rem;font-weight:900;letter-spacing:.15em}
.home-school-availability-copy span{font-size:.64rem;font-weight:800;letter-spacing:.11em;color:rgba(243,237,223,.7)}
.home-school-availability i{margin-left:.08rem;font-size:.88rem;font-weight:900}
.home-school-availability-mobile{display:none}

@media(max-width:900px){
  .home-school-availability{
    left:14px;
    top:max(22px,calc(env(safe-area-inset-top) + 10px));
    min-height:42px;
    padding:0 11px;
    gap:.55rem;
    border-color:rgba(243,237,223,.36);
  }
  .home-school-availability-desktop{display:none}
  .home-school-availability-mobile{display:inline}
  .home-school-availability-copy{gap:.42rem}
  .home-school-availability-copy strong{font-size:.64rem;letter-spacing:.13em}
  .home-school-availability-copy span{font-size:.59rem}
  .home-school-availability-dot{width:7px;height:7px;box-shadow:0 0 0 3px rgba(213,104,101,.14)}
}

@media(max-width:420px){
  .home-school-availability{left:10px;min-height:40px;padding-inline:10px}
  .home-school-availability-copy strong{font-size:.61rem}
  .home-school-availability-copy span{font-size:.56rem}
}

@media(prefers-reduced-motion:reduce){
  .home-school-availability{transition:none}
}

/* ============================================================
   V46 — curved scroll-reactive tape (hero → choice transition)
   One curve: paper below it, red ribbon on it, text riding it.
   Drift is constant; scroll velocity speeds it up (CurvedTape.tsx).
   ============================================================ */
.ed-tape{
  position:relative;
  z-index:18;
  width:100vw;
  height:max(150px,18vw);
  margin:calc(max(150px,18vw) * -.62) 0 0 calc(50% - 50vw);
  pointer-events:none;
}
.ed-tape-svg{display:block;width:100%;height:100%;overflow:hidden}
.ed-tape-paper{fill:var(--v29-paper)}
.ed-tape-line{fill:none;stroke:var(--v29-red);stroke-width:92}
.ed-tape-text{
  fill:var(--v29-paper);
  font-family:var(--font-display);
  font-size:60px;
  font-weight:700;
  letter-spacing:.5px;
  text-transform:uppercase;
  white-space:pre;
}
.ed-tape + .v29-choice{padding-top:3.4rem!important}

@media(max-width:767px){
  .ed-tape + .v29-choice{padding-top:2.6rem!important}
}

/* ============================================================
   V47 — booking funnel: retro premium service desk + checkout.
   Paper dominant, ink structure, coral only for action/selection.
   ~20% of homepage motion: selection, step reveal, price, drawer.
   ============================================================ */
.bk-page{
  --bk-paper:#f2ecdf;
  --bk-card:#f8f3e8;
  --bk-field:#fbf8f1;
  --bk-ink:#0b0a09;
  --bk-coral:#d56865;
  --bk-oxblood:#590d07;
  --bk-gray:rgba(11,10,9,.48);
  --bk-line:rgba(11,10,9,.2);
  --bk-gutter:clamp(16px,4vw,48px);
  background:var(--bk-paper);
  color:var(--bk-ink);
  min-height:100svh;
}
:where(.bk-page) button{font:inherit;color:inherit}

/* ---- header ---- */
.bk-top{position:sticky;top:0;z-index:45;background:var(--bk-paper);border-bottom:1.5px solid var(--bk-ink)}
.bk-top-row{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:1rem;padding:10px var(--bk-gutter)}
.bk-top-logo{display:inline-flex;width:46px;height:46px}
.bk-top-logo img{width:100%;height:100%;object-fit:contain}
.bk-top-title{margin:0;font-family:var(--font-display);font-size:.8rem;font-weight:800;letter-spacing:.2em;text-transform:uppercase}
.bk-top-help{justify-self:end;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--bk-ink);text-decoration:none;border-bottom:1.5px solid var(--bk-ink);padding-bottom:2px}
.bk-top-help:hover{color:var(--bk-coral);border-color:var(--bk-coral)}
.bk-progress{display:flex;gap:10px;margin:0;padding:0 var(--bk-gutter) 12px;list-style:none}
.bk-progress li{flex:1;padding-top:8px;border-top:3px solid rgba(11,10,9,.16);font-family:var(--font-display);font-size:.7rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:rgba(11,10,9,.38);transition:color .25s ease,border-color .25s ease}
.bk-progress li b{margin-right:.35rem}
.bk-progress li.is-done{border-color:var(--bk-ink);color:var(--bk-ink)}
.bk-progress li.is-current{border-color:var(--bk-coral);color:var(--bk-coral)}
.bk-progress-mobile{display:none}
@media(max-width:767px){
  .bk-top-row{grid-template-columns:auto 1fr auto;padding-block:8px}
  .bk-top-logo{width:38px;height:38px}
  .bk-top-title{text-align:center;font-size:.7rem;letter-spacing:.16em}
  .bk-top-help-long{display:none}
  .bk-progress{display:none}
  .bk-progress-mobile{display:block;padding:0 var(--bk-gutter) 10px}
  .bk-progress-mobile p{margin:0 0 6px;font-size:.82rem;font-weight:700}
  .bk-progress-mobile span{display:block;height:3px;background:rgba(11,10,9,.14)}
  .bk-progress-mobile i{display:block;height:100%;background:var(--bk-coral);transition:width .35s var(--ease-out,ease)}
}

/* ---- intro ---- */
.bk-intro,.bk-layout{max-width:1280px;margin:0 auto;padding-inline:var(--bk-gutter)}
.bk-intro{display:grid;grid-template-columns:1fr 250px;gap:2rem;align-items:end;padding-top:clamp(1.8rem,4vw,3.4rem);padding-bottom:clamp(1.2rem,2.4vw,2rem)}
.bk-intro-title{margin:0;font-family:var(--font-display);font-size:clamp(3rem,7.4vw,6.4rem);font-weight:900;line-height:.84;letter-spacing:-.045em;text-transform:uppercase}
.bk-intro-sub{margin:.7rem 0 0;font-size:clamp(1.1rem,1.8vw,1.35rem);font-weight:600}
.bk-intro-facts{margin:.9rem 0 0;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}
.bk-intro-facts i{font-style:normal;color:var(--bk-coral);margin:0 .5rem}
.bk-intro-signin,.bk-intro-quote{margin:1rem 0 0;font-size:.95rem;color:rgba(11,10,9,.72)}
.bk-intro-signin a{color:var(--bk-ink);font-weight:700;text-decoration:underline;text-underline-offset:3px}
.bk-intro-quote{display:flex;align-items:center;gap:.6rem;color:var(--bk-ink);font-weight:600}
.bk-intro-shot{position:relative;height:190px;border:1.5px solid var(--bk-ink);background:var(--bk-card);overflow:hidden;transform:rotate(1.4deg);box-shadow:6px 6px 0 rgba(11,10,9,.12)}
@media(max-width:899px){.bk-intro{grid-template-columns:1fr}.bk-intro-shot{display:none}}

/* ---- layout ---- */
.bk-layout{display:grid;grid-template-columns:minmax(0,7fr) minmax(280px,3fr);gap:clamp(28px,4vw,64px);padding-bottom:7rem;align-items:start}
.bk-flow{min-width:0;border-bottom:1.5px solid var(--bk-ink)}
.bk-aside{align-self:stretch}
@media(max-width:999px){.bk-layout{grid-template-columns:1fr;padding-bottom:9rem}.bk-aside{display:none}}

/* ---- steps ---- */
.bk-step{border-top:1.5px solid var(--bk-ink);scroll-margin-top:118px}
.bk-step.is-active{padding:2.2rem 0 3rem}
.bk-step-row{display:grid;grid-template-columns:2.2rem auto minmax(0,1fr) auto;align-items:baseline;gap:1rem;width:100%;padding:1.05rem 0;background:none;border:0;text-align:left}
.bk-step-row b{font-family:var(--font-display);font-weight:800;font-size:.8rem;color:rgba(11,10,9,.42)}
.bk-step-row-label{font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}
.bk-step-row-value{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:rgba(11,10,9,.7)}
.bk-step-row-edit{font-size:.82rem;font-weight:700;text-decoration:underline;text-underline-offset:3px}
.bk-step-row:hover .bk-step-row-edit{color:var(--bk-coral)}
.bk-step-body{animation:bk-in .34s var(--ease-out,ease) both}
.bk-step-num{margin:0;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:var(--bk-coral)}
.bk-q{margin:.45rem 0 1.8rem;font-family:var(--font-display);font-size:clamp(2.5rem,5.3vw,4.5rem);font-weight:900;line-height:.88;letter-spacing:-.04em;text-transform:uppercase}
.bk-q-sm{margin:0 0 1rem;font-size:clamp(1.9rem,3.6vw,2.8rem)}
.bk-label{display:block;font-family:var(--font-display);font-size:.66rem;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:var(--bk-gray)}
.bk-note{margin:.8rem 0;font-size:.95rem;color:rgba(11,10,9,.66)}
.bk-note a{color:var(--bk-ink);font-weight:700}
.bk-error{margin:1.2rem 0 0;padding:.85rem 1rem;border:1.5px solid var(--bk-coral);border-radius:4px;background:#fff3f0;color:#8a2a26;font-weight:600}
.bk-link{display:inline-block;margin-top:1rem;padding:0;background:none;border:0;font-weight:700;font-size:.95rem;text-decoration:underline;text-underline-offset:4px;text-align:left}
.bk-link:hover{color:var(--bk-coral)}
.bk-reveal{animation:bk-in .3s var(--ease-out,ease) both}
.bk-dot{display:inline-block;flex:0 0 auto;width:9px;height:9px;border-radius:50%;background:var(--bk-coral);box-shadow:0 0 0 4px rgba(213,104,101,.18)}

/* ---- buttons ---- */
.bk-btn{display:inline-flex;align-items:center;justify-content:center;min-height:54px;padding:0 1.4rem;border:1.5px solid var(--bk-ink);border-radius:4px;font-family:var(--font-display);font-size:.84rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;text-decoration:none;transition:background-color .18s ease,color .18s ease,transform .18s ease}
.bk-btn:active:not(:disabled){transform:scale(.98)}
.bk-btn:disabled{opacity:.42;cursor:not-allowed}
.bk-page .bk-btn-ink{background:var(--bk-ink);color:var(--bk-paper)}
.bk-btn-ink:hover:not(:disabled){background:#2b2521}
.bk-page .bk-btn-coral{background:var(--bk-coral);border-color:var(--bk-coral);color:#fff}
.bk-btn-coral:hover:not(:disabled){background:#c4524f;border-color:#c4524f}
.bk-page .bk-btn-line{background:transparent;color:var(--bk-ink)}
.bk-btn-line:hover{background:var(--bk-ink);color:var(--bk-paper)}

/* ---- fields ---- */
.bk-field{display:grid;gap:.4rem;min-width:0}
.bk-field>span{font-family:var(--font-display);font-size:.7rem;font-weight:800;letter-spacing:.15em;text-transform:uppercase}
.bk-field em{font-style:normal;font-weight:600;letter-spacing:.04em;text-transform:none;color:var(--bk-gray)}
.bk-field-wide{grid-column:1/-1}
.bk-input{width:100%;min-height:52px;padding:.75rem .9rem;border:1.5px solid var(--bk-ink);border-radius:4px;background:var(--bk-field);color:var(--bk-ink);font-size:1.05rem;transition:border-color .15s ease,box-shadow .15s ease}
.bk-input::placeholder{color:rgba(11,10,9,.3)}
.bk-input:focus{outline:none;border-color:var(--bk-coral);box-shadow:0 0 0 3px rgba(213,104,101,.2)}
.bk-input-xl{min-height:60px;font-size:1.25rem;font-weight:600}
.bk-input.is-bad{border-color:var(--bk-coral);background:#fff4f1}

/* ---- packages ---- */
.bk-pkgs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
@media(max-width:1179px){.bk-pkgs{grid-template-columns:1fr}}
.bk-pkg{position:relative;display:flex;flex-direction:column;gap:.55rem;padding:1.35rem 1.25rem 1.25rem;text-align:left;background:var(--bk-card);border:1.5px solid var(--bk-line);border-radius:6px;transition:transform .24s var(--ease-out,ease),border-color .2s ease,box-shadow .24s ease}
.bk-pkg:hover{border-color:var(--bk-ink)}
.bk-pkg.is-on{border:2px solid var(--bk-ink);transform:scale(1.015);box-shadow:6px 6px 0 var(--bk-ink)}
.bk-pkg-tab{position:absolute;top:-2px;right:16px;padding:5px 9px 4px;border-radius:0 0 4px 4px;background:var(--bk-coral);color:#fff;font-family:var(--font-display);font-size:.62rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;animation:bk-tab .3s var(--ease-out,ease) both}
.bk-pkg-top{display:flex;align-items:center;gap:.6rem}
.bk-pkg-no{font-family:var(--font-display);font-size:.78rem;font-weight:800;color:rgba(11,10,9,.42)}
.bk-pkg-badge{padding:3px 7px;background:var(--bk-oxblood);color:var(--bk-paper);font-family:var(--font-display);font-size:.6rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase}
.bk-pkg-name{overflow-wrap:anywhere;font-family:var(--font-display);font-size:clamp(1.55rem,1.9vw,2.2rem);font-weight:900;line-height:.9;letter-spacing:-.03em;text-transform:uppercase}
.bk-pkg-points{display:grid;margin:.4rem 0}
.bk-pkg-points span{padding:.42rem 0;border-top:1px solid var(--bk-line);font-size:.96rem}
.bk-pkg-price{font-family:var(--font-display);font-size:1.45rem;font-weight:800}
.bk-pkg-price small{font-size:.78rem;font-weight:600;color:var(--bk-gray)}
.bk-pkg-cta{margin-top:auto;padding:.85rem;border:1.5px solid var(--bk-ink);border-radius:4px;text-align:center;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase;transition:background-color .18s ease,color .18s ease}
.bk-pkg:hover .bk-pkg-cta,.bk-pkg.is-on .bk-pkg-cta{background:var(--bk-ink);color:var(--bk-paper)}
@media(max-width:1179px){
  .bk-pkg-name{font-size:clamp(1.9rem,6vw,2.4rem)}
  .bk-pkg{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:1.4rem}
  .bk-pkg>*{grid-column:1}
  .bk-pkg-price{grid-column:2;grid-row:1 / span 3;align-self:start;text-align:right}
  .bk-pkg-cta{grid-column:1 / -1}
}
@media(max-width:560px){.bk-pkg-points span:nth-child(4){display:none}}

/* ---- vehicle ---- */
.bk-mm{display:grid;grid-template-columns:1fr 1fr 130px;gap:12px}
@media(max-width:640px){.bk-mm{grid-template-columns:1fr 1fr}.bk-field-year{grid-column:1/-1}}
.bk-sil{display:block;width:120px;height:auto;fill:var(--bk-ink)}
.bk-sil .bk-sil-hub{fill:var(--bk-paper)}
.bk-sil line{stroke:var(--bk-ink);stroke-width:1}
.bk-got{display:flex;align-items:center;gap:1.4rem;margin-top:1.2rem;padding:1.1rem 1.3rem;border:1.5px solid var(--bk-ink);border-radius:6px;background:var(--bk-card);animation:bk-in .3s var(--ease-out,ease) both}
.bk-got p{margin:0;font-family:var(--font-display);font-size:.68rem;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:var(--bk-coral)}
.bk-got strong{display:block;font-family:var(--font-display);font-size:clamp(1.6rem,3vw,2.2rem);font-weight:900;line-height:1;letter-spacing:-.02em;text-transform:uppercase}
.bk-got button{margin-top:.5rem;padding:0;background:none;border:0;font-size:.88rem;font-weight:600;color:rgba(11,10,9,.66);text-decoration:underline;text-underline-offset:3px;text-align:left}
.bk-got button:hover{color:var(--bk-ink)}
@media(max-width:480px){.bk-got{flex-direction:column;align-items:flex-start;gap:.8rem}}
.bk-sizes,.bk-saved{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:1.1rem}
.bk-saved{grid-template-columns:repeat(2,minmax(0,1fr));margin:0 0 1.2rem}
@media(max-width:640px){.bk-sizes{grid-template-columns:repeat(2,minmax(0,1fr))}.bk-saved{grid-template-columns:1fr}}
.bk-size,.bk-saved-opt{display:flex;flex-direction:column;align-items:flex-start;gap:.2rem;min-height:56px;padding:.9rem 1rem;text-align:left;background:var(--bk-card);border:1.5px solid var(--bk-line);border-radius:6px;transition:border-color .18s ease,box-shadow .18s ease}
.bk-size .bk-sil{width:100%;max-width:140px;margin-bottom:.5rem}
.bk-saved-opt .bk-sil{width:84px;margin-bottom:.35rem}
.bk-size strong,.bk-saved-opt strong{font-family:var(--font-display);font-size:1rem;font-weight:800;text-transform:uppercase;letter-spacing:.02em}
.bk-size span,.bk-saved-opt span{font-size:.84rem;color:var(--bk-gray)}
.bk-size:hover,.bk-saved-opt:hover:not(:disabled){border-color:var(--bk-ink)}
.bk-size.is-on,.bk-saved-opt.is-on{border:2px solid var(--bk-ink);box-shadow:inset 0 -4px 0 var(--bk-coral)}
.bk-saved-opt:disabled{opacity:.4;cursor:not-allowed}
.bk-vehicle+.bk-vehicle{margin-top:2rem;padding-top:1.6rem;border-top:1.5px dashed var(--bk-line)}
.bk-vehicle-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:.9rem}
.bk-vehicle-head p{margin:0;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:var(--bk-coral)}
.bk-vehicle-head button{padding:0;background:none;border:0;font-size:.85rem;font-weight:700;text-decoration:underline}
.bk-chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:1.1rem}
.bk-chip{min-height:44px;padding:0 1rem;border:1.5px solid var(--bk-ink);border-radius:999px;background:transparent;font-family:var(--font-display);font-size:.74rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
.bk-page .bk-chip.is-on{background:var(--bk-ink);color:var(--bk-paper)}
.bk-add{margin-top:1.8rem}

/* ---- add-ons ---- */
.bk-addons{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px;margin-top:.4rem}
.bk-addon{display:grid;align-content:start;gap:.3rem;padding:1.05rem 1.05rem 1rem;text-align:left;background:var(--bk-card);border:1.5px solid var(--bk-line);border-radius:6px;transition:border-color .18s ease,transform .2s var(--ease-out,ease)}
.bk-addon:hover{border-color:var(--bk-ink)}
.bk-addon strong{font-family:var(--font-display);font-size:1.02rem;font-weight:800;line-height:1.1;text-transform:uppercase}
.bk-addon span{font-size:.88rem;color:rgba(11,10,9,.62)}
.bk-addon em{margin-top:.2rem;font-style:normal;font-family:var(--font-display);font-size:1.15rem;font-weight:800}
.bk-addon b{justify-self:start;margin-top:.55rem;padding:.4rem .75rem;border:1.5px solid var(--bk-ink);border-radius:3px;font-family:var(--font-display);font-size:.66rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;transition:background-color .18s ease,color .18s ease,border-color .18s ease}
.bk-addon.is-on{border:2px solid var(--bk-ink)}
.bk-addon.is-on b{background:var(--bk-coral);border-color:var(--bk-coral);color:#fff}
.bk-extras+.bk-extras{margin-top:2.2rem;padding-top:1.6rem;border-top:1.5px dashed var(--bk-line)}
.bk-extras-for{margin:0 0 .5rem;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--bk-coral)}
.bk-paint{margin-top:1.8rem}

/* ---- address + time ---- */
.bk-address{display:grid;grid-template-columns:1fr 1.4fr .55fr .75fr;gap:12px}
@media(max-width:640px){.bk-address{grid-template-columns:1fr 1fr}}
.bk-yep{display:flex;align-items:center;gap:.7rem;margin:1.3rem 0 0;font-family:var(--font-display);font-size:1.1rem;font-weight:800;text-transform:uppercase;letter-spacing:.01em}
.bk-yep b{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--bk-coral);color:#fff;font-size:.85rem}
.bk-time{margin-top:2.4rem;padding-top:2rem;border-top:1px solid var(--bk-line);transition:opacity .3s ease}
.bk-time.is-waiting{opacity:.55}
.bk-school{display:flex;gap:.9rem;align-items:flex-start;margin:0 0 1.2rem;padding:1rem 1.15rem;border:1px solid var(--bk-line);border-radius:6px;background:var(--bk-card)}
.bk-school .bk-dot{margin-top:.45rem}
.bk-school strong{font-family:var(--font-display);font-size:1rem;font-weight:900;letter-spacing:.02em;text-transform:uppercase}
.bk-school p{margin:.2rem 0 0;font-size:.94rem;color:rgba(11,10,9,.7)}
.bk-rail{position:relative;display:flex;gap:8px;margin:0 calc(var(--bk-gutter) * -1) 0 0;padding:.2rem var(--bk-gutter) .9rem 0;overflow-x:auto;scroll-snap-type:x proximity;scrollbar-width:thin;-webkit-overflow-scrolling:touch}
@media(min-width:1000px){.bk-rail{margin-right:0;padding-right:0}}
.bk-day{display:grid;justify-items:center;gap:.15rem;flex:0 0 84px;padding:.75rem .3rem .7rem;border:1.5px solid var(--bk-ink);border-radius:6px;background:var(--bk-field);scroll-snap-align:start;transition:background-color .18s ease,color .18s ease,border-color .18s ease}
.bk-day span{font-family:var(--font-display);font-size:.68rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}
.bk-day strong{font-family:var(--font-display);font-size:2rem;font-weight:900;line-height:1}
.bk-day em{font-style:normal;font-size:.62rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;white-space:nowrap}
.bk-day:hover:not(:disabled){background:var(--bk-ink);color:var(--bk-paper)}
.bk-page .bk-day.is-on{background:var(--bk-coral);border-color:var(--bk-coral);color:#fff}
.bk-day:disabled{border-color:var(--bk-line);background:transparent;color:rgba(11,10,9,.32);cursor:not-allowed}
.bk-slots-day{margin:1.4rem 0 .8rem;font-family:var(--font-display);font-size:1.45rem;font-weight:900;letter-spacing:-.01em;text-transform:uppercase}
.bk-pills{display:grid;grid-template-columns:repeat(auto-fill,minmax(128px,1fr));gap:10px}
.bk-pill{min-height:58px;border:1.5px solid var(--bk-ink);border-radius:6px;background:var(--bk-field);font-family:var(--font-display);font-size:1.15rem;font-weight:800;transition:background-color .16s ease,color .16s ease,border-color .16s ease}
.bk-pill:hover{background:var(--bk-ink);color:var(--bk-paper)}
.bk-page .bk-pill.is-on{background:var(--bk-coral);border-color:var(--bk-coral);color:#fff}
.bk-tz{margin:.9rem 0 0;font-family:var(--font-display);font-size:.66rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--bk-gray)}
.bk-loading{display:flex;gap:8px;margin-top:.6rem}
.bk-loading span{flex:0 0 84px;height:92px;border-radius:6px;background:rgba(11,10,9,.07);animation:bk-pulse 1.1s ease-in-out infinite alternate}
.bk-loading span:nth-child(2){animation-delay:.15s}.bk-loading span:nth-child(3){animation-delay:.3s}.bk-loading span:nth-child(4){animation-delay:.45s}

/* ---- info ---- */
.bk-info{display:grid;grid-template-columns:1fr 1fr;gap:16px 14px}
@media(max-width:640px){.bk-info{grid-template-columns:1fr}}
.bk-notes,.bk-source{margin-top:.6rem}
.bk-info .bk-note{align-self:end;margin:0 0 .9rem}

/* ---- review ---- */
.bk-receipt{padding:1.4rem 1.5rem;border:1.5px solid var(--bk-ink);border-radius:6px;background:var(--bk-field);box-shadow:6px 6px 0 rgba(11,10,9,.1)}
.bk-receipt-block{padding:.9rem 0;border-bottom:1.5px dashed var(--bk-line)}
.bk-receipt-block:first-child{padding-top:0}
.bk-receipt-block strong{display:block;font-family:var(--font-display);font-size:1.35rem;font-weight:900;line-height:1.05;text-transform:uppercase}
.bk-receipt-block p{margin:.15rem 0 0}
.bk-receipt-block .bk-label{margin-top:.3rem}
.bk-receipt-lines{padding-top:1rem}
.bk-receipt-lines p{display:flex;justify-content:space-between;gap:1rem;margin:.3rem 0;font-weight:600}
.bk-receipt-lines p.is-sub{font-weight:500;font-size:.94rem;color:rgba(11,10,9,.66)}
.bk-receipt-lines .bk-receipt-total{margin-top:.8rem;padding-top:.7rem;border-top:2px solid var(--bk-ink);font-family:var(--font-display);font-size:1.5rem;font-weight:900;text-transform:uppercase}
.bk-receipt-lines small,.bk-gift small{display:block;margin-top:.3rem;font-size:.84rem;color:var(--bk-gray)}
.bk-gift{margin-top:1.3rem;padding-top:1.2rem;border-top:1px solid var(--bk-line)}
.bk-gift-entry{display:flex;gap:8px;margin-top:.5rem}
.bk-gift-entry button,.bk-gift-on button{flex:0 0 auto;padding:0 1.1rem;border:1.5px solid var(--bk-ink);border-radius:4px;background:var(--bk-ink);color:var(--bk-paper);font-family:var(--font-display);font-size:.74rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.bk-gift-entry button:disabled{opacity:.4}
.bk-gift-on{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-top:.5rem;padding:.7rem .9rem;border:1.5px solid var(--bk-ink);border-radius:4px;font-weight:700}
.bk-gift-on button{min-height:40px;background:transparent;color:var(--bk-ink)}
.bk-next{margin:2.2rem 0 1.6rem}
.bk-next h3{margin:0 0 .8rem;font-family:var(--font-display);font-size:.74rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}
.bk-next ol{display:grid;gap:.55rem;margin:0;padding:0;list-style:none}
.bk-next li{font-family:var(--font-display);font-size:clamp(1.05rem,1.8vw,1.3rem);font-weight:700}
.bk-next li b{margin-right:.8rem;color:var(--bk-coral)}
.bk-confirm{width:100%;min-height:76px;font-size:clamp(1.05rem,2vw,1.35rem);letter-spacing:.14em}

/* ---- summary (desktop aside + mobile drawer) ---- */
.bk-aside-inner{position:sticky;top:126px;margin-top:2.2rem;padding:1.35rem 1.35rem 1.4rem;border:1.5px solid var(--bk-ink);border-radius:6px;background:var(--bk-field)}
.bk-sum-title{margin:0;padding-bottom:.6rem;border-bottom:2px solid var(--bk-ink);font-family:var(--font-display);font-size:1.15rem;font-weight:900;letter-spacing:.06em;text-transform:uppercase}
.bk-sum-block{padding:.7rem 0;border-bottom:1px dashed var(--bk-line)}
.bk-sum-block strong{display:block;font-family:var(--font-display);font-size:1.02rem;font-weight:800}
.bk-sum-block span{display:block;font-size:.92rem;color:rgba(11,10,9,.62)}
.bk-sum-money{padding-top:.6rem}
.bk-sum-money p{display:flex;justify-content:space-between;gap:1rem;margin:.3rem 0;font-family:var(--font-display);font-size:.78rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.bk-sum-money .bk-sum-total{margin-top:.6rem;padding-top:.6rem;border-top:2px solid var(--bk-ink);font-size:1.3rem;letter-spacing:.02em;animation:bk-pop .38s var(--ease-out,ease)}
.bk-sum-money .bk-sum-gift{color:var(--bk-coral);font-size:.7rem}
.bk-sum-money small{display:block;margin-top:.5rem;font-size:.82rem;color:var(--bk-gray)}
.bk-aside-go{width:100%;margin-top:1.1rem}

.bk-bar,.bk-drawer{display:none}
@media(max-width:999px){
  .bk-bar{position:fixed;inset:auto 0 0 0;z-index:50;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px;padding:10px 16px calc(10px + env(safe-area-inset-bottom));background:var(--bk-paper);border-top:1.5px solid var(--bk-ink)}
  .bk-bar-sum{min-width:0;padding:4px 0;background:none;border:0;text-align:left}
  .bk-bar-sum strong{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-family:var(--font-display);font-size:1rem;font-weight:800;animation:bk-pop .38s var(--ease-out,ease)}
  .bk-bar-sum span{font-size:.72rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--bk-gray)}
  .bk-bar-go{min-height:52px;padding:0 1.1rem;font-size:.78rem}
  .bk-drawer{position:fixed;inset:0;z-index:49;display:block;pointer-events:none}
  .bk-drawer-scrim{position:absolute;inset:0;border:0;background:rgba(11,10,9,.42);opacity:0;transition:opacity .3s ease}
  .bk-drawer-sheet{position:absolute;inset:auto 0 0 0;max-height:78svh;overflow:auto;padding:1.4rem 1.25rem calc(92px + env(safe-area-inset-bottom));background:var(--bk-paper);border-top:2px solid var(--bk-ink);border-radius:14px 14px 0 0;transform:translateY(100%);transition:transform .34s var(--ease-out,ease)}
  .bk-drawer.is-open{pointer-events:auto}
  .bk-drawer.is-open .bk-drawer-scrim{opacity:1}
  .bk-drawer.is-open .bk-drawer-sheet{transform:none}
  .bk-step{scroll-margin-top:92px}
}

/* ---- confirmation ---- */
.bk-done{max-width:780px;margin:0 auto;padding:clamp(2.4rem,7vw,5rem) var(--bk-gutter) 6rem}
.bk-kicker{display:flex;align-items:center;gap:.6rem;margin:0;font-family:var(--font-display);font-size:.72rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}
.bk-done-title{margin:1rem 0 0;font-family:var(--font-display);font-size:clamp(3.6rem,11vw,8rem);font-weight:900;line-height:.82;letter-spacing:-.05em;text-transform:uppercase;animation:bk-stamp .6s var(--ease-out,ease) both}
.bk-done-when{margin:1.4rem 0 0;font-family:var(--font-display);font-size:clamp(1.3rem,3vw,1.8rem);font-weight:900;color:var(--bk-coral);text-transform:uppercase}
.bk-done-lines{margin-top:1.4rem;padding:1.2rem 1.3rem;border:1.5px solid var(--bk-ink);border-radius:6px;background:var(--bk-field)}
.bk-done-lines p{display:flex;justify-content:space-between;gap:1rem;margin:.25rem 0;font-weight:600}
.bk-done-lines .bk-done-total{margin-top:.6rem;padding-top:.6rem;border-top:2px solid var(--bk-ink);font-family:var(--font-display);font-size:1.3rem;font-weight:900;text-transform:uppercase}
.bk-done-lines small{display:block;margin-top:.5rem;color:var(--bk-gray)}
.bk-done-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:1.4rem}
.bk-done-note{margin:1.2rem 0 0;color:rgba(11,10,9,.72)}
.bk-done-prep{margin-top:2.6rem;padding-top:1.6rem;border-top:1.5px solid var(--bk-ink)}
.bk-done-prep h2{margin:0;font-family:var(--font-display);font-size:.8rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}
.bk-done-prep ul{margin:.9rem 0 0;padding:0;list-style:none}
.bk-done-prep li{padding:.55rem 0;border-bottom:1px dashed var(--bk-line);font-size:1.08rem;font-weight:600}
.bk-done-line{margin:1.6rem 0 0;font-family:var(--font-display);font-size:clamp(1.6rem,4vw,2.4rem);font-weight:900;letter-spacing:-.02em;text-transform:uppercase}
.bk-done-small{margin-top:2rem;font-size:.92rem;color:rgba(11,10,9,.66)}
.bk-done-small a{color:var(--bk-ink);font-weight:700}

@keyframes bk-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes bk-tab{from{transform:translateY(-100%)}to{transform:none}}
@keyframes bk-pop{0%{transform:scale(1)}40%{transform:scale(1.04)}100%{transform:scale(1)}}
@keyframes bk-stamp{from{opacity:0;transform:scale(1.08) rotate(-2deg)}to{opacity:1;transform:none}}
@keyframes bk-pulse{from{opacity:.45}to{opacity:1}}

/* ============================================================
   V48 — BOOKING PRECISION PASS
   Keeps the V47 booking desk, removes friction and hardens edge cases.
   ============================================================ */

.bk-skip{
  position:fixed;
  left:16px;
  top:10px;
  z-index:70;
  padding:.7rem .9rem;
  background:var(--bk-ink);
  color:var(--bk-paper);
  font-family:var(--font-display);
  font-size:.75rem;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  text-decoration:none;
  transform:translateY(-160%);
  transition:transform .18s ease;
}
.bk-skip:focus{transform:none}

/* Booking intro should feel like the top of a checkout, not another hero. */
.bk-intro{
  display:block;
  padding-top:clamp(1.65rem,3.6vw,3rem);
  padding-bottom:clamp(1.15rem,2.2vw,1.8rem);
}
.bk-intro>div:first-child{max-width:860px}
.bk-intro-title{font-size:clamp(3rem,6.7vw,5.9rem)}
.bk-intro-shot{display:none!important}

/* Selected cards should feel locked-in, not animated forward at the customer. */
.bk-pkg.is-on{
  transform:none!important;
  box-shadow:4px 4px 0 var(--bk-ink)!important;
}

/* contenteditable notes hardening */
.autofill-safe-notes{
  outline:none;
}
.autofill-safe-notes:focus,
.autofill-safe-notes:focus-visible{
  border-color:var(--color-ink);
  box-shadow:0 0 0 3px rgb(184 54 61 / .18);
}
.autofill-safe-notes-meta{
  display:flex;
  justify-content:flex-end;
  margin-top:.35rem;
  color:var(--color-muted);
  font-family:var(--font-display);
  font-size:.72rem;
  font-weight:600;
  letter-spacing:.04em;
}

@media(prefers-reduced-motion:reduce){
  .bk-skip{transition:none}
}


/* ============================================================
   V49 — booking vehicle search parity with quote flow
   ============================================================ */
.bk-vehicle-search{
  max-width:42rem;
  margin-top:.4rem;
}
.bk-vehicle-search .quote-rec-search{
  min-height:64px;
  border:1.5px solid var(--bk-ink);
  border-radius:6px;
  background:var(--bk-field);
  font-family:var(--font-body);
  font-size:1.12rem;
  font-weight:600;
}
.bk-vehicle-search .quote-rec-search:focus{
  border-color:var(--bk-coral);
  box-shadow:0 0 0 3px rgba(213,104,101,.2);
}
.bk-vehicle-search .quote-rec-search-results{
  border:1.5px solid var(--bk-ink);
  border-radius:6px;
  box-shadow:0 18px 44px rgba(11,10,9,.16);
}
.bk-vehicle-search .quote-rec-search-results button{
  min-height:54px;
  padding:.9rem 1rem;
  background:#fff;
}
.bk-vehicle-search .quote-rec-search-results button:hover,
.bk-vehicle-search .quote-rec-search-results button:focus-visible{
  background:var(--bk-paper2,#ebe6dd);
}
.bk-vehicle-search .quote-rec-search-results button span{
  font-size:1rem;
}
.bk-vehicle-search .quote-rec-search-results button small{
  font-family:var(--font-display);
  font-size:.68rem;
  font-weight:800;
  letter-spacing:.1em;
  text-transform:uppercase;
}
.bk-vehicle-selected{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:center;
  gap:.85rem 1rem;
  max-width:42rem;
  margin-top:.4rem;
  padding:1rem 1.1rem;
  border:1.5px solid var(--bk-ink);
  border-radius:6px;
  background:var(--bk-field);
}
.bk-vehicle-selected>div strong{
  font-size:1.2rem;
  font-weight:900;
}
.bk-vehicle-selected>div span{
  font-family:var(--font-display);
  font-size:.72rem;
  font-weight:800;
  letter-spacing:.1em;
  text-transform:uppercase;
}
.bk-vehicle-selected>button{
  justify-self:end;
  padding:0;
  border:0;
  background:none;
  color:var(--bk-coral)!important;
  font-family:var(--font-display);
  font-size:.72rem;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.bk-year-inline{
  grid-column:1 / -1;
  display:grid;
  grid-template-columns:auto minmax(120px,160px);
  align-items:center;
  justify-content:start;
  gap:.8rem;
  padding-top:.8rem;
  border-top:1px dashed var(--bk-line);
}
.bk-year-inline>span{
  font-family:var(--font-display);
  font-size:.7rem;
  font-weight:800;
  letter-spacing:.12em;
  text-transform:uppercase;
}
.bk-year-inline em{
  font-family:var(--font-body);
  font-style:normal;
  font-weight:400;
  letter-spacing:0;
  text-transform:none;
  color:var(--bk-gray);
}
.bk-year-inline .bk-input{min-height:44px}
.bk-type-fallback{margin-top:.8rem}
.bk-size-fallback{margin-top:1rem;max-width:52rem}
.bk-size-fallback>.bk-label{margin-bottom:.65rem}
.bk-size-fallback-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:9px;
}
.bk-size-text{
  display:flex;
  min-height:72px;
  flex-direction:column;
  align-items:flex-start;
  justify-content:center;
  gap:.15rem;
  padding:.85rem .95rem;
  border:1.5px solid var(--bk-line);
  border-radius:6px;
  background:var(--bk-card);
  text-align:left;
}
.bk-size-text strong{
  font-family:var(--font-display);
  font-size:.92rem;
  font-weight:900;
  letter-spacing:.02em;
  text-transform:uppercase;
}
.bk-size-text span{font-size:.82rem;color:var(--bk-gray)}
.bk-size-text:hover{border-color:var(--bk-ink)}
.bk-size-text.is-on{
  border:2px solid var(--bk-ink);
  box-shadow:inset 0 -4px 0 var(--bk-coral);
}
/* Old silhouette/card picker is intentionally retired in V49. */
.bk-sil{display:none!important}
@media(max-width:640px){
  .bk-vehicle-search,.bk-vehicle-selected{max-width:none}
  .bk-size-fallback-grid{grid-template-columns:1fr 1fr}
  .bk-vehicle-selected{grid-template-columns:1fr auto}
  .bk-year-inline{grid-template-columns:1fr}
}

/* ============================================================
   V50 — booking vehicle-result overflow + full availability calendar
   ============================================================ */

/* Keep quote-style search, but let booking results participate in document flow.
   This prevents long result sets from disappearing behind the viewport/bottom UI. */
.bk-vehicle-search{
  position:relative;
  z-index:24;
}
.bk-vehicle-search .quote-rec-search-results{
  position:relative!important;
  z-index:25!important;
  top:auto!important;
  left:auto!important;
  right:auto!important;
  margin-top:.45rem;
  max-height:min(360px,46dvh);
  overflow-y:auto!important;
  overflow-x:hidden!important;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  scrollbar-width:thin;
  scrollbar-color:rgba(11,10,9,.34) transparent;
}
.bk-vehicle-search .quote-rec-search-results::-webkit-scrollbar{width:9px}
.bk-vehicle-search .quote-rec-search-results::-webkit-scrollbar-track{background:transparent}
.bk-vehicle-search .quote-rec-search-results::-webkit-scrollbar-thumb{
  background:rgba(11,10,9,.28);
  border:3px solid transparent;
  border-radius:999px;
  background-clip:padding-box;
}

/* Full month availability picker. */
.bk-calendar{
  width:min(100%,760px);
  margin-top:.45rem;
  border:1.5px solid var(--bk-ink);
  border-radius:6px;
  background:var(--bk-field);
  overflow:hidden;
}
.bk-calendar-head{
  display:grid;
  grid-template-columns:48px 1fr 48px;
  align-items:center;
  min-height:64px;
  border-bottom:1.5px solid var(--bk-ink);
}
.bk-calendar-head h4{
  margin:0;
  text-align:center;
  font-family:var(--font-display);
  font-size:clamp(1.2rem,2.2vw,1.55rem);
  font-weight:900;
  letter-spacing:-.015em;
  text-transform:uppercase;
}
.bk-calendar-head button{
  align-self:stretch;
  border:0;
  background:transparent;
  font-family:var(--font-display);
  font-size:1.15rem;
  font-weight:900;
  transition:background-color .16s ease,color .16s ease;
}
.bk-calendar-head button:first-child{border-right:1px solid var(--bk-line)}
.bk-calendar-head button:last-child{border-left:1px solid var(--bk-line)}
.bk-calendar-head button:hover:not(:disabled){background:var(--bk-ink);color:var(--bk-paper)}
.bk-calendar-head button:disabled{opacity:.2;cursor:default}
.bk-calendar-weekdays,
.bk-calendar-grid{
  display:grid;
  grid-template-columns:repeat(7,minmax(0,1fr));
}
.bk-calendar-weekdays{
  border-bottom:1px solid var(--bk-line);
  background:rgba(11,10,9,.025);
}
.bk-calendar-weekdays span{
  padding:.62rem .25rem .55rem;
  text-align:center;
  font-family:var(--font-display);
  font-size:.62rem;
  font-weight:900;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--bk-gray);
}
.bk-cal-day{
  position:relative;
  display:flex;
  min-width:0;
  min-height:86px;
  padding:.65rem .65rem .58rem;
  flex-direction:column;
  align-items:flex-start;
  justify-content:space-between;
  gap:.3rem;
  border:0;
  border-right:1px solid var(--bk-line);
  border-bottom:1px solid var(--bk-line);
  background:transparent;
  text-align:left;
  transition:background-color .16s ease,color .16s ease,box-shadow .16s ease;
}
.bk-cal-day:nth-child(7n){border-right:0}
.bk-cal-day:nth-last-child(-n+7){border-bottom:0}
.bk-cal-num{
  font-family:var(--font-display);
  font-size:1.2rem;
  font-weight:900;
  line-height:1;
}
.bk-cal-avail{
  display:inline-flex;
  align-items:center;
  gap:.35rem;
  font-family:var(--font-display);
  font-size:.58rem;
  font-weight:900;
  letter-spacing:.08em;
  line-height:1.1;
  text-transform:uppercase;
  color:var(--bk-coral);
}
.bk-cal-avail::before{
  content:"";
  width:6px;
  height:6px;
  flex:0 0 6px;
  border-radius:50%;
  background:currentColor;
}
.bk-cal-today{
  position:absolute;
  top:.66rem;
  right:.6rem;
  font-family:var(--font-display);
  font-size:.5rem;
  font-weight:900;
  letter-spacing:.1em;
  text-transform:uppercase;
  color:var(--bk-gray);
}
.bk-cal-day:not(:disabled):hover{
  background:rgba(11,10,9,.055);
  box-shadow:inset 0 -3px 0 var(--bk-ink);
}
.bk-cal-day.is-on{
  background:var(--bk-coral)!important;
  color:#fff!important;
  box-shadow:none!important;
}
.bk-cal-day.is-on .bk-cal-avail,
.bk-cal-day.is-on .bk-cal-today{color:#fff}
.bk-cal-day:disabled{
  cursor:default;
  color:rgba(11,10,9,.28);
}
.bk-cal-day:disabled .bk-cal-avail{display:none}
