.q52-page .q51-complete-row{transition:padding .2s ease,color .2s ease}
.q52-page .q51-complete-row:hover{padding-left:.5rem}

/* Condition becomes a playful mess meter rather than five identical boxes. */
.q52-page .q51-condition-grid.quote-rec-condition-grid{align-items:end;gap:12px;padding:1rem .3rem .4rem}
.q52-page .q51-condition-grid.quote-rec-condition-grid button{
  position:relative;
  transform-origin:center bottom;
  transition:transform .22s var(--ease-out,ease),border-color .18s ease,box-shadow .2s ease,background .2s ease;
}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:nth-child(1){min-height:146px;transform:rotate(-2.2deg);background:#fbf8f1}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:nth-child(2){min-height:156px;transform:rotate(1.3deg);background:#f6eee5}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:nth-child(3){min-height:168px;transform:rotate(-1deg);background:#f0e3d8}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:nth-child(4){min-height:182px;transform:rotate(1.8deg);background:#ead5ca}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:nth-child(5){min-height:196px;transform:rotate(-1.7deg);background:#dfc0b8}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:hover{transform:translateY(-8px) rotate(0);box-shadow:7px 9px 0 rgba(11,10,9,.12)}
.q52-page .q51-condition-grid.quote-rec-condition-grid button.is-selected{transform:translateY(-8px) rotate(0);box-shadow:7px 9px 0 var(--q51-ink)}
.q52-page .q51-condition-grid.quote-rec-condition-grid button::after{
  content:"";
  position:absolute;
  left:10px;
  right:10px;
  bottom:8px;
  height:3px;
  background:var(--q51-coral);
  transform:scaleX(0);
  transform-origin:left;
  transition:transform .2s ease;
}
.q52-page .q51-condition-grid.quote-rec-condition-grid button:hover::after,
.q52-page .q51-condition-grid.quote-rec-condition-grid button.is-selected::after{transform:scaleX(1)}

.q52-page .q51-concern-grid.quote-rec-concern-grid{gap:12px;padding:.35rem 0}
.q52-page .q51-concern-grid.quote-rec-concern-grid button{
