}
.q52-page .q51-concern-grid.quote-rec-concern-grid button:nth-child(3n+1){transform:rotate(-.45deg)}
.q52-page .q51-concern-grid.quote-rec-concern-grid button:nth-child(3n+2){transform:rotate(.35deg)}
.q52-page .q51-concern-grid.quote-rec-concern-grid button:hover{transform:translate(-2px,-3px) rotate(0);box-shadow:7px 8px 0 rgba(11,10,9,.12)}
.q52-page .q51-concern-grid.quote-rec-concern-grid button.is-selected{transform:translate(-2px,-3px) rotate(0);background:var(--q51-ink);color:var(--q51-paper);box-shadow:7px 8px 0 var(--q51-coral)}
.q52-page .q51-concern-grid.quote-rec-concern-grid button.is-selected small{color:rgba(243,237,223,.66)}
.q52-page .q51-build{min-height:82px;margin-top:1.8rem;border-radius:0;box-shadow:8px 8px 0 var(--q51-coral);transition:transform .18s ease,box-shadow .18s ease,background .18s ease}
.q52-page .q51-build:hover{transform:translate(-3px,-3px);box-shadow:11px 11px 0 var(--q51-coral)}

.q52-page .q51-snapshot{
  top:96px;
  transform:rotate(1.2deg);
  border-radius:0;
  box-shadow:9px 11px 0 rgba(11,10,9,.1);
}
.q52-page .q51-snapshot::before{
  content:"LIVE DIAGNOSIS";
  position:absolute;
  right:18px;
  top:-13px;
  padding:5px 9px 4px;
  background:var(--q51-coral);
  color:#fff;
  font-family:var(--font-display);
  font-size:.55rem;
  font-weight:900;
  letter-spacing:.13em;
  transform:rotate(2deg);
}
.q52-page .q51-snapshot-title{font-size:1.15rem}

/* Recommendation payoff: bolder, darker, more poster-like than booking. */
.q52-page .q51-result.quote-rec-result{padding-top:1rem}
.q52-page .q51-result .quote-rec-reveal-card{
  position:relative;
