}
.q52-page .q51-result .quote-rec-reveal-price>strong{font-size:clamp(5rem,8vw,8rem)}
.q52-page .q51-intent.quote-rec-intent-stage{margin-top:28px;border-radius:0;box-shadow:9px 10px 0 rgba(11,10,9,.08)}
.q52-page .q51-intent .quote-rec-intent-context{position:relative;overflow:hidden;background:#e8d7c6}
.q52-page .q51-intent .quote-rec-intent-context::after{
  content:"WHEN?";
  position:absolute;
  right:-.08em;
  bottom:-.18em;
  color:rgba(89,13,7,.07);
  font-family:var(--font-display);
  font-size:clamp(6rem,11vw,10rem);
