  pointer-events:none;
}
.q52-page .q51-intent .quote-rec-intent-choice{border-radius:0;transition:transform .16s ease,box-shadow .16s ease,border-color .16s ease,background .16s ease}
.q52-page .q51-intent .quote-rec-intent-choice:hover{transform:translate(-2px,-2px);box-shadow:5px 5px 0 var(--q51-ink)}

@keyframes q52PhotoIn{
  from{opacity:0;transform:translateY(26px) rotate(0deg) scale(.97)}
