/* ============================================================
   V53 — QUOTE SINGLE-SCREEN TOOL + AVAILABILITY RECOVERY
   Keep quote more expressive than booking without turning it
   into another long-form homepage.
   ============================================================ */
.q53-page{
  height:100svh;
  min-height:100svh;
  overflow:hidden;
  background:
    radial-gradient(circle at 84% 10%,rgba(213,104,101,.08),transparent 28%),
    var(--q51-paper);
}
.q53-page .q51-top{position:relative}
.q53-tool{
  display:grid;
  grid-template-rows:auto minmax(0,1fr);
  height:calc(100svh - 67px);
  max-width:1380px;
  margin:0 auto;
  padding:0 clamp(16px,4vw,48px) 18px;
  overflow:hidden;
  outline:none;
}
.q53-intro{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:1.5rem;
  min-height:104px;
  padding:16px 0 14px;
  border-bottom:1.5px solid var(--q51-ink);
}
.q53-intro>div>p{
  margin:0 0 .35rem;
  color:var(--q51-coral);
  font-family:var(--font-display);
  font-size:.62rem;
  font-weight:900;
  letter-spacing:.18em;
}
.q53-intro h1{
  margin:0;
  font-family:var(--font-display);
  font-size:clamp(2.7rem,4.6vw,4.8rem);
  font-weight:900;
  line-height:.82;
  letter-spacing:-.05em;
  text-transform:uppercase;
}
.q53-intro>span{
  padding-bottom:.3rem;
  font-family:var(--font-display);
  font-size:.62rem;
  font-weight:900;
  letter-spacing:.14em;
  text-align:right;
  white-space:nowrap;
}
.q53-intro>span::before{content:"●";margin-right:.55rem;color:var(--q51-coral)}

.q53-rec.quote-rec-shell{
  min-height:0;
  height:100%;
  grid-template-columns:minmax(0,7fr) minmax(280px,3fr);
  gap:clamp(26px,3.5vw,54px);
  padding-top:14px;
  align-items:start;
}
.q53-rec-main{
  min-width:0;
  min-height:0;
  border-bottom:0;
  overflow:visible;
}
.q53-page .q51-progress{margin-bottom:10px}
.q53-page .q51-progress span{padding-top:.45rem}
.q53-page .q53-active-step{
  min-height:0!important;
  padding:1.55rem 0 1.35rem!important;
  border-top:1.5px solid var(--q51-ink);
  overflow:visible;
}
.q53-page .q51-step-body h2{
  margin:.35rem 0 .5rem;
  font-size:clamp(2.8rem,4.9vw,4.8rem);
  line-height:.84;
}
.q53-page .q51-step-help{margin-bottom:1rem}
.q53-page .q51-search-wrap.quote-rec-search-wrap{max-width:760px;z-index:40}
.q53-page .q51-search-results.quote-rec-search-results{
  z-index:80;
  max-height:min(360px,42svh);
  overscroll-behavior:contain;
}

.q53-page .q51-condition-grid.quote-rec-condition-grid{
  grid-template-columns:repeat(5,minmax(0,1fr));
  gap:9px;
  margin-top:.2rem;
}
.q53-page .q51-condition-grid.quote-rec-condition-grid button{
  min-height:136px;
  padding:.9rem;
}
.q53-page .q51-condition-grid.quote-rec-condition-grid button strong{font-size:1.05rem}
.q53-page .q51-condition-grid.quote-rec-condition-grid button small{font-size:.72rem;line-height:1.3}

.q53-page .q51-concern-grid.quote-rec-concern-grid{
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
  margin-top:.2rem;
}
.q53-page .q51-concern-grid.quote-rec-concern-grid button{
  min-height:66px;
  padding:.72rem .9rem;
}
.q53-page .q51-build{
  min-height:58px;
  margin-top:1rem;
  box-shadow:5px 5px 0 var(--q51-coral);
}
.q53-page .q51-build:hover{transform:translate(-2px,-2px);box-shadow:7px 7px 0 var(--q51-coral)}

.q53-snapshot.q51-snapshot{
  position:relative;
  top:auto;
  margin-top:34px;
  transform:rotate(-.55deg);
  box-shadow:8px 9px 0 rgba(11,10,9,.08);
  background:var(--q51-field);
}
.q53-snapshot.q51-snapshot::before{
  content:"LIVE DIAGNOSIS";
  position:absolute;
  top:-12px;
  right:16px;
  padding:5px 9px 4px;
  background:var(--q51-coral);
  color:#fff;
  font-family:var(--font-display);
  font-size:.56rem;
  font-weight:900;
  letter-spacing:.14em;
  transform:rotate(3deg);
}
.q53-snapshot>div:not(.q51-snapshot-foot){position:relative;padding-right:58px}
.q53-snapshot>div>button{
  position:absolute;
  right:0;
  bottom:.8rem;
  padding:0;
  border:0;
  background:none;
  font-size:.72rem;
  font-weight:800;
  text-decoration:underline;
  text-underline-offset:3px;
}
.q53-snapshot>div>button:hover{color:var(--q51-coral)}

/* Recommendation views replace the diagnostic in the same viewport. */
.q53-tool>.q51-result.quote-rec-result{
  min-height:0;
  height:100%;
  max-width:none;
  margin:0;
  padding:14px 0 4px;
  overflow:auto;
  scrollbar-width:thin;
}
.q53-page .q51-result:not(.quote-rec-flow){
  display:grid;
  grid-template-columns:minmax(0,1.15fr) minmax(330px,.85fr);
  gap:14px;
  align-content:start;
}
.q53-page .q51-result:not(.quote-rec-flow)>.quote-rec-back{grid-column:1/-1;margin:0 0 2px}
.q53-page .q51-result:not(.quote-rec-flow)>.quote-rec-reveal-card{grid-column:1;margin:0}
.q53-page .q51-result:not(.quote-rec-flow)>.q51-intent{grid-column:2;margin:0}
.q53-page .q51-intent.quote-rec-intent-stage{grid-template-columns:1fr}
.q53-page .q51-intent .quote-rec-intent-context{padding:1.35rem}
.q53-page .q51-intent .quote-rec-intent-context h2{font-size:clamp(2.1rem,3vw,3.2rem)}
.q53-page .q51-intent .quote-rec-intent-options{padding:1rem}
.q53-page .quote-rec-intent-choice{min-height:60px}
.q53-page .q51-result .quote-rec-reveal-copy{padding:1.5rem}
.q53-page .q51-result .quote-rec-reveal-copy h2{font-size:clamp(3.5rem,5.8vw,6rem)}
.q53-page .q51-result .quote-rec-reveal-price{padding:1.35rem}
.q53-page .q51-result .quote-rec-reveal-price>strong{font-size:clamp(3.8rem,5.4vw,5.8rem)}

.q53-page .quote-rec-flow{
  display:grid;
  grid-template-columns:minmax(0,1.08fr) minmax(340px,.92fr);
  gap:14px;
  align-content:start;
}
.q53-page .quote-rec-flow>.quote-rec-answerbar{grid-column:1/-1;margin:0}
