.dp56-thesis{padding:clamp(5rem,8vw,8rem) 0}
.dp56-thesis-grid,.dp56-section-head{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.65fr);gap:clamp(2rem,6vw,6rem);align-items:end}
.dp56-thesis-grid h2,.dp56-section-head h2,.dp56-faq h2,.dp56-how h2{margin:.7rem 0 0;font-family:var(--font-numeral);font-size:clamp(4rem,7vw,7rem);font-weight:400;line-height:.85;letter-spacing:.005em}
.dp56-thesis-grid>p,.dp56-section-head>p{margin:0 0 .45rem;font-size:1.08rem;line-height:1.65;color:rgba(20,18,16,.68)}
.dp56-compare{display:grid;grid-template-columns:1fr 1fr;gap:1.25rem;margin-top:3.5rem}
.dp56-compare-card{padding:1.5rem 1.6rem;box-shadow:var(--dp-shadow);transform:rotate(-.35deg)}
.dp56-compare-card:nth-child(2){transform:rotate(.5deg)}
.dp56-compare-card>span{font-family:var(--font-display);font-size:.68rem;font-weight:900;letter-spacing:.16em}.dp56-compare-card ol{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin:1.2rem 0 0;padding:0;list-style:none;border-top:2px solid currentColor}.dp56-compare-card li{min-height:95px;padding:.9rem .8rem;border-right:1px dashed rgba(20,18,16,.28);font-family:var(--font-display);font-size:.86rem;font-weight:800;text-transform:uppercase}.dp56-compare-card li:last-child{border-right:0}.dp56-compare-card li b{display:block;margin-bottom:.8rem;color:#9d3c3a;font-size:.62rem;letter-spacing:.12em}

.dp56-builder{padding:clamp(5rem,8vw,8rem) 0;border-block:1px solid rgba(20,18,16,.16)}
.dp56-builder-form{margin-top:3.2rem}
.dp56-builder-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:clamp(2rem,5vw,4.5rem);align-items:start}
.dp56-control-head{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1rem}.dp56-control-head span,.dp56-subchoices legend{font-family:var(--font-display);font-size:.66rem;font-weight:900;letter-spacing:.16em;text-transform:uppercase}.dp56-control-head strong{font-family:var(--font-display);font-size:1rem;text-transform:uppercase;color:#9d3c3a}
.dp56-cadence-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.dp56-cadence-ticket{position:relative;min-height:140px;padding:1rem;text-align:left;border:1px solid rgba(20,18,16,.28);box-shadow:0 2px 3px rgba(40,30,20,.08),0 10px 22px rgba(40,30,20,.08);transform:rotate(-.4deg);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}
.dp56-cadence-ticket:nth-child(2){transform:rotate(.45deg)}.dp56-cadence-ticket:nth-child(3){transform:rotate(-.2deg)}.dp56-cadence-ticket:nth-child(4){transform:rotate(.65deg)}
.dp56-cadence-ticket:hover{transform:translateY(-3px) rotate(0);box-shadow:0 4px 5px rgba(40,30,20,.12),0 18px 30px rgba(40,30,20,.12)}
.dp56-cadence-ticket.is-selected{z-index:2;border:2px solid var(--dp-ink);transform:translateY(-5px) rotate(0);box-shadow:7px 8px 0 var(--dp-coral),0 22px 38px rgba(40,30,20,.15)}
.dp56-cadence-ticket small{display:block;font-family:var(--font-display);font-size:.6rem;font-weight:900;letter-spacing:.12em;color:#9d3c3a}.dp56-cadence-ticket b{display:block;margin-top:1.3rem;font-family:var(--font-display);font-size:1.05rem;text-transform:uppercase}.dp56-cadence-ticket span{display:block;margin-top:.25rem;font-size:.8rem;color:rgba(20,18,16,.6)}
.dp56-slider-sheet{margin-top:1.15rem;padding:1.1rem 1.25rem 1rem;border:1px solid rgba(20,18,16,.22);box-shadow:0 10px 26px rgba(40,30,20,.1)}
.dp56-slider-readout{display:flex;justify-content:space-between;align-items:baseline;gap:1rem}.dp56-slider-readout span{font-family:var(--font-display);font-size:.63rem;font-weight:900;letter-spacing:.15em}.dp56-slider-readout strong{font-family:var(--font-display);font-size:1.25rem;text-transform:uppercase}
.dp56-range{width:100%;margin:1rem 0 .4rem;accent-color:var(--dp-coral)}
.dp56-range-labels{display:flex;justify-content:space-between;font-family:var(--font-display);font-size:.57rem;font-weight:900;letter-spacing:.14em;color:rgba(20,18,16,.58)}
.dp56-cycle-card{margin-top:1.2rem;padding:1.1rem 1.2rem 1rem;color:var(--dp-cream);box-shadow:var(--dp-shadow);transform:rotate(-.25deg)}
.dp56-cycle-top{display:flex;justify-content:space-between;gap:1rem;align-items:baseline}.dp56-cycle-top span{font-family:var(--font-display);font-size:.6rem;font-weight:900;letter-spacing:.14em}.dp56-cycle-top b{font-family:var(--font-display);font-size:.75rem;letter-spacing:.1em;color:#ef8e88}
.dp56-week-strip{display:grid;grid-template-columns:repeat(13,1fr);gap:4px;margin-top:.9rem}.dp56-week{position:relative;display:grid;place-items:center;min-height:58px;border:1px solid rgba(242,236,223,.22)}.dp56-week i{position:absolute;left:4px;top:3px;font-family:var(--font-display);font-size:.45rem;font-style:normal;color:rgba(242,236,223,.45)}.dp56-week span{font-family:var(--font-display);font-size:1.4rem;font-weight:900;color:var(--dp-coral)}.dp56-week.is-visit{background:rgba(213,104,101,.12);border-color:var(--dp-coral)}
.dp56-cycle-card>p{margin:.7rem 0 0;font-size:.76rem;color:rgba(242,236,223,.64)}
.dp56-subchoices{display:grid;grid-template-columns:1fr 1fr;gap:1.1rem;margin-top:1.25rem}.dp56-subchoices fieldset{border:0;padding:0;margin:0}.dp56-subchoices legend{margin-bottom:.55rem}.dp56-choice-row{display:grid;gap:7px}.dp56-choice-row button,.dp56-vehicle-select-wrap select{width:100%;min-height:48px;padding:.65rem .8rem;border:1px solid rgba(20,18,16,.28);background:rgba(255,255,255,.24);text-align:left;font:inherit;font-size:.88rem}.dp56-choice-row button.is-selected{border:2px solid var(--dp-ink);background:var(--dp-ink);color:var(--dp-cream)}.dp56-vehicle-select-wrap select{appearance:auto}
.dp56-member-stack{position:sticky;top:7rem;display:grid;gap:1.25rem;padding-top:1.9rem}
.dp56-member-card{position:relative;min-height:330px;padding:1.35rem 1.45rem;color:#2c1816;box-shadow:0 3px 4px rgba(32,22,15,.14),0 18px 36px rgba(32,22,15,.17),0 38px 75px rgba(32,22,15,.12);transform:rotate(1.4deg)}
.dp56-member-card-top{display:flex;align-items:baseline;justify-content:space-between;padding-bottom:.6rem;border-bottom:2px solid #2c1816}.dp56-member-card-top span{font-family:var(--font-display);font-size:.67rem;font-weight:900;letter-spacing:.16em}.dp56-member-card-top b{font-family:var(--font-numeral);font-size:2.7rem;font-weight:400}.dp56-member-card>p{font-family:var(--font-display);font-size:.76rem;font-weight:900;letter-spacing:.2em}.dp56-member-lines{display:grid;gap:.6rem;margin-top:1.2rem}.dp56-member-lines div{padding-bottom:.5rem;border-bottom:1px dashed rgba(44,24,22,.45)}.dp56-member-lines span{display:block;font-family:var(--font-display);font-size:.52rem;font-weight:900;letter-spacing:.14em}.dp56-member-lines strong{display:block;margin-top:.15rem;font-size:.9rem;text-transform:uppercase}.dp56-member-stamp{position:absolute;right:1.2rem;bottom:2.5rem;display:grid;place-items:center;width:76px;height:76px;border:2px solid #2c1816;border-radius:50%;font-family:var(--font-display);font-size:.7rem;font-weight:900;letter-spacing:.07em;line-height:1;text-align:center;transform:rotate(-10deg)}.dp56-member-card>small{position:absolute;left:1.45rem;bottom:1rem;font-family:var(--font-display);font-size:.5rem;font-weight:900;letter-spacing:.13em}
.dp56-rate-note{padding:1rem 1.1rem;border:1px solid rgba(20,18,16,.22);box-shadow:0 12px 30px rgba(40,30,20,.1);transform:rotate(-.7deg)}.dp56-rate-note span{font-family:var(--font-display);font-size:.55rem;font-weight:900;letter-spacing:.14em;color:#9d3c3a}.dp56-rate-note strong{display:block;margin-top:.2rem;font-family:var(--font-display);font-size:.95rem;letter-spacing:.04em}.dp56-rate-note p{margin:.35rem 0 0;font-size:.78rem;color:rgba(20,18,16,.64)}
.dp56-contact-sheet{display:grid;grid-template-columns:minmax(220px,.6fr) minmax(0,1.4fr);gap:2rem;margin-top:3.5rem;padding:1.6rem 1.8rem;border:1px solid rgba(20,18,16,.22);box-shadow:var(--dp-shadow);transform:rotate(.12deg)}
.dp56-contact-copy>span{font-family:var(--font-display);font-size:.62rem;font-weight:900;letter-spacing:.16em;color:#9d3c3a}.dp56-contact-copy h3{margin:.5rem 0 0;font-size:1.6rem}.dp56-contact-copy p{font-size:.88rem;color:rgba(20,18,16,.66)}
.dp56-contact-fields{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.dp56-contact-fields>div:nth-of-type(3),.dp56-contact-fields>div:nth-of-type(4),.dp56-contact-fields>.form-error,.dp56-contact-fields>.dp56-submit{grid-column:1/-1}.dp56-contact-fields .field,.dp56-contact-fields input,.dp56-contact-fields textarea{background:rgba(255,255,255,.48)}
.dp56-submit{min-height:56px;border:1.5px solid var(--dp-ink);background:var(--dp-ink);color:var(--dp-cream);font-family:var(--font-display);font-size:.76rem;font-weight:900;letter-spacing:.15em;text-transform:uppercase;box-shadow:5px 6px 0 var(--dp-coral)}
.dp56-success{padding:2rem;border:1px solid rgba(20,18,16,.22);box-shadow:var(--dp-shadow)}

.dp56-club-rules{padding:5.5rem 0;color:var(--dp-cream)}
.dp56-rules-band{display:grid;grid-template-columns:repeat(3,1fr);gap:1.25rem}.dp56-rules-band>div{min-height:270px;padding:1.5rem 1.6rem;border:1px solid rgba(242,236,223,.24)}.dp56-rules-band>div:nth-child(2){color:var(--dp-ink);box-shadow:var(--dp-shadow);transform:rotate(-1.2deg)}.dp56-rules-band span{font-family:var(--font-display);font-size:.65rem;font-weight:900;letter-spacing:.14em;color:var(--dp-coral)}.dp56-rules-band strong{display:block;margin-top:4.3rem;font-family:var(--font-numeral);font-size:clamp(3.3rem,5vw,5.6rem);font-weight:400;line-height:.85}.dp56-rules-band p{max-width:290px;margin:.8rem 0 0;color:rgba(242,236,223,.68)}.dp56-rules-band>div:nth-child(2) p{color:rgba(20,18,16,.66)}

.dp56-covered{padding:clamp(5rem,8vw,8rem) 0}.dp56-section-head blockquote{margin:0;font-family:var(--font-display);font-size:clamp(1.45rem,2.2vw,2rem);font-weight:800;line-height:1.3}
.dp56-benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:3rem}.dp56-benefit-grid article,.dp56-benefit-photo{min-height:250px;padding:1.25rem;border:1px solid rgba(20,18,16,.18);box-shadow:0 10px 28px rgba(40,30,20,.08)}.dp56-benefit-grid article span{font-family:var(--font-display);font-size:.6rem;font-weight:900;color:#9d3c3a}.dp56-benefit-grid article h3{margin:3.6rem 0 .5rem;font-size:1.3rem}.dp56-benefit-grid article p{margin:0;font-size:.9rem;color:rgba(20,18,16,.66)}.dp56-benefit-photo{position:relative;grid-column:span 1;padding:10px 10px 34px;transform:rotate(1.1deg)}.dp56-benefit-photo :is(img,picture){width:100%;height:100%;min-height:250px;object-fit:cover}.dp56-benefit-photo figcaption{position:absolute;left:14px;bottom:9px;font-family:var(--font-display);font-size:.54rem;font-weight:900;letter-spacing:.13em}

.dp56-how{padding:clamp(5rem,8vw,8rem) 0}.dp56-how-grid{display:grid;grid-template-columns:minmax(260px,.7fr) minmax(0,1.3fr);gap:clamp(2rem,6vw,6rem);align-items:start}.dp56-how-copy>p:last-child{max-width:380px}.dp56-how-steps{display:grid;gap:1rem}.dp56-how-steps article{position:relative;min-height:160px;padding:1.25rem 1.4rem 1.2rem 5rem;border:1px solid rgba(20,18,16,.22);box-shadow:var(--dp-shadow);transform:rotate(-.35deg)}.dp56-how-steps article:nth-child(2){transform:rotate(.45deg)}.dp56-how-steps article b{position:absolute;left:1.3rem;top:1.25rem;font-family:var(--font-numeral);font-size:2rem;font-weight:400;color:var(--dp-coral)}.dp56-how-steps h3{margin:0;font-size:1.45rem}.dp56-how-steps p{margin:.45rem 0 0;color:rgba(20,18,16,.66)}

.dp56-faq{padding:clamp(5rem,8vw,8rem) 0}.dp56-faq-grid{display:grid;grid-template-columns:minmax(250px,.7fr) minmax(0,1.3fr);gap:clamp(2rem,6vw,6rem)}.dp56-faq-grid>div>p:last-child{margin-top:1.5rem}.dp56-faq a{color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:4px}
.dp56-final{padding:clamp(6rem,10vw,10rem) 0;color:var(--dp-cream);text-align:center}.dp56-final h2{margin:.9rem auto 0;font-family:var(--font-numeral);font-size:clamp(5rem,10vw,10rem);font-weight:400;line-height:.8}.dp56-final>div>p:not(.dp56-kicker){margin:1.4rem auto 1.8rem;color:rgba(242,236,223,.68)}

@media(max-width:980px){
  .dp56-hero{min-height:auto;padding:8rem 0 5rem}.dp56-hero-grid{grid-template-columns:1fr}.dp56-hero-art{min-height:520px;max-width:620px;margin-inline:auto;width:100%}
  .dp56-thesis-grid,.dp56-section-head,.dp56-builder-grid,.dp56-how-grid,.dp56-faq-grid{grid-template-columns:1fr}.dp56-section-head>p{max-width:620px}.dp56-member-stack{position:static;grid-template-columns:1fr 1fr;padding-top:0}.dp56-member-card{min-height:300px}.dp56-rate-note{align-self:end}
  .dp56-rules-band{grid-template-columns:1fr}.dp56-rules-band>div{min-height:200px}.dp56-rules-band strong{margin-top:2.5rem}.dp56-benefit-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:720px){
  .dp56-shell{width:min(100% - 28px,1220px)}.dp56-hero{padding-top:7rem}.dp56-hero-copy h1{font-size:clamp(4.5rem,18vw,6.4rem)}.dp56-hero-actions{align-items:flex-start;flex-direction:column}.dp56-proof-row{gap:.6rem 1rem}
  .dp56-hero-art{min-height:460px}.dp56-polaroid{right:0;width:78%}.dp56-polaroid :is(img,picture){height:330px}.dp56-club-card{left:0;width:82%;min-height:220px}.dp56-paper-tag{display:none}
  .dp56-thesis-grid h2,.dp56-section-head h2,.dp56-faq h2,.dp56-how h2{font-size:clamp(3.6rem,15vw,5rem)}.dp56-compare{grid-template-columns:1fr}.dp56-compare-card ol{grid-template-columns:1fr 1fr}.dp56-compare-card li:nth-child(2){border-right:0}
  .dp56-cadence-grid{grid-template-columns:1fr 1fr}.dp56-cadence-ticket{min-height:120px}.dp56-week-strip{grid-template-columns:repeat(7,1fr)}.dp56-week{min-height:48px}.dp56-subchoices{grid-template-columns:1fr}.dp56-member-stack{grid-template-columns:1fr}.dp56-contact-sheet{grid-template-columns:1fr;padding:1.25rem}.dp56-contact-fields{grid-template-columns:1fr}.dp56-contact-fields>*{grid-column:1!important}
  .dp56-benefit-grid{grid-template-columns:1fr}.dp56-rules-band strong{font-size:4rem}.dp56-final h2{font-size:clamp(4.5rem,18vw,7rem)}
}
@media(max-width:440px){.dp56-cadence-grid{grid-template-columns:1fr}.dp56-hero-art{min-height:410px}.dp56-polaroid{width:88%}.dp56-club-card{width:92%}}
@media(prefers-reduced-motion:reduce){.dp56-cadence-ticket,.dp56-btn{transition:none}.dp56-cadence-ticket:hover,.dp56-btn:hover{transform:none}}

/* Detail+ builder also appears on /detailplus/join, so keep its material tokens local. */
.dp56-builder-form{
  --dp-cream:#f2ecdf;
  --dp-cream-2:#e7dece;
  --dp-ink:#141210;
  --dp-coral:#d56865;
  --dp-red:#b83e43;
  --dp-line:rgba(20,18,16,.2);
  --dp-shadow:0 2px 2px rgba(32,22,15,.12),0 12px 28px rgba(32,22,15,.14),0 28px 70px rgba(32,22,15,.12);
}
.dp56-how .dp56-kicker{color:var(--dp-ink)}
.dp56-how h2 span{color:var(--dp-cream)}

/* ============================================================
   V57 Paint Lab
   High-ticket paint care art direction: inspection, process,
   workshop tickets, technical proof, and consultative conversion.
   ============================================================ */
.pl57-page{
  --pl57-cream:#f2ecdf;
  --pl57-cream2:#e7ddcb;
  --pl57-ink:#12100e;
  --pl57-red:#d56865;
  --pl57-red-deep:#a83e3e;
  --pl57-ox:#5b1716;
  --pl57-line:rgba(18,16,14,.2);
  --pl57-shadow:0 2px 2px rgba(23,14,8,.14),0 14px 34px rgba(23,14,8,.16),0 38px 86px rgba(23,14,8,.12);
  overflow-x:clip;
  background:var(--pl57-ink);
  color:var(--pl57-cream);
}
.pl57-shell{width:min(1260px,calc(100% - 44px));margin-inline:auto}
.pl57-kicker{margin:0;font-family:var(--font-display);font-size:.72rem;font-weight:900;letter-spacing:.2em;text-transform:uppercase;color:var(--pl57-red)}
.pl57-kicker.dark{color:#843b37}
.pl57-section-head{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(290px,.65fr);gap:clamp(2.5rem,6vw,6rem);align-items:end;margin-bottom:clamp(2.5rem,4.5vw,4.5rem)}
.pl57-section-head h2,.pl57-process-intro h2,.pl57-ceramic-copy h2,.pl57-layers h2,.pl57-trust-head h2,.pl57-faq h2,.pl57-final h2{margin:.65rem 0 0;font-family:var(--font-display);font-size:clamp(3.3rem,6vw,6.7rem);font-weight:900;line-height:.84;letter-spacing:-.055em;text-transform:uppercase}
.pl57-section-head h2 span,.pl57-process-intro h2 span,.pl57-ceramic-copy h2 span,.pl57-layers h2 span,.pl57-trust-head h2 span,.pl57-final h2 span{color:var(--pl57-red)}
.pl57-section-head>p:last-child{max-width:520px;margin:0;color:rgba(18,16,14,.66);font-size:1.03rem;line-height:1.65}
.pl57-section-head-light>p:last-child{color:rgba(242,236,223,.68)}
.pl57-section-head-dark{color:var(--pl57-ink)}

/* Paint Lab status */
.pl57-status{position:fixed;right:18px;top:122px;z-index:35;display:flex;gap:.6rem;align-items:center;padding:.58rem .75rem;border:1px solid rgba(242,236,223,.26);background:rgba(10,9,8,.74);color:var(--pl57-cream);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);box-shadow:0 10px 30px rgba(0,0,0,.2);pointer-events:none}
.pl57-status span,.pl57-status b{font-family:var(--font-display);font-size:.62rem;letter-spacing:.15em;text-transform:uppercase}
.pl57-status span{color:rgba(242,236,223,.55)}.pl57-status b{color:var(--pl57-red)}

/* Hero */
.pl57-hero{position:relative;isolation:isolate;min-height:92svh;display:flex;align-items:end;padding:clamp(9rem,15vh,12rem) 0 clamp(4rem,7vh,6.5rem);overflow:hidden;background:#090807}
.pl57-hero-photo,.pl57-hero-shade{position:absolute;inset:0;z-index:-2}.pl57-hero-photo{background:url('/images/hq-black-suv-grille.webp') 68% center/cover no-repeat;transform:scale(1.025)}
.pl57-hero-shade{z-index:-1;background:radial-gradient(ellipse 65% 72% at 76% 48%,rgba(255,255,255,.02),transparent 65%),linear-gradient(90deg,rgba(7,6,5,.96) 0%,rgba(7,6,5,.85) 44%,rgba(7,6,5,.34) 72%,rgba(7,6,5,.16) 100%),linear-gradient(0deg,rgba(0,0,0,.7),transparent 52%)}
.pl57-hero-grid{display:grid;grid-template-columns:minmax(0,1.22fr) minmax(330px,.55fr);gap:clamp(3rem,7vw,7rem);align-items:end}
.pl57-hero-copy h1{margin:.8rem 0 1.35rem;max-width:930px;font-family:var(--font-display);font-size:clamp(5rem,8.5vw,9.4rem);font-weight:900;line-height:.78;letter-spacing:-.065em;text-transform:uppercase;color:var(--pl57-cream)}
.pl57-hero-copy h1 span{color:var(--pl57-red)}
.pl57-hero-lede{max-width:620px;margin:0;color:rgba(242,236,223,.76);font-size:clamp(1rem,1.35vw,1.2rem);line-height:1.6}
.pl57-hero-actions{display:flex;align-items:center;gap:1.25rem;margin-top:1.8rem}.pl57-primary-btn,.pl57-ticket-btn,.pl57-final-btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:.8rem 1.1rem;border:2px solid var(--pl57-ink);background:var(--pl57-red);color:#fff;font-family:var(--font-display);font-size:.74rem;font-weight:900;letter-spacing:.14em;text-decoration:none;text-transform:uppercase;box-shadow:5px 5px 0 var(--pl57-ink);transition:transform .18s var(--ease-out),box-shadow .18s var(--ease-out)}
.pl57-primary-btn:hover,.pl57-final-btn:hover{transform:translate(-2px,-2px);box-shadow:7px 7px 0 var(--pl57-ink)}
.pl57-hero .pl57-primary-btn{border-color:var(--pl57-cream);box-shadow:5px 5px 0 rgba(0,0,0,.75)}.pl57-hero .pl57-primary-btn:hover{box-shadow:7px 7px 0 rgba(0,0,0,.75)}
.pl57-hero-link{color:var(--pl57-cream);font-family:var(--font-display);font-size:.72rem;font-weight:900;letter-spacing:.12em;text-decoration:none;border-bottom:1px solid rgba(242,236,223,.4);padding-bottom:.35rem}
.pl57-hero-proof{display:flex;flex-wrap:wrap;gap:.65rem 1.4rem;margin-top:2rem;padding-top:1rem;border-top:1px solid rgba(242,236,223,.2);color:rgba(242,236,223,.56);font-family:var(--font-display);font-size:.63rem;font-weight:850;letter-spacing:.09em}.pl57-hero-proof b{color:var(--pl57-cream)}
