.pl57-inspection-tag{position:absolute;padding:.45rem .55rem;background:rgba(9,8,7,.72);border:1px solid rgba(242,236,223,.25);color:var(--pl57-cream);font-family:var(--font-display);font-size:.58rem;font-weight:900;letter-spacing:.13em;backdrop-filter:blur(8px)}.pl57-inspection-tag-a{top:1rem;left:1rem}.pl57-inspection-tag-b{top:1rem;right:1rem}.pl57-inspection-hint{position:absolute;left:1rem;bottom:.85rem;margin:0;color:rgba(242,236,223,.7);font-size:.78rem}
