.pl57-plan-options{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pl57-plan-option{display:grid;grid-template-columns:auto 1fr;gap:.15rem 1rem;min-height:188px;padding:1.35rem;border:2px solid rgba(18,16,14,.17);color:var(--pl57-ink);text-align:left;box-shadow:0 6px 18px rgba(31,20,12,.08);transition:transform .2s var(--ease-out),border-color .18s ease,box-shadow .2s ease}.pl57-plan-option:nth-child(2){transform:rotate(.5deg)}.pl57-plan-option:nth-child(3){transform:rotate(-.4deg)}.pl57-plan-option:hover{border-color:rgba(18,16,14,.55);transform:translateY(-3px)}.pl57-plan-option.is-on{border-color:var(--pl57-ink);box-shadow:6px 6px 0 var(--pl57-ink);transform:translate(-2px,-2px)}.pl57-plan-no{grid-row:1 / span 3;font-family:var(--font-display);font-size:1.3rem;font-weight:900;color:var(--pl57-red)}.pl57-plan-label{font-family:var(--font-display);font-size:.63rem;font-weight:900;letter-spacing:.13em;text-transform:uppercase;color:#813b37}.pl57-plan-option strong{display:block;font-family:var(--font-display);font-size:clamp(1.3rem,2vw,1.85rem);line-height:1.02;text-transform:uppercase}.pl57-plan-option small{display:block;margin-top:.35rem;color:rgba(18,16,14,.62);font-size:.85rem;line-height:1.45}
.pl57-plan-result{position:sticky;top:128px;padding:1.45rem 1.5rem 1.5rem;border:2px solid var(--pl57-ink);color:var(--pl57-ink);box-shadow:10px 10px 0 var(--pl57-red-deep);transform:rotate(.65deg)}.pl57-plan-stamp{position:absolute;right:1.1rem;top:-14px;padding:.45rem .6rem;background:var(--pl57-red);color:#fff;font-family:var(--font-display);font-size:.55rem;font-weight:900;letter-spacing:.12em;transform:rotate(2deg)}.pl57-mini-label{margin:0;color:#85423e;font-family:var(--font-display);font-size:.58rem;font-weight:900;letter-spacing:.14em}.pl57-plan-result h3{margin:1rem 0 .8rem;padding-bottom:.8rem;border-bottom:2px solid var(--pl57-ink);font-family:var(--font-display);font-size:clamp(2.2rem,3.8vw,3.8rem);line-height:.88;text-transform:uppercase}.pl57-plan-path{display:flex;flex-wrap:wrap;gap:.45rem;margin:.8rem 0}.pl57-plan-path span{font-family:var(--font-display);font-size:.67rem;font-weight:900;letter-spacing:.09em}.pl57-plan-path i{margin-left:.45rem;font-style:normal;color:var(--pl57-red)}.pl57-plan-result>p:not(.pl57-mini-label):not(.pl57-plan-fine){margin:1rem 0;color:rgba(18,16,14,.68);line-height:1.55}.pl57-plan-price{display:flex;align-items:end;gap:.65rem;margin:1.2rem 0 0;padding-top:1rem;border-top:1px dashed rgba(18,16,14,.3)}.pl57-plan-price small{padding-bottom:.4rem;font-family:var(--font-display);font-size:.58rem;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.pl57-plan-price strong{font-family:var(--font-display);font-size:3.3rem;line-height:.8}.pl57-plan-fine{margin:.75rem 0 0;color:rgba(18,16,14,.52);font-size:.74rem;line-height:1.45}.pl57-plan-actions{display:grid;gap:.8rem;margin-top:1.25rem}.pl57-plan-actions .pl57-primary-btn{width:100%}.pl57-plan-actions>a:last-child{color:var(--pl57-ink);font-size:.8rem;font-weight:800;text-align:center;text-decoration:underline;text-underline-offset:4px}

/* Process sheets */
