.pl57-process-intro{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(300px,.62fr);gap:clamp(3rem,7vw,7rem);align-items:end;margin-bottom:3rem}.pl57-process-intro>p:last-child{max-width:510px;margin:0;color:rgba(242,236,223,.64);line-height:1.65}
