/* Ceramic chapter */
.pl57-ceramic{padding:clamp(5rem,8vw,8rem) 0;color:var(--pl57-cream)}
.pl57-ceramic-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,.72fr);gap:clamp(3rem,8vw,8rem);align-items:center}.pl57-ceramic-copy>p:not(.pl57-kicker){max-width:590px;margin:1.3rem 0 0;color:rgba(242,236,223,.65);line-height:1.65}.pl57-ceramic-traits{display:flex;flex-wrap:wrap;gap:.55rem;margin-top:1.6rem}.pl57-ceramic-traits span{padding:.52rem .64rem;border:1px solid rgba(242,236,223,.28);font-family:var(--font-display);font-size:.6rem;font-weight:900;letter-spacing:.12em}.pl57-gloss-panel{position:relative;min-height:420px;padding:1.6rem;display:flex;flex-direction:column;justify-content:flex-end;overflow:hidden;border:1px solid rgba(242,236,223,.22);background:radial-gradient(circle at 72% 24%,rgba(213,104,101,.26),transparent 22%),linear-gradient(145deg,#1d1d1b 0%,#050505 58%,#1a1413 100%);box-shadow:0 26px 70px rgba(0,0,0,.38);isolation:isolate}.pl57-gloss-panel:before{content:"";position:absolute;inset:-40% -20%;z-index:-1;background:linear-gradient(102deg,transparent 36%,rgba(255,255,255,.12) 48%,rgba(255,255,255,.025) 53%,transparent 62%);transform:rotate(-8deg)}.pl57-gloss-orb{position:absolute;right:14%;top:16%;width:140px;height:140px;border-radius:50%;border:1px solid rgba(255,255,255,.22);box-shadow:inset -18px -18px 40px rgba(0,0,0,.48),inset 15px 12px 30px rgba(255,255,255,.08),0 20px 50px rgba(0,0,0,.32)}.pl57-gloss-label{position:absolute;left:1.5rem;top:1.5rem;font-family:var(--font-display);font-size:.6rem;font-weight:900;letter-spacing:.14em;color:var(--pl57-red)}.pl57-gloss-panel strong{font-family:var(--font-display);font-size:clamp(2.4rem,4vw,4.2rem);line-height:.87;letter-spacing:-.04em}.pl57-gloss-panel p{max-width:410px;margin:.9rem 0 0;color:rgba(242,236,223,.62);font-size:.87rem;line-height:1.55}.pl57-truth-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin-top:3rem;background:rgba(242,236,223,.18);border:1px solid rgba(242,236,223,.18)}.pl57-truth-grid>div{display:grid;gap:0;padding:1.4rem 1.6rem;background:rgba(8,7,6,.62)}.pl57-truth-grid p{margin:0 0 .45rem;color:var(--pl57-red);font-family:var(--font-display);font-size:.62rem;font-weight:900;letter-spacing:.14em}.pl57-truth-grid span{display:block;padding:.7rem 0;border-top:1px solid rgba(242,236,223,.15);color:rgba(242,236,223,.68);font-size:.88rem;line-height:1.5}

/* Layer diagram */
.pl57-layers{padding:clamp(5rem,8vw,8rem) 0;color:var(--pl57-ink)}.pl57-layers-grid{display:grid;grid-template-columns:minmax(0,.85fr) minmax(420px,1fr);gap:clamp(3rem,8vw,8rem);align-items:center}.pl57-layers-grid>div:first-child>p:last-child{max-width:560px;margin:1.4rem 0 0;color:rgba(18,16,14,.66);line-height:1.65}.pl57-layer-diagram{display:grid;gap:8px;perspective:800px}.pl57-layer-diagram>div{display:grid;grid-template-columns:52px 1fr;gap:.25rem 1rem;align-items:center;min-height:112px;padding:1.15rem 1.3rem;border:2px solid var(--pl57-ink);box-shadow:6px 8px 0 rgba(18,16,14,.12);transform-origin:center left}.pl57-layer-diagram>div:nth-child(1){background:#181716;color:var(--pl57-cream);transform:translateX(7%) rotate(-.3deg)}.pl57-layer-diagram>div:nth-child(2){background:var(--pl57-red);color:#fff;transform:translateX(3%)}.pl57-layer-diagram>div:nth-child(3){background:#d1c1aa;color:var(--pl57-ink);transform:rotate(.3deg)}.pl57-layer-diagram span{grid-row:1 / span 2;font-family:var(--font-display);font-size:2.1rem;font-weight:900;opacity:.62}.pl57-layer-diagram strong{font-family:var(--font-display);font-size:1.25rem;letter-spacing:.03em}.pl57-layer-diagram small{font-size:.82rem;opacity:.7}

/* Work tickets */
.pl57-tickets{padding:clamp(5rem,8vw,8rem) 0;background:#e7dece;color:var(--pl57-ink)}.pl57-ticket-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.pl57-work-ticket{display:flex;flex-direction:column;min-height:100%;padding:1.45rem 1.4rem 1.5rem;border:2px solid var(--pl57-ink);color:var(--pl57-ink);box-shadow:var(--pl57-shadow);transform:rotate(-.35deg)}.pl57-work-ticket:nth-child(2){transform:rotate(.45deg) translateY(12px)}.pl57-work-ticket:nth-child(3){transform:rotate(-.15deg)}.pl57-work-ticket.is-featured{background-color:#e6b3a7;box-shadow:10px 10px 0 var(--pl57-ox),var(--pl57-shadow)}.pl57-ticket-top{display:flex;justify-content:space-between;gap:1rem;padding-bottom:.75rem;border-bottom:2px solid var(--pl57-ink);font-family:var(--font-display);font-size:.58rem;font-weight:900;letter-spacing:.12em}.pl57-ticket-top b{color:#8b3c38}.pl57-work-ticket h3{margin:1.5rem 0 .7rem;font-family:var(--font-display);font-size:clamp(2rem,3vw,3.2rem);line-height:.9;text-transform:uppercase}.pl57-ticket-best{min-height:4.6em;margin:0;color:rgba(18,16,14,.65);font-size:.88rem;line-height:1.52}.pl57-ticket-price{display:flex;align-items:end;gap:.6rem;margin:1.35rem 0}.pl57-ticket-price small{padding-bottom:.38rem;font-family:var(--font-display);font-size:.57rem;font-weight:900;letter-spacing:.12em}.pl57-ticket-price strong{font-family:var(--font-display);font-size:3.2rem;line-height:.8}.pl57-work-ticket ul{margin:0 0 1.5rem;padding:0;list-style:none;border-top:1px dashed rgba(18,16,14,.3)}.pl57-work-ticket li{padding:.68rem 0;border-bottom:1px dashed rgba(18,16,14,.24);font-size:.82rem;line-height:1.4}.pl57-work-ticket li:before{content:"✓";margin-right:.55rem;color:#8b3c38;font-weight:900}.pl57-ticket-btn{margin-top:auto;background:transparent;color:var(--pl57-ink);box-shadow:none}.pl57-ticket-btn:hover{background:var(--pl57-ink);color:var(--pl57-cream)}.pl57-work-ticket .pl57-primary-btn{margin-top:auto}.pl57-ticket-fine{margin:.8rem 0 0;color:rgba(18,16,14,.5);font-size:.7rem;line-height:1.4}

/* Trust */
.pl57-trust{padding:clamp(5rem,8vw,8rem) 0;background:#11100e;color:var(--pl57-cream)}.pl57-trust-head{display:grid;grid-template-columns:1fr minmax(300px,.56fr);gap:clamp(3rem,8vw,8rem);align-items:end;margin-bottom:3rem}.pl57-trust-head>p{margin:0;color:rgba(242,236,223,.62);line-height:1.65}.pl57-trust-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(390px,.82fr);gap:clamp(3rem,7vw,7rem);align-items:center}.pl57-trust-list{border-top:1px solid rgba(242,236,223,.2)}.pl57-trust-list article{display:grid;grid-template-columns:54px 1fr;gap:1rem;padding:1.35rem 0;border-bottom:1px solid rgba(242,236,223,.2)}.pl57-trust-list article>span{font-family:var(--font-display);font-size:1.2rem;font-weight:900;color:var(--pl57-red)}.pl57-trust-list h3{margin:0 0 .35rem;font-family:var(--font-display);font-size:1.35rem;letter-spacing:.03em}.pl57-trust-list p{max-width:610px;margin:0;color:rgba(242,236,223,.6);font-size:.9rem;line-height:1.55}.pl57-photo-stack{position:relative;min-height:580px}.pl57-photo-stack figure{position:absolute;margin:0;overflow:hidden;border:8px solid var(--pl57-cream);background:#333;box-shadow:0 22px 55px rgba(0,0,0,.42)}.pl57-photo-stack img{object-fit:cover}.pl57-photo-a{right:0;top:0;width:78%;aspect-ratio:4/5;transform:rotate(2.2deg)}.pl57-photo-b{left:0;bottom:0;width:58%;aspect-ratio:4/5;transform:rotate(-4deg)}.pl57-photo-stack>span{position:absolute;right:4%;bottom:4%;padding:.7rem .8rem;background:var(--pl57-red);color:white;font-family:var(--font-display);font-size:.72rem;font-weight:900;line-height:1.05;letter-spacing:.08em;transform:rotate(4deg);box-shadow:4px 4px 0 #000}

/* Consult form */
.pl57-form{padding:clamp(5rem,8vw,8rem) 0;color:var(--pl57-ink)}.pl57-form-banner{display:flex;justify-content:space-between;gap:1rem;margin-bottom:2rem;padding-bottom:.85rem;border-bottom:3px solid var(--pl57-ink);font-family:var(--font-display);font-size:clamp(1.1rem,2vw,1.7rem);font-weight:900;letter-spacing:.08em}.pl57-form-banner b{color:#893d39}.pl57-form .paint-lead-shell{border:2px solid var(--pl57-ink);background:rgba(255,255,255,.24);box-shadow:10px 10px 0 var(--pl57-ink)}

/* FAQ + final */
.pl57-faq{padding:clamp(5rem,7vw,7rem) 0;color:var(--pl57-ink)}.pl57-faq-grid{display:grid;grid-template-columns:.62fr 1fr;gap:clamp(3rem,8vw,8rem);align-items:start}.pl57-faq h2{font-size:clamp(3rem,5vw,5.2rem)}
.pl57-final{padding:clamp(5rem,8vw,8rem) 0;color:var(--pl57-ink);text-align:center;border-top:3px solid var(--pl57-ink)}.pl57-final>div>p{margin:0;font-family:var(--font-display);font-size:.65rem;font-weight:900;letter-spacing:.17em}.pl57-final h2{margin:1rem auto 2rem;font-size:clamp(4rem,8vw,8rem)}.pl57-final h2 span{color:#fff}.pl57-final>div>div{display:flex;justify-content:center;align-items:center;gap:1.2rem;flex-wrap:wrap}.pl57-final>div>div>a:last-child{color:var(--pl57-ink);font-family:var(--font-display);font-size:.72rem;font-weight:900;letter-spacing:.12em;text-decoration:underline;text-underline-offset:4px}

@media(max-width:1000px){
  .pl57-status{display:none}
  .pl57-hero{min-height:auto;padding-top:9rem}.pl57-hero-grid{grid-template-columns:1fr}.pl57-hero-report{max-width:560px;margin-top:1rem;transform:rotate(.5deg)}
  .pl57-section-head,.pl57-process-intro,.pl57-ceramic-grid,.pl57-layers-grid,.pl57-trust-head,.pl57-trust-grid,.pl57-faq-grid{grid-template-columns:1fr}
  .pl57-plan-builder{grid-template-columns:1fr}.pl57-plan-result{position:relative;top:auto}
