  .pl57-section-head h2,.pl57-process-intro h2,.pl57-ceramic-copy h2,.pl57-layers h2,.pl57-trust-head h2,.pl57-faq h2{font-size:clamp(3rem,13vw,4.8rem)}
  .pl57-inspection-stage{aspect-ratio:4/4.4}.pl57-inspection-tag-b{display:none}.pl57-inspection-lamp{background:radial-gradient(circle 115px at var(--pl57-lamp-x) var(--pl57-lamp-y),rgba(255,255,238,.6) 0%,rgba(255,247,226,.2) 38%,transparent 72%)}.pl57-defect-strip{grid-template-columns:1fr 1fr}.pl57-defect-strip span{border-bottom:1px solid rgba(242,236,223,.18)}.pl57-defect-strip span:nth-child(even){border-right:0}.pl57-defect-strip span:last-child{grid-column:1/-1}
  .pl57-plan-options{grid-template-columns:1fr}.pl57-plan-option{min-height:150px}.pl57-plan-result{transform:none;box-shadow:6px 6px 0 var(--pl57-red-deep)}
  .pl57-process-sheet{grid-template-columns:56px 1fr;padding:1.25rem;min-height:165px;margin-top:-6px}.pl57-process-sheet>b{display:none}.pl57-sheet-no{font-size:2.7rem}.pl57-process-sheet:nth-child(n){transform:rotate(0deg)}
