@media(prefers-reduced-motion:reduce){.pl57-plan-option,.pl57-process-sheet,.pl57-work-ticket,.pl57-primary-btn,.pl57-final-btn{transition:none}.pl57-inspection-crosshair,.pl57-inspection-lamp{display:none}.pl57-inspection-image{filter:none}}

/* ============================================================
   V58 Detail+ material restraint pass
   Paper texture is now an accent material, not the whole page.
   Keep it on the hero, member cards, the coral loop, and final close.
   ============================================================ */
.dp56-page{
  background:#f2ecdf;
}
.dp56-thesis{
  background:#f5f0e6;
}
.dp56-builder{
  background:#ebe2d3;
}
.dp56-club-rules{
  background:#151311;
}
.dp56-covered{
  background:#f2ecdf;
}
.dp56-faq{
  background:#e8dfd0;
  border-top:1px solid rgba(20,18,16,.12);
}

/* Clean physical objects: depth comes from stock, edges and shadows, not grain. */
.dp56-polaroid,
.dp56-paper-tag,
.dp56-compare-card,
.dp56-cadence-ticket,
.dp56-slider-sheet,
.dp56-rate-note,
.dp56-contact-sheet,
.dp56-success,
.dp56-benefit-card,
.dp56-benefit-photo,
.dp56-how-card{
