}
.dp56-compare-card{
  border:1px solid rgba(20,18,16,.18);
  box-shadow:0 2px 2px rgba(31,24,17,.09),0 14px 30px rgba(31,24,17,.11),0 30px 60px rgba(31,24,17,.07);
}
.dp56-compare-accent{
  background:#d56865;
  color:#2b1715;
  box-shadow:0 2px 2px rgba(72,34,31,.12),0 15px 32px rgba(72,34,31,.18),0 34px 64px rgba(72,34,31,.12);
}
.dp56-compare-accent li{border-color:rgba(43,23,21,.25)}
.dp56-compare-accent li b{color:#5d211f}

.dp56-cadence-ticket{
  background:#f9f5ed;
  box-shadow:0 1px 2px rgba(40,30,20,.08),0 8px 18px rgba(40,30,20,.07);
}
.dp56-cadence-ticket:hover{
  box-shadow:0 3px 4px rgba(40,30,20,.1),0 14px 26px rgba(40,30,20,.1);
}
.dp56-cadence-ticket.is-selected{
