  box-shadow:0 2px 3px rgba(20,18,16,.18),0 16px 34px rgba(20,18,16,.18),0 34px 64px rgba(20,18,16,.12);
}
.dp56-choice-row button,.dp56-vehicle-select-wrap select{
  background:#f8f3ea;
}
.dp56-rate-note{
  background:#fbf7ee;
  box-shadow:0 1px 2px rgba(40,30,20,.08),0 11px 24px rgba(40,30,20,.08);
}
.dp56-contact-sheet{
  background:#f8f3ea;
  box-shadow:0 2px 3px rgba(40,30,20,.09),0 14px 34px rgba(40,30,20,.1),0 36px 68px rgba(40,30,20,.07);
}
.dp56-success{
  background:#f8f3ea;
}

/* Solid dark club band with one coral card. */
.dp56-rules-band>div{
  background:#151311;
}
.dp56-rules-band>div.dp56-rule-accent{
  background:#d56865;
  color:#2b1715;
  border-color:#d56865;
  box-shadow:0 3px 4px rgba(0,0,0,.12),0 18px 40px rgba(0,0,0,.2);
}
.dp56-rules-band>div.dp56-rule-accent p{color:rgba(43,23,21,.72)}
.dp56-rules-band>div.dp56-rule-accent span{color:#5d211f}

.dp56-benefit-card,.dp56-benefit-photo{
  background:#fbf7ee;
  box-shadow:0 2px 2px rgba(40,30,20,.07),0 12px 26px rgba(40,30,20,.08);
}

/* The coral loop remains one of the deliberate textured moments. */
.dp56-how-card{
  background:#f9f4ea;
  box-shadow:0 2px 3px rgba(72,34,31,.12),0 14px 30px rgba(72,34,31,.16),0 30px 58px rgba(72,34,31,.1);
}

/* The member card remains the tactile collectible object in the clean builder. */
.dp56-member-card{
