/* ─────────────────────────────────────────────
   V66 SITEWIDE CONTEXT
   Session-aware vehicle, service, location + booking continuity.
   ───────────────────────────────────────────── */
.site-journey-pill {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  min-height: 2.85rem;
  padding: .55rem .75rem;
  border: 1px solid rgb(255 255 255 / .28);
  border-radius: 999px;
  background: rgb(10 10 10 / .34);
  color: #fff;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
.site-journey-pill span { font: 700 .63rem/1 var(--font-display); letter-spacing: .1em; opacity: .62; }
.site-journey-pill strong { max-width: 10rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 650 .84rem/1.1 var(--font-display); }
.site-journey-pill i { font-style: normal; opacity: .7; }
.site-shared-menu-detail { border-top: 1px solid rgb(255 255 255 / .12); }

.journey-pill {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 34;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "label icon" "title icon" "meta icon";
  align-items: center;
  min-width: 12rem;
  max-width: min(22rem, calc(100vw - 2rem));
  padding: .8rem .9rem .78rem 1rem;
  border: 1px solid rgb(17 17 17 / .16);
  border-radius: 1rem;
  background: rgb(248 246 240 / .94);
  color: var(--color-ink);
  box-shadow: 0 18px 55px rgb(17 17 17 / .16), 0 2px 8px rgb(17 17 17 / .08);
  backdrop-filter: blur(20px) saturate(130%);
  -webkit-backdrop-filter: blur(20px) saturate(130%);
  text-align: left;
}
.journey-pill > span { grid-area: label; font: 700 .6rem/1 var(--font-display); letter-spacing: .12em; color: var(--color-red); }
.journey-pill > strong { grid-area: title; margin-top: .28rem; font: 650 .94rem/1.12 var(--font-display); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.journey-pill > small { grid-area: meta; margin-top: .18rem; font-size: .73rem; color: rgb(17 17 17 / .58); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.journey-pill > i { grid-area: icon; margin-left: .8rem; font-style: normal; font-size: 1.1rem; }

.journey-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  justify-content: flex-end;
  background: rgb(0 0 0 / .38);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}
.journey-drawer {
  width: min(27rem, 100%);
  height: 100%;
  overflow-y: auto;
  padding: 1.35rem;
  background: #f7f4ed;
  color: var(--color-ink);
  box-shadow: -24px 0 80px rgb(0 0 0 / .18);
}
.journey-drawer-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; padding-bottom: 1.25rem; border-bottom: 1px solid rgb(17 17 17 / .14); }
.journey-drawer-head span,
.journey-block > span,
.journey-recent > span,
.journey-resume > span,
.journey-nudge > span { display: block; font: 700 .67rem/1 var(--font-display); letter-spacing: .12em; color: var(--color-red); }
.journey-drawer-head h2 { margin-top: .4rem; max-width: 18rem; font: 650 1.55rem/1.02 var(--font-display); letter-spacing: -.035em; }
.journey-drawer-head button { width: 2.4rem; height: 2.4rem; border: 1px solid rgb(17 17 17 / .15); border-radius: 999px; background: #fff; font-size: 1.35rem; }
.journey-block { position: relative; padding: 1.15rem 0; border-bottom: 1px solid rgb(17 17 17 / .11); }
.journey-block strong { display: block; margin-top: .38rem; font: 650 1.05rem/1.2 var(--font-display); }
.journey-block small { display: block; margin-top: .25rem; font-size: .84rem; color: rgb(17 17 17 / .6); }
.journey-block button,
.journey-block a { display: inline-flex; margin-top: .55rem; padding: 0; border: 0; background: transparent; color: var(--color-ink); font: 650 .82rem/1.2 var(--font-display); text-decoration: underline; text-decoration-color: var(--color-red); text-underline-offset: 3px; }
.journey-recent,
.journey-resume,
.journey-nudge { margin-top: 1rem; padding: 1rem; border: 1px solid rgb(17 17 17 / .12); border-radius: .8rem; background: rgb(255 255 255 / .58); }
.journey-recent div { display: flex; flex-wrap: wrap; gap: .4rem; margin-top: .65rem; }
.journey-recent button { padding: .48rem .6rem; border: 1px solid rgb(17 17 17 / .13); border-radius: .5rem; background: #fff; font-size: .78rem; }
.journey-resume strong { display: block; margin-top: .35rem; font: 650 .92rem/1.2 var(--font-display); }
.journey-resume a { display: inline-flex; margin-top: .5rem; font-weight: 650; text-decoration: underline; text-decoration-color: var(--color-red); text-underline-offset: 3px; }
.journey-nudge p { margin-top: .45rem; font-size: .86rem; line-height: 1.45; color: rgb(17 17 17 / .7); }
.journey-nudge button { margin-top: .6rem; padding: 0; border: 0; background: transparent; font-weight: 650; text-decoration: underline; text-decoration-color: var(--color-red); text-underline-offset: 3px; }
.journey-primary { display: flex; justify-content: center; margin-top: 1rem; padding: .95rem 1rem; border-radius: .65rem; background: var(--color-ink); color: var(--color-paper); font: 700 .9rem/1 var(--font-display); letter-spacing: .02em; }
.journey-clear { display: block; margin: .85rem auto 0; padding: .3rem; border: 0; background: transparent; color: rgb(17 17 17 / .48); font-size: .77rem; text-decoration: underline; }

.mobile-context-copy { min-width: 0; flex: 1 1 auto; }
.mobile-context-copy span { display: block; font: 700 .58rem/1 var(--font-display); letter-spacing: .11em; color: var(--color-red); }
.mobile-context-copy strong { display: block; margin-top: .2rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 650 .78rem/1.1 var(--font-display); }

@media (max-width: 1180px) {
  .site-journey-pill { display: none; }
}
@media (max-width: 767px) {
  .journey-pill { right: .7rem; bottom: 5.25rem; min-width: 0; width: min(18rem, calc(100vw - 1.4rem)); padding: .65rem .7rem .62rem .8rem; border-radius: .8rem; }
  .journey-pill > small { display: none; }
  .journey-drawer { width: 100%; padding: 1rem 1rem calc(1rem + env(safe-area-inset-bottom)); }
  .mobile-context-bar ~ .journey-pill { bottom: 5.6rem; }
}
@media (min-width: 1181px) {
  .journey-pill { display: none; }
}

