/* Menu owns its own close control. Do not depend on the page header. */
.site-shared-menu-panel{position:fixed!important;overflow:auto!important;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
.site-shared-menu-panel-close{
  position:sticky;
  top:max(10px,env(safe-area-inset-top));
  z-index:8;
  margin:0 18px 0 auto;
  min-width:104px;
  min-height:46px;
  padding:0 .85rem;
  display:flex;
  align-items:center;
