/* Journey sheet: sticky header means Close is never scrolled away. */
.journey-drawer{
  max-height:calc(100svh - max(16px,env(safe-area-inset-top)) - max(16px,env(safe-area-inset-bottom)))!important;
  overflow:auto!important;
