  .bk-actions,.bk-nav,.bk-bottom-actions,.bk-review-actions{padding-bottom:max(8px,env(safe-area-inset-bottom))!important}
  .bk-actions :is(button,a),.bk-nav :is(button,a),.bk-bottom-actions :is(button,a),.bk-review-actions :is(button,a){min-height:48px!important;max-width:100%!important}
