/* V79 Apple-principled quote hierarchy: one visual path, one next decision. */
.q53-page .q79-plan{
  width:min(100%, 980px);
  margin:0 auto;
  padding:clamp(1.5rem,3vw,2.4rem) 0 clamp(2rem,4vw,3rem);
  border-top:1px solid rgba(17,17,17,.7);
  color:#111;
  animation:q79-materialize .38s cubic-bezier(.2,.8,.2,1) both;
}
.q79-plan-head{padding-bottom:clamp(1.25rem,2.5vw,2rem)}
.q79-eyebrow{
  margin:0 0 .8rem;
  color:#a8463f;
  font-family:var(--font-display);
  font-size:.72rem;
  font-weight:750;
  letter-spacing:.09em;
  text-transform:uppercase;
}
.q79-plan-title-row{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:2rem;
}
.q79-plan h2{
  margin:0;
  max-width:12ch;
  font-family:var(--font-display);
  font-size:clamp(3rem,5.1vw,5rem);
  font-weight:650;
  line-height:.96;
  letter-spacing:-.045em;
  text-transform:none;
}
.q79-price{
  flex:0 0 auto;
  padding-bottom:.18rem;
  text-align:right;
}
.q79-price span{
  display:block;
  margin-bottom:.25rem;
  color:#756f68;
  font-size:.68rem;
  font-weight:700;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.q79-price strong{
  display:block;
  font-family:var(--font-display);
  font-size:clamp(2.7rem,4vw,4.25rem);
  font-weight:650;
  line-height:.9;
  letter-spacing:-.045em;
}
.q79-extras{
  margin:.85rem 0 0;
  color:#68625b;
  font-size:.9rem;
  line-height:1.4;
}
.q79-plan-body{
  display:grid;
  grid-template-columns:minmax(0,1.35fr) minmax(220px,.65fr);
  gap:clamp(2rem,5vw,4.5rem);
  padding:clamp(1.4rem,3vw,2.2rem) 0;
  border-top:1px solid rgba(17,17,17,.14);
}
.q79-fit h3,.q79-included>span,.q79-next-copy>span{
  margin:0;
  color:#756f68;
  font-family:var(--font-display);
  font-size:.7rem;
  font-weight:750;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.q79-fit h3{color:#111;font-size:1rem;letter-spacing:-.01em;text-transform:none}
.q79-fit p{
  max-width:62ch;
  margin:.55rem 0 0;
  color:#58534d;
  font-size:1rem;
  line-height:1.58;
}
.q79-included ul{
  list-style:none;
  margin:.65rem 0 0;
  padding:0;
}
.q79-included li{
  position:relative;
  padding:.48rem 0 .48rem 1.15rem;
  border-bottom:1px solid rgba(17,17,17,.1);
  color:#292724;
  font-size:.88rem;
  line-height:1.35;
}
.q79-included li:last-child{border-bottom:0}
.q79-included li::before{
  content:"✓";
  position:absolute;
  left:0;
  color:#a8463f;
  font-weight:800;
}
.q79-next{
  display:grid;
  grid-template-columns:minmax(180px,.52fr) minmax(0,1.48fr);
  gap:clamp(2rem,5vw,4.5rem);
  padding-top:clamp(1.5rem,3vw,2.3rem);
  border-top:1px solid rgba(17,17,17,.7);
}
.q79-next-copy h3{
  margin:.5rem 0 0;
  font-family:var(--font-display);
  font-size:clamp(1.8rem,2.5vw,2.5rem);
  font-weight:650;
  line-height:1;
  letter-spacing:-.035em;
  text-transform:none;
}
.q79-next-copy p{
  max-width:24ch;
  margin:.7rem 0 0;
  color:#6e6861;
  font-size:.84rem;
  line-height:1.45;
}
.q79-timing-options{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:.75rem;
}
.q79-timing-options button{
  min-height:88px;
  padding:1rem 1.05rem;
  border:1px solid rgba(17,17,17,.18);
  border-radius:14px;
  background:rgba(255,255,255,.34);
  color:#111;
  text-align:left;
  transition:transform .12s ease-out, background-color .16s ease-out, border-color .16s ease-out;
}
.q79-timing-options button:hover{
  background:rgba(255,255,255,.66);
  border-color:rgba(17,17,17,.34);
}
.q79-timing-options button:active{transform:scale(.985)}
.q79-timing-options button strong{
  display:block;
  font-family:var(--font-display);
  font-size:.96rem;
  font-weight:650;
  letter-spacing:-.01em;
}
.q79-timing-options button small{
  display:block;
  margin-top:.28rem;
  color:#77716a;
  font-size:.78rem;
  line-height:1.3;
}
@keyframes q79-materialize{
  from{opacity:0;transform:translateY(8px) scale(.995)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
@media(max-width:760px){
  .q53-page .q79-plan{width:100%;padding-left:0;padding-right:0}
  .q79-plan-title-row{display:block}
  .q79-plan h2{max-width:none;font-size:clamp(2.7rem,12vw,4rem)}
  .q79-price{margin-top:1rem;text-align:left}
  .q79-price strong{font-size:clamp(2.5rem,11vw,3.7rem)}
  .q79-plan-body{grid-template-columns:1fr;gap:1.4rem}
  .q79-next{grid-template-columns:1fr;gap:1.2rem}
  .q79-next-copy p{max-width:none}
}
@media(max-width:440px){
  .q79-timing-options{grid-template-columns:1fr}
  .q79-timing-options button{min-height:70px}
}
@media(prefers-reduced-motion:reduce){
  .q53-page .q79-plan{animation:q79-fade .18s ease-out both}
  .q79-timing-options button{transition:none}
  .q79-timing-options button:active{transform:none}
}
@keyframes q79-fade{from{opacity:0}to{opacity:1}}

