/* =========================================================
   V86 READABILITY FIXES
   Scoped corrections only. Do not refactor the existing cascade.
   ========================================================= */

/* Breadcrumbs inherit the hero/page foreground instead of forcing dark text. */
.breadcrumbs{color:inherit}
.breadcrumbs a{color:currentColor;opacity:.62;text-decoration:none}
.breadcrumbs a:hover{opacity:1;text-decoration:underline;text-underline-offset:3px}
.breadcrumbs [aria-current="page"]{color:currentColor;opacity:.88}

/* Services light hero: restore contrast and clear the fixed header. */
.services-v61.info80-page .svc61-hero{padding-top:7.4rem!important}
.services-v61.info80-page .svc61-crumbs{padding-top:0!important;opacity:.72}
.services-v61.info80-page .svc61-lede{color:rgba(17,17,17,.74)!important}
.services-v61.info80-page .info80-facts{color:rgba(17,17,17,.68)!important}
.services-v61.info80-page .info80-facts strong{color:#111!important}
.services-v61.info80-page .info80-facts span{color:rgba(17,17,17,.68)!important}

/* Light-page header chrome should read as intentional, not translucent gray. */
body:has(.services-v61) .site-context-pill,
body:has(.info-form86) .site-context-pill,
body:has(.services-v61) .site-context-pill.is-set,
body:has(.info-form86) .site-context-pill.is-set{
  background:rgba(243,241,236,.94)!important;
  color:#111!important;
  border-color:rgba(17,17,17,.68)!important;
  box-shadow:0 10px 28px rgba(17,17,17,.10)!important;
}
body:has(.services-v61) .site-shared-menu-button,
body:has(.info-form86) .site-shared-menu-button{
  background:rgba(243,241,236,.94)!important;
  color:#111!important;
  border-color:rgba(17,17,17,.68)!important;
  box-shadow:0 10px 28px rgba(17,17,17,.10)!important;
}
body:has(.services-v61) .site-shared-menu-button:hover,
body:has(.services-v61) .site-shared-menu-button[aria-expanded="true"],
body:has(.info-form86) .site-shared-menu-button:hover,
body:has(.info-form86) .site-shared-menu-button[aria-expanded="true"]{
  background:#111!important;color:#f3eddf!important;border-color:#111!important
}

