/* Homepage hero: each word rises independently with a small deterministic
   offset so the lockup assembles quickly rather than appearing as one block. */
.v90-hero-build > span{
  overflow:visible;
}
.v90-hero-word{
  display:inline-block;
  margin-right:.18em;
  font:inherit;
  font-style:normal;
  color:inherit;
  opacity:0;
  transform:translate3d(var(--hero-word-x,0),var(--hero-word-y,64px),0) rotate(var(--hero-word-rot,0deg));
  filter:blur(5px);
  animation:v90HeroWordIn .62s cubic-bezier(.16,1,.3,1) var(--hero-word-delay,0ms) forwards;
  will-change:transform,opacity,filter;
}
.v90-hero-word:last-child{margin-right:0}
@keyframes v90HeroWordIn{
  0%{opacity:0;filter:blur(5px);transform:translate3d(var(--hero-word-x,0),var(--hero-word-y,64px),0) rotate(var(--hero-word-rot,0deg))}
  62%{opacity:1;filter:blur(0);transform:translate3d(0,-5px,0) rotate(0deg)}
  100%{opacity:1;filter:blur(0);transform:translate3d(0,0,0) rotate(0deg)}
}
@media(prefers-reduced-motion:reduce){
  .v90-hero-word{opacity:1;filter:none;transform:none;animation:none}
}

