/* ============================================================
   V99 — SITE-WIDE DEPTH SYSTEM
   Depth is a hierarchy, not decoration:
   flat content -> soft interactive surfaces -> physical objects
   -> hard offset actions / selected states.
   ============================================================ */
:root{
  --ed-depth-surface:
    inset 0 1px 0 rgba(255,255,255,.72),
    0 14px 34px rgba(36,27,22,.065),
    0 3px 8px rgba(36,27,22,.035);
  --ed-depth-surface-hover:
    inset 0 1px 0 rgba(255,255,255,.82),
    0 20px 44px rgba(36,27,22,.095),
    0 5px 12px rgba(36,27,22,.055);
  --ed-depth-surface-lg:
    inset -12px -12px 30px rgba(255,255,255,.24),
    inset 10px 10px 28px rgba(50,38,30,.035),
    0 30px 66px rgba(36,27,22,.115),
    0 8px 18px rgba(36,27,22,.065);
  --ed-depth-object:
    inset 0 1px 0 rgba(255,255,255,.18),
    0 30px 64px rgba(31,22,18,.16),
    0 10px 22px rgba(31,22,18,.10);
  --ed-depth-photo:
    0 28px 55px rgba(25,20,17,.16),
    0 8px 16px rgba(25,20,17,.10);
  --ed-depth-dark:
    inset -12px -12px 30px rgba(255,255,255,.035),
    inset 12px 12px 28px rgba(0,0,0,.20),
    0 32px 72px rgba(25,18,15,.17),
    0 10px 22px rgba(25,18,15,.10);
  --ed-depth-modal:
    inset 0 1px 0 rgba(255,255,255,.82),
    0 36px 100px rgba(0,0,0,.30),
    0 10px 28px rgba(0,0,0,.13);
  --ed-depth-hard:4px 4px 0 #171717;
  --ed-depth-hard-hover:6px 6px 0 #171717;

  /* Existing editorial objects inherit the same depth family. */
  --site-shadow:var(--ed-depth-object);
}

